// Pick a name for a new companion: prefer a race-specific name matching their
// gender, then fall back to the generic pools.
// Asexual races (Namekian, Frost Demon) have a single flat list used for any gender.
function rollCompanionName(gender, race = null) {
    const g = String(gender || '').toLowerCase();
    const genderKey = g === 'male' || g === 'female' ? g : 'neutral';

    const raceTable = COMPANION_NAMES.races[race];
    if (Array.isArray(raceTable)) {
        if (raceTable.length > 0) {
            return raceTable[getRandomInt(raceTable.length) - 1];
        }
    } else if (raceTable && Array.isArray(raceTable[genderKey]) && raceTable[genderKey].length > 0) {
        return raceTable[genderKey][getRandomInt(raceTable[genderKey].length) - 1];
    }

    const pool = COMPANION_NAMES.generic[genderKey] || COMPANION_NAMES.generic.neutral;
    return pool[getRandomInt(pool.length) - 1];
}

// Build a persistent companion record from a recruited enemy participant.
// The companion keeps the stats it was recruited with (the enemy's stat block), rather than
// being re-based to 20% of the owner's current stats.
function createCompanion(p, ownerChar) {
    const pStats = (p && p.stats) || {};
    const base = {};
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(k => {
        const recruited = Number(pStats[k]);
        if (Number.isFinite(recruited) && recruited > 0) {
            base[k] = Math.max(1, Math.round(recruited));
        } else {
            // Fallback if the participant had no stat data: 20% of the owner's stat.
            base[k] = Math.max(1, Math.round(((ownerChar.stats || {})[k] || 0) * 0.2));
        }
    });
    // Give companions an INT so they can craft/gather for you; use their own if known.
    const intRecruited = Number(pStats.int);
    base.int = Number.isFinite(intRecruited) && intRecruited > 0
        ? Math.max(1, Math.round(intRecruited))
        : rollIntelligence(p.race || null);
    return {
        id: `comp_${Date.now().toString(36)}_${Math.floor(Math.random() * 1000)}`,
        // Use the name they revealed when recruited; otherwise roll one.
        name: p.companionName || rollCompanionName(p.gender, p.race),
        race: p.race || null,
        gender: p.gender || null,
        // Hidden alignment persists with the companion (never shown to the player).
        alignment: p.alignment || 'Positive',
        alignmentValue: Number(p.alignmentValue) || 0,
        stats: base,
        bonusStats: { str: 0, dex: 0, con: 0, wil: 0, spi: 0 },
        companionship: 0,
        fatigue: 0,
        restCharges: COMPANION_REST_MAX,
        lastCompanionRestChargeTime: Date.now(),
        age: p.age || 20,
        techniques: getCompanionTechniques(p),
        fightingStyle: p.fightingStyle || null,
        weapon: p.weapon || null,
        weaponAttackMod: p.weaponAttackMod || 0,
        weaponDamageMode: p.weaponDamageMode || null,
        weaponBypass: p.weaponBypass || false,
        weaponDexPenalty: p.weaponDexPenalty || 0,
        armor: p.armor || null,
        armorReduction: Number(p.armorReduction) || 0,
        armorDexReduction: Number(p.armorDexReduction) || 0,
        armorDurability: Number(p.armorDurability) || 0,
        kiAppDamage: p.kiAppDamage || 0,
        flying: p.flying || false,
        kiSense: p.kiSense || false,
        createdAt: new Date().toISOString()
    };
}

// Battle-ready stats for a companion: its own stored base stats + its XP growth.
function getCompanionBattleStats(companion, ownerChar) {
    const stats = {};
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(k => {
        const owned = Number((companion.stats || {})[k]);
        const base = Number.isFinite(owned) && owned > 0
            ? owned
            : Math.max(1, Math.round(((ownerChar.stats || {})[k] || 0) * 0.2));
        const bonus = Number((companion.bonusStats || {})[k]) || 0;
        stats[k] = Math.max(1, base + bonus);
    });
    // Companions have INT too (used for crafting/gathering on your behalf).
    const intOwned = Number((companion.stats || {}).int);
    stats.int = Number.isFinite(intOwned) && intOwned > 0
        ? intOwned
        : rollIntelligence(companion.race || null);
    return stats;
}

// A companion's known techniques, guaranteed to include its fighting style's signature moves.
function getCompanionTechniques(companion) {
    const techniques = Array.isArray(companion.techniques) ? [...companion.techniques] : [];
    const style = companion.fightingStyle;
    const mentor = style && MENTOR_STYLES[style];
    if (mentor && Array.isArray(mentor.moves)) {
        mentor.moves.forEach(move => {
            if (!techniques.includes(move)) techniques.push(move);
        });
    }
    // Cerealian racial technique (they pay the standard cost; others pay double).
    if ((companion.race === 'Cerealian' || companion.mutation === 'Hunter of Legend') && !techniques.includes('Vital Strike')) {
        techniques.push('Vital Strike');
    }
    return techniques;
}

// Remove any technique that belongs to a fighting style other than `fightingStyle`, so a
// character can't keep moves from styles they no longer use. Non-style abilities (Fly, Ki Sense,
// Ki Efficiency, Ki Application, etc.) are kept.
function pruneOffStyleTechniques(techniques, fightingStyle) {
    const others = new Set();
    Object.keys(MENTOR_STYLES).forEach(style => {
        if (style !== fightingStyle) {
            (MENTOR_STYLES[style].moves || []).forEach(m => others.add(m));
        }
    });
    // Removed / non-existent techniques are always dropped.
    others.add('Wolf Slice Fist');
    // Techniques a mentor can teach individually (e.g. Turtle's Pump Up) are kept even if the
    // character isn't currently that fighting style — they were learned, not style-granted.
    const keep = new Set(['Pump Up']);
    return (techniques || []).filter(t => {
        const name = String(typeof t === 'string' ? t : (t.name || t));
        return !others.has(name) || keep.has(name);
    });
}

// Ensure a technique list includes all of the given fighting style's signature moves. If a
// character lost style moves (e.g. when they briefly held another style), this restores them.
function ensureStyleTechniques(techniques, fightingStyle) {
    const techs = Array.isArray(techniques) ? [...techniques] : [];
    if (!fightingStyle) return techs;
    const mentor = MENTOR_STYLES[fightingStyle];
    if (mentor && Array.isArray(mentor.moves)) {
        mentor.moves.forEach(move => { if (!techs.includes(move)) techs.push(move); });
    }
    return techs;
}

// One-time repair: make sure every character/companion has their current style's signature moves
// (runs alongside pruneAllOffStyleTechniques so nothing gets left missing).
function ensureAllStyleTechniques() {
    const users = Object.keys(characterManager.characters || {});
    users.forEach(userId => {
        (characterManager.characters[userId] || []).forEach(character => {
            let changed = false;
            const ensured = ensureStyleTechniques(character.techniques, character.fightingStyle);
            if (ensured.length !== (character.techniques || []).length) {
                character.techniques = ensured;
                changed = true;
            }
            if (Array.isArray(character.companions)) {
                character.companions.forEach(cmp => {
                    const p = ensureStyleTechniques(cmp.techniques, cmp.fightingStyle);
                    if (p.length !== (cmp.techniques || []).length) {
                        cmp.techniques = p;
                        changed = true;
                    }
                });
            }
            if (changed) characterManager.updateCharacter(userId, character.id, { techniques: character.techniques, companions: character.companions });
        });
    });
}

// One-time cleanup: strip off-style techniques from every character/companion so nobody keeps
// moves from a style they don't currently have.
function pruneAllOffStyleTechniques() {
    const users = Object.keys(characterManager.characters || {});
    users.forEach(userId => {
        (characterManager.characters[userId] || []).forEach(character => {
            let changed = false;
            const pruned = pruneOffStyleTechniques(character.techniques, character.fightingStyle);
            if (pruned.length !== (character.techniques || []).length) {
                character.techniques = pruned;
                changed = true;
            }
            if (Array.isArray(character.companions)) {
                character.companions.forEach(cmp => {
                    const p = pruneOffStyleTechniques(cmp.techniques, cmp.fightingStyle);
                    if (p.length !== (cmp.techniques || []).length) {
                        cmp.techniques = p;
                        changed = true;
                    }
                });
            }
            if (changed) characterManager.updateCharacter(userId, character.id, { techniques: character.techniques, companions: character.companions });
        });
    });
}

// Str & Dex weapons that can unlock the Shogun style (Trello "Shogun" card).
const STR_DEX_WEAPONS = new Set(['Sword', 'Katana', 'Nodachi', 'Greatsword', 'Dimension Sword', 'Brave Sword']);
function isStrDexWeapon(weaponType) { return !!weaponType && STR_DEX_WEAPONS.has(weaponType); }

// Finish a combat turn wielding a Str & Dex weapon while an enemy is DOWNED: roll 3d100 vs 257
// to unlock the Shogun style (per the Trello card the save was 295 per enemy killed).
function maybeUnlockShogun(battle, actor) {
    if (!battle || !actor || !actor.userId || isNPC(actor)) return '';
    if (!isStrDexWeapon(actor.weaponType)) return '';
    const enemiesDown = (battle.turnOrder || []).some(p => {
        if (p.userId === actor.userId) return false;
        if (!isNPC(p)) return false;
        return p.isIncapacitated || p.isDead;
    });
    if (!enemiesDown) return '';
    const character = characterManager.getCharacter(actor.userId);
    if (!character || character.fightingStyle === 'Shogun') return '';
    // Shogun requires first mastering the Swordsman style (Trello "Shogun" card).
    if (character.fightingStyle !== 'Swordsman') return '';
    const roll = battle.rollDice(100) + battle.rollDice(100) + battle.rollDice(100);
    if (roll >= 257) {
        const techniques = pruneOffStyleTechniques(getKnownTechniqueNames(character), 'Shogun');
        (MENTOR_STYLES['Shogun'].moves || []).forEach(m => { if (!techniques.includes(m)) techniques.push(m); });
        characterManager.updateCharacter(actor.userId, character.id, { fightingStyle: 'Shogun', techniques });
        return `\n\n🏯 **SHOGUN UNLOCKED!** (3d100 = **${roll}** vs 257) — **${character.name}** has mastered the **Shogun** style!`;
    }
    return '';
}

// Does this entity's race get the "Enhanced Pump Up" variant? (Oni & Hera per the race cards.)
function hasEnhancedPumpUp(entity) {
    const race = entity && entity.race;
    const raceInfo = race && races[race];
    return !!(raceInfo && raceInfo.passives && raceInfo.passives.some(p => p.id === 'enhanced-pump-up'));
}

// Build battle participants for a character's companions (up to 4), fighting alongside them.
// Eligible children (age 6+) fight as companions too.
function buildCompanionRoster(ownerId, ownerChar) {
    const roster = [];
    // Companions with `inBattle === false` are benched and don't follow into battle.
    const companions = getFightCompanions(ownerChar).slice(0, MAX_COMPANIONS);
    companions.forEach((cmp, index) => {
        const isChild = !!cmp.isChild;
        const cStats = isChild ? getChildBattleStats(cmp) : getCompanionBattleStats(cmp, ownerChar);
        const maxHP = calculateHP(cStats.con, cmp.race || null);
        const maxKi = calculateKi(cStats.spi, cmp.race || null);
        roster.push({
            userId: `companion_${ownerId}_${cmp.id}`,
            username: cmp.name,
            isNPC: false,
            isAlly: true,
            ownerUserId: ownerId,
            companionId: cmp.id,
            race: cmp.race || null,
            gender: cmp.gender || null,
            alignment: cmp.alignment || 'Positive',
            alignmentValue: Number(cmp.alignmentValue) || 0,
            powerLevel: characterManager.calculatePowerLevel({
                str: cStats.str, dex: cStats.dex, con: cStats.con, wil: cStats.wil, spi: cStats.spi,
                maxHP, maxKi
            }),
            hp: maxHP,
            ki: maxKi,
            fatigue: 0,
            stats: cStats,
            modBonus: applyPregnancyModPenalty({ dex: -applyWeaponProficiencyReduction(cmp.race, cmp.fightingStyle, parseWeaponType(cmp.weapon || ''), Number(cmp.weaponDexPenalty) || 0) }, cmp, ownerChar),
            kiAppDamage: cmp.kiAppDamage || 0,
            kiEfficiency: false,
            kiApplicationLearned: cmp.race === 'Cerealian' || cmp.mutation === 'Hunter of Legend',
            techniques: getCompanionTechniques(cmp),
            fightingStyle: cmp.fightingStyle || null,
            isChild: isChild,
            weapon: cmp.weapon || null,
            weaponType: parseWeaponType(cmp.weapon || ''),
            weaponAttackMod: cmp.weaponAttackMod || 0,
            weaponDamageMode: cmp.weaponDamageMode || null,
            weaponBypass: cmp.weaponBypass || false,
            weaponConBonus: cmp.weaponConBonus || 0,
            weaponWilBonus: cmp.weaponWilBonus || 0,
            armor: cmp.armor || null,
            armorReduction: Number(cmp.armorReduction) || 0,
            armorDexReduction: Number(cmp.armorDexReduction) || 0,
            flying: cmp.flying || false,
            kiSense: cmp.kiSense || false,
            pseudoImmortality: cmp.pseudoImmortality === true,
            zenkaiExhausted: (cmp.zenkaiExhaustedUntil || 0) > Date.now()
        });
    });
    return roster;
}

// Save a recruited enemy as a companion on the owner's character (max 4).
function persistRecruitAsCompanion(ownerId, p, ownerChar) {
    if (!ownerChar) return '';
    const companions = Array.isArray(ownerChar.companions) ? ownerChar.companions : [];
    if (companions.length >= MAX_COMPANIONS) return '';
    const companion = createCompanion(p, ownerChar);
    // The new companion fought in this battle — roll for technique mastery.
    const masteryText = rollCompanionMastery(companion);
    companions.push(companion);
    characterManager.updateCharacter(ownerId, ownerChar.id, { companions });
    return masteryText;
}

// ---------- Rival System ----------
// A dynamic nemesis who ambushes missions, grows stronger each defeat, and can eventually be
// spared into a companion after 10 successful persuasion checks.
const RIVAL_AMBUSH_CHANCE = 25;   // % chance the active rival ambushes a mission
const RIVAL_CALLOUT_CHANCE = 5;  // % chance your rival calls you out mid-search (1v1)
const RIVAL_GENERATE_CHANCE = 20; // % chance a defeated enemy becomes your rival after a mission win
const RIVAL_RECRUIT_TARGET = 10;  // successful persuasion checks needed to recruit
const RIVAL_MAX_STAT_MULT = 5.5;    // stat multiplier cap (at 30 defeats)
// Once the rival hits max strength (defeats), it stops hunting you and instead rescues you when
// you're in trouble — ambushes become rare, and it shows up as an ally to toss you an item.
const RIVAL_MATURE_DEFEATS = 15;      // defeats needed for the "max strength" rescue behavior
const RIVAL_MATURE_AMBUSH_CHANCE = 5; // % chance a mature rival still ambushes a mission
const RIVAL_RESCUE_HP_PCT = 0.15;     // rescue triggers when a player is at/below 15% HP

// Does this player currently have an active rival?
function hasActiveRival(userId) {
    const char = characterManager.getCharacter(userId);
    return !!(char && char.rival);
}

// Build a persistent rival record from a defeated non-boss enemy participant.
function createRivalFromEnemy(ownerChar, enemy) {
    const baseStats = {};
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(k => {
        baseStats[k] = Math.max(1, Math.round(Number((enemy.stats || {})[k]) || 100));
    });
    return {
        name: rollCompanionName(enemy.gender, enemy.race),
        race: enemy.race || 'Earthling',
        gender: enemy.gender || 'Male',
        baseStats,
        techniques: Array.isArray(enemy.techniques) ? [...enemy.techniques] : [],
        fightingStyle: enemy.fightingStyle || enemy.style || null,
        weapon: enemy.weapon || null,
        weaponType: enemy.weaponType || null,
        weaponAttackMod: enemy.weaponAttackMod || 0,
        weaponDamageMode: enemy.weaponDamageMode || null,
        weaponBypass: enemy.weaponBypass || false,
        weaponDexPenalty: enemy.weaponDexPenalty || 0,
        weaponRank: 0,
        armor: enemy.armor || null,
        armorReduction: Number(enemy.armorReduction) || 0,
        armorDexReduction: Number(enemy.armorDexReduction) || 0,
        armorDurability: Number(enemy.armorDurability) || 0,
        armorRank: 0,
        passives: [],
        defeats: 0,             // rival_defeats (beaten count — lowers the persuasion DC)
        persuasionProgress: 0,  // successful in-battle Talk persuasions (0..RIVAL_RECRUIT_TARGET)
        spares: 0,              // times spared instead of killed (dialogue bonus when persuading)
        createdAt: Date.now()
    };
}

// A rival's stats grow with each defeat (rival_defeats).
function getRivalScaledStats(rival) {
    const mult = Math.min(RIVAL_MAX_STAT_MULT, 1 + 0.12 * (rival.defeats || 0));
    const stats = {};
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(k => {
        stats[k] = Math.max(1, Math.round((rival.baseStats[k] || 100) * mult));
    });
    return stats;
}

// Unique passive abilities unlocked as the rival is beaten repeatedly.
function getRivalPassiveFlags(rival) {
    const d = rival.defeats || 0;
    const flags = { passives: [] };
    if (d >= 1) flags.passives.push('Determined');
    if (d >= 2) flags.passives.push('Battle-Hardened');
    if (d >= 3) { flags.kiSense = true; flags.passives.push('Keen Senses'); }
    if (d >= 5) { flags.flying = true; flags.passives.push('Flight'); }
    if (d >= 7) { flags.kiAppDamage = 5; flags.passives.push('Power Surge'); }
    if (d >= 10) { flags.kiAppDamage = (flags.kiAppDamage || 0) + 5; flags.passives.push('Ruthless'); }
    return flags;
}

// Kill (Permanent) chance grows each defeat: min(30%, defeats * 1%).
function getRivalKillChance(rival) {
    return Math.min(30, (rival.defeats || 0) * 1);
}

// Persuasion DC starts Extremely Hard and drops as the pair fights repeatedly.
function getRivalPersuasionDC(rival) {
    return Math.max(5, 20 - (rival.defeats || 0));
}

// Upgrade the rival's weapon/armor toward higher tiers as it gets beaten.
function upgradeRivalGear(rival) {
    const rank = Math.min(4, Math.floor((rival.defeats || 0) / 2));
    if (rank > (rival.weaponRank || 0)) {
        const weapon = rival.fightingStyle ? rollStyleWeapon(rival.fightingStyle, rank) : rollRandomWeapon(rank);
        rival.weapon = weapon;
        rival.weaponRank = rank;
        const mods = getWeaponMods(weapon);
        if (mods) {
            rival.weaponType = mods.type;
            rival.weaponAttackMod = mods.attackMod;
            rival.weaponDexPenalty = applyWeaponProficiencyReduction(rival.race, rival.fightingStyle, mods.type, mods.dexPenalty);
            rival.weaponDamageMode = mods.damageMode;
            rival.weaponBypass = mods.bypass;
            rival.weaponConBonus = mods.conBonus || 0;
            rival.weaponWilBonus = mods.wilBonus || 0;
        }
    }
    if (rank > (rival.armorRank || 0)) {
        const armor = rollEnemyArmor(rank);
        if (armor) {
            rival.armor = armor.name;
            rival.armorReduction = armor.armorReduction;
            rival.armorDexReduction = armor.armorDexReduction;
            rival.armorDurability = armor.armorDurability;
            rival.armorRank = rank;
        }
    }
}

// Build a battle participant for the active rival (used when it ambushes a mission).
// Note: `armor` is stored as a plain name; rollEnemyArmor returns an object with reduction stats.
function buildRivalParticipant(ownerId, rival, ownerChar) {
    const stats = getRivalScaledStats(rival);
    const flags = getRivalPassiveFlags(rival);
    const maxHP = calculateHP(stats.con, rival.race || null);
    const maxKi = calculateKi(stats.spi, rival.race || null);
    const armor = typeof rival.armor === 'object' && rival.armor
        ? rival.armor
        : { name: rival.armor, armorReduction: rival.armorReduction, armorDexReduction: rival.armorDexReduction, armorDurability: rival.armorDurability };
    return {
        userId: `rival_${ownerId}`,
        username: `⚔️ ${rival.name}`,
        isNPC: true,
        isRival: true,
        rivalOwnerId: ownerId,
        race: rival.race || null,
        gender: rival.gender || null,
        powerLevel: characterManager.calculatePowerLevel({ ...stats, maxHP, maxKi }),
        hp: maxHP,
        ki: maxKi,
        fatigue: 0,
        stats,
        flying: flags.flying || false,
        kiSense: flags.kiSense || false,
        kiAppDamage: flags.kiAppDamage || 0,
        kiEfficiency: false,
        kiApplicationLearned: false,
        techniques: Array.isArray(rival.techniques) ? [...rival.techniques] : [],
        fightingStyle: rival.fightingStyle || null,
        weapon: rival.weapon || null,
        weaponType: rival.weaponType || null,
        weaponAttackMod: rival.weaponAttackMod || 0,
        weaponDamageMode: rival.weaponDamageMode || null,
        weaponBypass: rival.weaponBypass || false,
        weaponConBonus: rival.weaponConBonus || 0,
        weaponWilBonus: rival.weaponWilBonus || 0,
        armor: armor.name || null,
        armorReduction: Number(armor.armorReduction) || 0,
        armorDexReduction: Number(armor.armorDexReduction) || 0,
        armorDurability: Number(armor.armorDurability) || 0,
        modBonus: { dex: -(rival.weaponDexPenalty || 0) }
    };
}

// Build the rescued-rival ALLY participant (appears on the player's side when they're in trouble).
function buildRivalAllyParticipant(ownerId, rival, ownerChar) {
    const stats = getRivalScaledStats(rival);
    const flags = getRivalPassiveFlags(rival);
    const maxHP = calculateHP(stats.con, rival.race || null);
    const maxKi = calculateKi(stats.spi, rival.race || null);
    const armor = typeof rival.armor === 'object' && rival.armor
        ? rival.armor
        : { name: rival.armor, armorReduction: rival.armorReduction, armorDexReduction: rival.armorDexReduction, armorDurability: rival.armorDurability };
    return {
        userId: `rival_rescue_${ownerId}`,
        username: `🛡️ ${rival.name}`,
        isNPC: false,
        isAlly: true,
        isRivalAlly: true,
        rivalOwnerId: ownerId,
        companionId: `rival_rescue_${ownerId}`,
        ownerUserId: ownerId,
        race: rival.race || null,
        gender: rival.gender || null,
        powerLevel: characterManager.calculatePowerLevel({ ...stats, maxHP, maxKi }),
        hp: maxHP,
        ki: maxKi,
        currentHP: maxHP,
        currentKi: maxKi,
        fatigue: 0,
        stats,
        flying: flags.flying || false,
        kiSense: flags.kiSense || false,
        kiAppDamage: flags.kiAppDamage || 0,
        kiEfficiency: false,
        kiApplicationLearned: false,
        techniques: Array.isArray(rival.techniques) ? [...rival.techniques] : [],
        fightingStyle: rival.fightingStyle || null,
        weapon: rival.weapon || null,
        weaponType: rival.weaponType || null,
        weaponAttackMod: rival.weaponAttackMod || 0,
        weaponDamageMode: rival.weaponDamageMode || null,
        weaponBypass: rival.weaponBypass || false,
        weaponConBonus: rival.weaponConBonus || 0,
        weaponWilBonus: rival.weaponWilBonus || 0,
        armor: armor.name || null,
        armorReduction: Number(armor.armorReduction) || 0,
        armorDexReduction: Number(armor.armorDexReduction) || 0,
        armorDurability: Number(armor.armorDurability) || 0,
        modBonus: { dex: -(rival.weaponDexPenalty || 0) }
    };
}

// Mature rival rescue: when a player dips to low HP, their max-strength rival appears as an ally,
// says a line, and tosses a Recovery Capsule (d20 1-19) or a Senzu Bean (d20 20). Once per battle.
function maybeRivalRescues(battle) {
    if (!battle || battle.active === false) return '';
    // Rivals hold off during an active raid.
    if (getRaidActive()) return '';
    // Rivals never rescue during spars or mentor fights.
    if (battle.isSpar || battle.isCompanionSpar || activeMentorFights.has(battle.id)) return '';
    // Only PvE with enemies (no spars/duels).
    if (getEnemyTargets(battle).length === 0) return '';
    if (!battle.rivalRescued) battle.rivalRescued = {};
    let text = '';
    battle.turnOrder.filter(p => !isNPC(p) && !isCompanion(p) && !p.isDead && !p.isIncapacitated && p.userId).forEach(p => {
        if (battle.rivalRescued[p.userId]) return;
        const char = characterManager.getCharacter(p.userId);
        if (!char || !char.rival) return;
        const rival = char.rival;
        if ((rival.defeats || 0) < RIVAL_MATURE_DEFEATS) return;
        const maxHP = p.hp || 1;
        if ((p.currentHP || 0) > maxHP * RIVAL_RESCUE_HP_PCT) return;
        // Already has a rival (enemy or ally) in this fight — no rescue.
        if (battle.turnOrder.some(a => (a.isRival || a.isRivalAlly) && a.rivalOwnerId === p.userId)) return;
        const addedAlly = battle.addParticipant(buildRivalAllyParticipant(p.userId, rival, char));
        // Rescue ally acts after the current turn so it doesn't disrupt the active player's turn.
        addedAlly.initiative = 0;
        battle.turnOrder.sort((a, b) => b.initiative - a.initiative);
        battle.rivalRescued[p.userId] = true;
        const roll = getRandomInt(20);
        const item = roll === 20 ? 'Senzu Bean' : 'Recovery Capsule';
        const inv = Array.isArray(char.inventory) ? char.inventory : [];
        pushStackedItem(inv, item, 1);
        characterManager.updateCharacter(p.userId, char.id, { inventory: inv });
        text += `\n\n🛡️ **${rival.name}** appears at your side!\n"Can't have you dying on me just yet."\n🎁 **${rival.name}** tosses you a **${item}** (d20 = **${roll}**)!\n`;
    });
    return text;
}

// Render one companion's full status (stats + power level) with Spar Train / Dismiss buttons.
function buildCompanionStatus(character, slot) {
    const companions = Array.isArray(character.companions) ? character.companions : [];
    const cmp = companions[slot - 1];
    if (!cmp) return null;
    const stats = getCompanionBattleStats(cmp, character);
    const maxHP = calculateHP(stats.con, cmp.race || null);
    const maxKi = calculateKi(stats.spi, cmp.race || null);
    const pl = characterManager.calculatePowerLevel({
        str: stats.str, dex: stats.dex, con: stats.con, wil: stats.wil, spi: stats.spi,
        maxHP, maxKi
    });
    const genderText = cmp.gender ? `${cmp.gender} ` : '';
    const techText = Array.isArray(cmp.techniques) && cmp.techniques.length > 0 ? cmp.techniques.join(', ') : '(unarmed)';
    const mastery = (cmp.techniqueMastery || {});
    const masteries = Object.keys(mastery).filter(k => (mastery[k] || 0) > 0)
        .map(k => `${k} ${mastery[k]}/5`).join(', ');
    const benched = cmp.inBattle === false;
    const row = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder().setCustomId(`comp_spar_${slot}`).setLabel('🥋 Spar Train').setStyle(ButtonStyle.Primary),
            new ButtonBuilder().setCustomId(`comp_battle_${slot}`).setLabel(benched ? '⛔ Benched' : '⚔️ In Battle').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId(`comp_rest_${slot}`).setLabel('😴 Rest').setStyle(ButtonStyle.Secondary)
        );
    const gearRow = new ActionRowBuilder();
    if (cmp.weapon) {
        gearRow.addComponents(new ButtonBuilder().setCustomId(`comp_unequip_weapon_${slot}`).setLabel('🗡️ Unequip Weapon').setStyle(ButtonStyle.Secondary));
    }
    if (cmp.armor) {
        gearRow.addComponents(new ButtonBuilder().setCustomId(`comp_unequip_armor_${slot}`).setLabel('🛡️ Unequip Armor').setStyle(ButtonStyle.Secondary));
    }
    gearRow.addComponents(new ButtonBuilder().setCustomId(`comp_dismiss_${slot}`).setLabel('🚪 Dismiss').setStyle(ButtonStyle.Danger));
    return {
        content:
            `🤝 **${cmp.name}** — Companion ${slot}/${MAX_COMPANIONS}\n\n` +
            `👤 ${cmp.race || 'Unknown'} ${genderText}| ⚡ PL **${pl.toLocaleString()}**\n` +
            `📊 STR ${stats.str} | DEX ${stats.dex} | CON ${stats.con} | WIL ${stats.wil} | SPI ${stats.spi}\n` +
            `❤️ HP ${maxHP} | 💙 Ki ${maxKi}\n` +
            `😓 Fatigue: ${Math.round(cmp.fatigue || 0)}% | 🔋 Rest: ${cmp.restCharges ?? COMPANION_REST_MAX}/${COMPANION_REST_MAX}\n` +
            `🧠 Techniques: ${techText}\n` +
            (masteries ? `⭐ Technique Mastery: ${masteries}\n` : '') +
            (cmp.weapon ? `⚔️ Weapon: ${cmp.weapon}\n` : '') +
            (cmp.armor ? `🛡️ Armor: ${cmp.armor}\n` : '') +
            (cmp.fightingStyle ? `🥋 Style: ${cmp.fightingStyle}\n` : '') +
            (benched ? `⛔ **Benched** — won't fight in battle.\n` : `⚔️ **Fighting** in battles.\n`) +
            (cmp.sparRefusalThreshold ? `😤 **Upset** — refuses to spar until companionship reaches **${cmp.sparRefusalThreshold}** (currently ${cmp.companionship || 0}).\n` : '') +
            `\n*Companions share 20% of your stats and follow you into battle (up to 4).*`,
        components: [row, gearRow]
    };
}

// Convert a child record into a companion (keeps stats/race/techniques, adds companion fields).
function childToCompanion(child) {
    return {
        ...child,
        id: child.id || `comp_${Date.now().toString(36)}_${Math.floor(Math.random() * 1000)}`,
        age: child.age != null ? child.age : family.getAgeYears(child.birthDate),
        companionship: child.companionship || 0,
        techniques: child.techniques || [],
        techniqueMastery: child.techniqueMastery || {},
        masteryBonus: child.masteryBonus || {},
        fightingStyle: child.fightingStyle || null,
        weapon: child.weapon || null,
        weaponAttackMod: child.weaponAttackMod || 0,
        weaponDexPenalty: child.weaponDexPenalty || 0,
        weaponDamageMode: child.weaponDamageMode || null,
        weaponBypass: child.weaponBypass || false,
        armor: child.armor || null,
        armorReduction: Number(child.armorReduction) || 0,
        armorDexReduction: Number(child.armorDexReduction) || 0,
        armorDurability: Number(child.armorDurability) || 0,
        inBattle: true,
        flying: child.flying || false,
        kiSense: child.kiSense || false,
        isChild: true, // still grows as a child
        isSeed: false
    };
}

// A row of buttons, one per child, to select which child to view.
function childrenSelectionRow(children) {
    const rows = [];
    let current = [];
    children.forEach(c => {
        current.push(new ButtonBuilder()
            .setCustomId(`child_pick_${c.id}`)
            .setLabel((c.race === 'Saibamen' ? '🌱 ' : '') + c.name)
            .setStyle(ButtonStyle.Secondary));
        if (current.length === 5) { rows.push(new ActionRowBuilder().addComponents(...current)); current = []; }
    });
    if (current.length) rows.push(new ActionRowBuilder().addComponents(...current));
    return rows;
}

// Action buttons for a selected child (make companion / feed / disown).
function childActionsRow(childId) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`child_comp_${childId}`).setLabel('🤝 Make Companion').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId(`child_feed_${childId}`).setLabel('🍼 Feed').setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId(`child_disown_${childId}`).setLabel('🚪 Disown').setStyle(ButtonStyle.Danger)
    );
}

// Prev / back-to-list / next navigation for the currently selected child.
function childNavRow(children, currentId) {
    const idx = children.findIndex(c => c.id === currentId);
    if (children.length <= 1) {
        return new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId('child_back_list').setLabel('⬅ Back to List').setStyle(ButtonStyle.Secondary)
        );
    }
    const prevId = children[(idx - 1 + children.length) % children.length].id;
    const nextId = children[(idx + 1) % children.length].id;
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`child_pick_${prevId}`).setLabel('◀ Prev').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('child_back_list').setLabel('⬅ List').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId(`child_pick_${nextId}`).setLabel('Next ▶').setStyle(ButtonStyle.Secondary)
    );
}

// Build the child selection list UI.
function buildChildrenList(character) {
    const children = getChildrenOf(character);
    if (children.length === 0) {
        return { content: "👶 You don't have any children yet!", components: [] };
    }
    let text = `👶 **${character.name}'s Children (${children.length})**\n\n`;
    text += `Tap a child below to see their stats and actions.\n\n`;
    children.forEach((c, i) => {
        const age = family.getAgeYears(c.birthDate);
        const stats = getChildBattleStats(c);
        text += `**${i + 1}. ${c.name}** — ${c.race || 'Unknown'} ${c.gender || ''} | ${age} yr | 💪 STR ${stats.str} DEX ${stats.dex} CON ${stats.con} WIL ${stats.wil} SPI ${stats.spi}\n`;
    });
    return { content: text, components: childrenSelectionRow(children) };
}

// Build the detail view for a specific child with action + nav buttons.
function buildChildDetail(character, childId, actionMsg = '') {
    const children = getChildrenOf(character);
    const child = children.find(c => c.id === childId);
    if (!child) return { content: '❌ That child no longer exists.', components: [] };
    const stats = getChildBattleStats(child);
    const maxHP = calculateHP(stats.con, child.race || null);
    const maxKi = calculateKi(stats.spi, child.race || null);
    const pl = characterManager.calculatePowerLevel({
        str: stats.str, dex: stats.dex, con: stats.con, wil: stats.wil, spi: stats.spi,
        maxHP, maxKi
    });
    const age = family.getAgeYears(child.birthDate);
    const hp = child.currentHP != null ? child.currentHP : maxHP;
    const ki = child.currentKi != null ? child.currentKi : maxKi;
    const alreadyComp = (Array.isArray(character.companions) && character.companions.some(c => c.id === child.id));
    let text = `👶 **${child.name}** — ${child.race || 'Unknown'} ${child.gender || ''}\n`;
    text += `🎂 Age: ${age} yr | ⚡ PL: **${pl.toLocaleString()}**\n`;
    text += `📊 STR ${stats.str} | DEX ${stats.dex} | CON ${stats.con} | WIL ${stats.wil} | SPI ${stats.spi}${stats.int != null ? ` | INT ${stats.int}` : ''}\n`;
    text += `❤️ HP ${hp}/${maxHP} | 💙 Ki ${ki}/${maxKi}\n`;
    if (child.racialAbilities && child.racialAbilities.length) text += `🧬 Abilities: ${child.racialAbilities.join(', ')}\n`;
    if (child.prodigy) text += `⭐ **PRODIGY**\n`;
    if (child.incest) text += `😈 Born of incest (see alignment).\n`;
    if (age < 1 && child.isChild) {
        if (child.nextFeedAt && child.nextFeedAt > Date.now()) {
            text += `🍼 Fed (next in ~${formatDuration(child.nextFeedAt - Date.now())}).\n`;
        } else {
            text += `🍼 **Needs feeding** — a missed feed costs HP!\n`;
        }
    }
    text += `\n${alreadyComp ? '🤝 Already a companion.' : 'Tap an action below.'}`;
    if (actionMsg) text += `\n\n${actionMsg}`;
    return { content: text, components: [childActionsRow(child.id), childNavRow(children, child.id)] };
}

// Reward text for companions gaining stat points alongside the owner.
// Roll for a companion's technique mastery after a fight, using the same d20-vs-20
// chance and +1-on-fail bonus as a player's `/mastery` roll for a technique.
function rollCompanionMastery(cmp) {
    const mastery = cmp.techniqueMastery || {};
    // Never roll a technique that has already hit its mastery cap (5).
    const techniques = getCompanionTechniques(cmp).filter(t => (mastery[t] || 0) < 5);
    if (techniques.length === 0) return '';
    const target = techniques[Math.floor(Math.random() * techniques.length)];
    cmp.techniqueMastery = cmp.techniqueMastery || {};
    cmp.masteryBonus = cmp.masteryBonus || {};
    const bonus = cmp.masteryBonus[target] || 0;
    const roll = getRandomInt(20);
    const total = roll + bonus;
    if (total >= 20) {
        const newLevel = Math.min(5, (cmp.techniqueMastery[target] || 0) + 1);
        cmp.techniqueMastery[target] = newLevel;
        delete cmp.masteryBonus[target];
        return `\n🎲 **${cmp.name}** mastered **${target}** (Mastery ${newLevel}/5)!`;
    } else {
        cmp.masteryBonus[target] = bonus + 1;
        return `\n🎲 **${cmp.name}** studied **${target}** in the fight — **+1** on their next mastery roll.`;
    }
}

function applyCompanionXp(ownerId, ownerChar, statPoints) {
    if (!ownerChar) return '';
    // Only actual COMPANIONS earn XP from a fight. Eligible children who aren't companions
    // (still in ownerChar.children) may fight alongside, but they do NOT gain stats from
    // fighting and do NOT reduce the owner's own stat reward.
    const party = Array.isArray(ownerChar.companions) ? ownerChar.companions.filter(c => c.inBattle !== false) : [];
    if (party.length === 0) return { ownerPoints: statPoints, text: '' };

    const presentCount = party.length;
    const compGain = family.getCompanionshipGain(presentCount, 1);
    let text = '';
    const childUpdated = [];
    const companionUpdated = [];
    party.forEach((cmp) => {
        const share = Math.max(1, Math.round(statPoints * 0.2)); // each companion takes a 20% cut
        // Child stat-growth multiplier: 0% (<6), 15% (6-11), 50% (12-17), 100% (18+).
        let gain = distributeGain(share, ['str', 'dex', 'con', 'wil', 'spi']);
        if (cmp.isChild) {
            const age = family.getAgeYears(cmp.birthDate);
            const mult = family.getChildGrowthMultiplier(age);
            gain = distributeGain(Math.max(0, Math.floor(share * mult)), ['str', 'dex', 'con', 'wil', 'spi']);
        }
        const bonusStats = { ...(cmp.bonusStats || {}) };
        Object.entries(gain).forEach(([stat, value]) => {
            bonusStats[stat] = (bonusStats[stat] || 0) + value;
        });
        // Roll for technique mastery after the fight (same chances as a player).
        const masteryText = rollCompanionMastery(cmp);
        const updated = { ...cmp, bonusStats, companionship: (cmp.companionship || 0) + compGain };
        if (cmp.isChild) childUpdated.push(updated);
        else companionUpdated.push(updated);
        text += `\n🤝 **${cmp.name}** grew — **+${share} stat points**!`;
        text += masteryText;
    });

    // Persist the updated companion (and child) arrays in one write.
    const companions = Array.isArray(ownerChar.companions) ? ownerChar.companions : [];
    const children = Array.isArray(ownerChar.children) ? ownerChar.children : [];
    const updatedCompanions = companions.map(c => companionUpdated.find(u => u.id === c.id) || c);
    const updatedChildren = children.map(c => childUpdated.find(u => u.id === c.id) || c);
    characterManager.updateCharacter(ownerId, ownerChar.id, { companions: updatedCompanions, children: updatedChildren });

    // Owner gets less stat points for themselves with each companion (20% cut each).
    const ownerPoints = Math.max(0, Math.round(statPoints * (1 - 0.2 * presentCount)));
    return { ownerPoints, text, companions: updatedCompanions };
}

// Equip a weapon/armor from the player's inventory onto one of their companions via /give.
// Removes the item from inventory, returns any old equipped gear, and persists the change.
function equipCompanionItem(ownerId, ownerChar, cmp, itemName) {
    if (!ownerChar || !cmp) return '❌ Invalid companion!';
    const inventory = Array.isArray(ownerChar.inventory) ? ownerChar.inventory : [];
    ownerChar.inventory = inventory;
    const entry = inventory.find(i => parseItemName(i).name.toLowerCase() === itemName.toLowerCase());
    if (!entry) return `❌ You don't have **${itemName}** in your inventory!`;
    const name = parseItemName(entry).name;

    // Weapons: retain/roll their ATK mod, inhibiting DEX, damage mode, and bypass.
    const weaponType = (typeof entry === 'object' && entry.weaponType) ? entry.weaponType : parseWeaponType(name);
    if (weaponType) {
        const mods = (typeof entry === 'object' && entry.weaponAttackMod != null)
            ? { attackMod: entry.weaponAttackMod, dexPenalty: entry.weaponDexPenalty || 0, damageMode: entry.weaponDamageMode || 'str', bypass: !!entry.weaponBypass, conBonus: entry.weaponConBonus || 0, wilBonus: entry.weaponWilBonus || 0, type: weaponType }
            : getWeaponMods(name);
        if (!mods) return `❌ Couldn't compute stats for **${name}**!`;
        let swapNote = '';
        if (cmp.weapon) {
            const oldName = parseItemName(cmp.weapon).name;
            pushStackedItem(inventory, oldName, 1);
            swapNote = `\n↩️ **${oldName}** was returned to your inventory.`;
        }
        removeInventoryItems(inventory, name, 1);
        cmp.weapon = name;
        cmp.weaponType = mods.type || weaponType;
        cmp.weaponAttackMod = mods.attackMod;
        cmp.weaponDexPenalty = mods.dexPenalty;
        cmp.weaponDamageMode = mods.damageMode || null;
        cmp.weaponBypass = !!mods.bypass;
        cmp.weaponConBonus = mods.conBonus || 0;
        cmp.weaponWilBonus = mods.wilBonus || 0;
        const buffs = (mods.conBonus || mods.wilBonus) ? `\n💪 While wielded: **+${mods.conBonus || 0} CON** / **+${mods.wilBonus || 0} WIL**` : '';
        persistCompanionEquipment(ownerId, ownerChar, cmp, inventory);
        return `⚔️ Gave **${name}** to **${cmp.name}**!\n\n🎯 Attack mod: **+${mods.attackMod}**\n😅 Inhibiting DEX: **-${mods.dexPenalty}**\n${mods.bypass ? '💥 Bypasses armor!\n' : ''}${mods.damageMode && mods.damageMode !== 'str' ? `📐 Damage mode: ${mods.damageMode}\n` : ''}${buffs}${swapNote}`;
    }

    // Armor: retain/roll its damage reduction, defending-DEX reduction, and durability.
    const isArmor = /Armor/i.test(name) &&
        (/(Light|Medium|Heavy)\s+Armor/i.test(name) ||
         /(Masterwork|Expert|Tempered|Fine|Regular|Bad|Worthless)\s+Armor/i.test(name) ||
         /Rusted Kavacha Armor/i.test(name));
    if (isArmor) {
        const weight = /Light/i.test(name) ? 'Light' : /Heavy/i.test(name) ? 'Heavy' : 'Medium';
        let damageReduction, dexReduction, durability;
        if (typeof entry === 'object' && entry.armorReduction != null) {
            damageReduction = entry.armorReduction;
            dexReduction = entry.armorDexReduction;
            durability = entry.armorDurability;
        } else {
            if (weight === 'Light') { damageReduction = getRandomInt(20); dexReduction = getRandomInt(20) + 15; durability = getRandomInt(30); }
            else if (weight === 'Heavy') { damageReduction = getRandomInt(50); dexReduction = getRandomInt(40) + 30; durability = getRandomInt(60); }
            else { damageReduction = getRandomInt(35); dexReduction = getRandomInt(35) + 20; durability = getRandomInt(45); }
        }
        let swapNote = '';
        if (cmp.armor) {
            const oldName = parseItemName(cmp.armor).name;
            pushStackedItem(inventory, oldName, 1);
            swapNote = `\n↩️ **${oldName}** was returned to your inventory.`;
        }
        removeInventoryItems(inventory, name, 1);
        cmp.armor = name;
        cmp.armorReduction = damageReduction;
        cmp.armorDexReduction = dexReduction;
        cmp.armorDurability = durability;
        persistCompanionEquipment(ownerId, ownerChar, cmp, inventory);
        return `🛡️ Gave **${name}** to **${cmp.name}**!\n\n💥 Damage reduction: **${damageReduction}%**\n😅 Defending DEX reduction: **${dexReduction}%**\n🔩 Durability: **${durability}**${swapNote}`;
    }

    return `❌ **${name}** isn't a weapon or armor you can give to a companion!`;
}

// Persist a companion's equipment change + the player's inventory in one write.
function persistCompanionEquipment(ownerId, ownerChar, cmp, inventory) {
    const companions = Array.isArray(ownerChar.companions) ? ownerChar.companions : [];
    const idx = companions.findIndex(c => c.id === cmp.id);
    if (idx === -1) companions.push(cmp);
    else companions[idx] = cmp;
    characterManager.updateCharacter(ownerId, ownerChar.id, { companions, inventory });
}

// ---------- Family / Procreation / Child Growth (requires ./familySystem) ----------
// Age helpers: 1 in-game year = 1 real-world week; a child's age derives from its birthDate.
function getCharacterAge(character) {
    if (!character) return 0;
    if (character.birthDate) return family.getAgeYears(character.birthDate);
    // Player characters derive current age from the persistent lastAgeCheck timestamp so
    // age is never stale even after long offline periods (aging continues while offline).
    if (character.lastAgeCheck) {
        const now = Date.now();
        return (character.age || 0) + Math.floor((now - character.lastAgeCheck) / family.FAMILY_CONFIG.ageUpIntervalMs);
    }
    return character.age || family.FAMILY_CONFIG.adultAge;
}
function getCompanionAge(companion) {
    if (!companion) return 0;
    if (companion.birthDate) return family.getAgeYears(companion.birthDate);
    return Number(companion.age) || family.FAMILY_CONFIG.adultAge;
}
function isAdultCharacter(character) { return family.isAdult(getCharacterAge(character)); }

function getChildrenOf(character) {
    return Array.isArray(character.children) ? character.children : [];
}
function getCompanionEligibleChildren(ownerChar) {
    // Children age 6+ fight alongside; under-6 stay home. Saibamen are battle-ready from birth.
    return (Array.isArray(ownerChar.children) ? ownerChar.children : [])
        .filter(c => c.isChild && (isSaibamenRace(c.race) || family.isCombatCapableChild(family.getAgeYears(c.birthDate))));
}
function getFightCompanions(ownerChar) {
    const companions = Array.isArray(ownerChar.companions) ? ownerChar.companions.filter(c => c.inBattle !== false) : [];
    return [...companions, ...getCompanionEligibleChildren(ownerChar)];
}
function getChildBattleStats(child) {
    const stats = {};
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(k => {
        const base = child.stats && typeof child.stats[k] === 'number' ? child.stats[k] : 0;
        const bonus = child.bonusStats && typeof child.bonusStats[k] === 'number' ? child.bonusStats[k] : 0;
        stats[k] = Math.max(1, base + bonus);
    });
    // INT for children rolls fresh (no growth track yet).
    if (child.stats && child.stats.int) stats.int = child.stats.int;
    return stats;
}

// A child's max HP (from its CON, including bonusStats) — used when feeding babies.
function getChildMaxHP(child) {
    const stats = getChildBattleStats(child);
    return Math.max(10, calculateHP(stats.con, child.race || null));
}

// Consume one usable food item (not a raw fish) from the player's inventory to feed a baby.
// Returns the food item's name, or null if no food is available.
function takeFoodForBaby(character) {
    const inventory = Array.isArray(character.inventory) ? character.inventory : [];
    const idx = inventory.findIndex(i => {
        const name = parseItemName(i).name;
        return FOOD_ITEMS[name] && !isUncookedFood(i);
    });
    if (idx === -1) return null;
    const name = parseItemName(inventory[idx]).name;
    consumeInventorySlot(inventory, idx);
    character.inventory = inventory;
    return name;
}

// Procreation eligibility (18+ and race must be able to procreate).
function getProcreationEligibility(type, entity) {
    if (!entity) return { ok: false, reason: 'Target not found.' };
    const age = type === 'companion' ? getCompanionAge(entity) : getCharacterAge(entity);
    if (!family.isAdult(age)) return { ok: false, reason: `They must be **18+** (currently ${age}).` };
    if (family.isProcreationIneligibleRace(entity.race)) return { ok: false, reason: `**${entity.race}** cannot procreate.` };
    return { ok: true };
}

// Effective stats of a parent (player, companion, or child) used for the baby's initial stats.
function entityStatsForProcreation(entity, ownerChar) {
    if (!entity) return {};
    if (entity.isChild) return getChildBattleStats(entity);
    if (ownerChar && entity.id && Array.isArray(ownerChar.companions) && ownerChar.companions.some(c => c.id === entity.id)) {
        return getCompanionBattleStats(entity, ownerChar);
    }
    // A player character (or a companion without owner context) → use its own stored stats.
    return { ...(entity.stats || {}) };
}

// A character/companion is "pregnant" while an unresolved pregnancy exists.
function isPregnant(entity, ownerChar) {
    if (!entity) return false;
    if (entity.pregnancy && !entity.pregnancy.resolved) return true;
    if (ownerChar && Array.isArray(ownerChar.companionPregnancies)) {
        return ownerChar.companionPregnancies.some(p => !p.resolved && p.companionId === entity.id);
    }
    return false;
}

// Pregnant mothers suffer -5 to every stat mod while pregnant.
function applyPregnancyModPenalty(modBonus, entity, ownerChar) {
    if (!isPregnant(entity, ownerChar)) return modBonus;
    ['str', 'dex', 'con', 'wil', 'spi', 'int'].forEach(s => { modBonus[s] = (modBonus[s] || 0) - 5; });
    return modBonus;
}
function isCompanionProcreationReady(companion) {
    return family.isCompanionshipEligibleForProcreation(companion.companionship);
}

// Incest: one party is the biological parent of the other.
function isIncestuousPair(a, b) {
    if (!a || !b) return false;
    const aParents = [a.fatherId, a.motherId];
    const bParents = [b.fatherId, b.motherId];
    return aParents.includes(b.id) || bParents.includes(a.id);
}

// Determine which parent becomes the mother: prefer a known female, never a known male.
// Returns 'a' (first parent), 'b' (second parent), or 'none' (no eligible mother).
function resolveMotherGender(aGender, bGender) {
    const ga = String(aGender || '').toLowerCase();
    const gb = String(bGender || '').toLowerCase();
    if (ga === 'female') return 'a';
    if (gb === 'female') return 'b';
    // Neither is known-female. Avoid making a known-male the mother.
    if (ga === 'male' && gb !== 'male') return 'b';
    if (gb === 'male' && ga !== 'male') return 'a';
    if (ga !== 'male' && gb !== 'male') return 'a';
    return 'none';
}

// Child race + racial-ability inheritance.
function isSaibamenRace(race) {
    return race === 'Saibamen' || race === 'Saibaman';
}
function getChildRace(motherRace, fatherRace) {
    const pair = [motherRace, fatherRace];
    // Saibamen release a seed/hatchling of themselves (Trello "Ruler of Many") — takes priority.
    if (pair.some(isSaibamenRace)) return 'Saibamen';
    if (pair.includes('Earthling') && pair.includes('Saiyan')) return 'Half-Saiyan';
    return 'Hybrid';
}
function getChildRacialAbilities(childRace, motherRace, fatherRace) {
    // Children inherit the RACIAL PASSIVES (actual mechanics), not the generic ability tags.
    const passivesOf = (race) => (races[race] && Array.isArray(races[race].passives))
        ? races[race].passives.map(p => p.name) : [];
    if (childRace === 'Half-Saiyan') {
        return passivesOf('Half-Saiyan');
    }
    if (childRace === 'Saibamen') {
        return passivesOf('Saibamen');
    }
    return family.inheritRacialAbilities([motherRace, fatherRace]);
}

// Build a persistent child record.
function createChildObject(opts) {
    const { mother, father, race, gender, siblings, incest, racialAbilities, name } = opts;
    const motherStats = mother.stats || {};
    const fatherStats = father.stats || {};
    let stats;
    let prodigy = false;
    let isSeed = false;
    let seedSproutAt;
    const seedParent = isSaibamenRace(mother.race) ? mother : (isSaibamenRace(father.race) ? father : null);

    if (race === 'Saibamen' && seedParent) {
        // Saibamen are born battle-ready with FULL stats, inheriting 90-95% of the parent's stats.
        const src = seedParent.stats || {};
        stats = {};
        ['str', 'dex', 'con', 'wil', 'spi', 'int'].forEach(k => {
            const inheritPct = 0.90 + (Math.random() * 0.05); // 90% - 95%
            stats[k] = Math.max(1, Math.round((Number(src[k]) || 0) * inheritPct));
        });
        isSeed = false; // no sprout delay — they're born ready
        seedSproutAt = undefined;
    } else {
        // Baby initial stats = average of both parents' stats (rolled per stat).
        const avg = {};
        ['str', 'dex', 'con', 'wil', 'spi', 'int'].forEach(k => {
            const m = typeof motherStats[k] === 'number' ? motherStats[k] : 0;
            const f = typeof fatherStats[k] === 'number' ? fatherStats[k] : 0;
            avg[k] = Math.max(1, Math.round((m + f) / 2));
        });
        // Roll 1d20: on a 20 the baby is a PRODIGY and has 50% higher stats.
        prodigy = family.randInt(20) === 20;
        const prodigyMult = prodigy ? 1.5 : 1;
        const baseStats = {};
        Object.entries(avg).forEach(([k, v]) => { baseStats[k] = Math.max(1, Math.round(v * prodigyMult)); });
        stats = incest ? family.applyIncestStatPenalty(baseStats) : baseStats;
    }
    return {
        id: `child_${Date.now().toString(36)}_${Math.floor(Math.random() * 100000)}`,
        name: name || 'Unnamed',
        race,
        gender,
        birthDate: Date.now(),
        motherId: mother.id,
        motherName: mother.name,
        fatherId: father.id,
        fatherName: father.name,
        custodianId: mother.id,
        custodianUserId: mother.userId,
        siblings,
        racialAbilities: racialAbilities || [],
        stats,
        prodigy: prodigy,
        isSeed: isSeed,
        ...(seedSproutAt ? { seedSproutAt } : {}),
        bonusStats: { str: 0, dex: 0, con: 0, wil: 0, spi: 0 },
        fatigue: 0,
        restCharges: COMPANION_REST_MAX,
        lastCompanionRestChargeTime: Date.now(),
        techniques: [],
        isChild: true,
        incest: !!incest,
        // Half-Saiyans roll 1d2 for a tail at birth (Trello "To Tail or to Not": 1 = no tail, 2 = tail).
        hasTail: race === 'Half-Saiyan' ? (family.randInt(2) === 2) : null,
        alignment: incest ? 'Negative' : 'Neutral',
        alignmentValue: incest ? -family.FAMILY_CONFIG.incestAlignmentDrop : 0,
        nextFeedAt: Date.now() + family.FAMILY_CONFIG.babyFeedingIntervalMs,
        inBattle: false,
        createdAt: new Date().toISOString()
    };
}

// Generate children from a pregnancy record. `pregnancy` carries parent info + incest flag.
function generateChildrenFromPregnancy(pregnancy) {
    const childRace = getChildRace(pregnancy.motherRace, pregnancy.fatherRace);
    const { count } = family.rollChildCount();
    const racialAbilities = getChildRacialAbilities(childRace, pregnancy.motherRace, pregnancy.fatherRace);
    const mother = { id: pregnancy.motherId, name: pregnancy.motherName, userId: pregnancy.motherUserId, stats: pregnancy.motherStats, race: pregnancy.motherRace };
    const father = { id: pregnancy.fatherId, name: pregnancy.fatherName, userId: pregnancy.fatherUserId, stats: pregnancy.fatherStats, race: pregnancy.fatherRace };
    const children = [];
    for (let i = 0; i < count; i++) {
        children.push(createChildObject({
            mother, father, race: childRace,
            gender: family.rollChildGender(),
            siblings: count,
            incest: pregnancy.incest,
            racialAbilities
        }));
    }
    return children;
}

// Resolve any due pregnancies (persistent timestamps guard against duplicate births on restart).
function processPendingBirths() {
    const notices = [];
    const users = Object.keys(characterManager.characters || {});
    users.forEach(userId => {
        const chars = characterManager.characters[userId] || [];
        chars.forEach(character => {
            // Player-as-mother pregnancy.
            if (character.pregnancy && !character.pregnancy.resolved) {
                const p = character.pregnancy;
                if (Date.now() >= p.dueAt) {
                    const children = generateChildrenFromPregnancy({ ...p, motherUserId: userId });
                    p.resolved = true;
                    const all = [...getChildrenOf(character), ...children];
                    characterManager.updateCharacter(userId, character.id, { pregnancy: p, children: all });
                    notices.push(`👶 **${character.name}** gave birth to **${children.length}** child${children.length > 1 ? 'ren' : ''}! Name them with \`/name-child\`.`);
                    queueBirthNotice(userId, `👶 **${character.name}** gave birth to **${children.length}** child${children.length > 1 ? 'ren' : ''}! They're currently **Unnamed** — use \`/name-child\` to name them.`);
                    character = characterManager.getCharacter(userId, character.id) || character;
                }
            }
            // Companion-as-mother pregnancies (each entry is keyed by companionId).
            if (Array.isArray(character.companionPregnancies) && character.companionPregnancies.length > 0) {
                const remaining = [];
                let newChildren = null;
                let updatedComps = null;
                let birthNotices = [];
                character.companionPregnancies.forEach(p => {
                    if (!p.resolved && Date.now() >= p.dueAt) {
                        const children = generateChildrenFromPregnancy({ ...p, motherUserId: userId });
                        p.resolved = true;
                        newChildren = [...(newChildren || getChildrenOf(character)), ...children];
                        const comps = (updatedComps || Array.isArray(character.companions) ? character.companions : []).map(c => ({ ...c }));
                        const idx = comps.findIndex(c => c.id === p.companionId);
                        if (idx !== -1) {
                            comps[idx].lastBirthAt = Date.now();
                            updatedComps = comps;
                        }
                        birthNotices.push(`👶 **${p.motherName}** (companion) gave birth to **${children.length}** child${children.length > 1 ? 'ren' : ''}!`);
                        queueBirthNotice(userId, `👶 **${p.motherName}** (companion) gave birth to **${children.length}** child${children.length > 1 ? 'ren' : ''}! They're currently **Unnamed** — use \`/name-child\` to name them.`);
                    }
                    remaining.push(p);
                });
                if (newChildren || updatedComps) {
                    character.companionPregnancies = remaining;
                    characterManager.updateCharacter(userId, character.id, {
                        children: newChildren || getChildrenOf(character),
                        companionPregnancies: remaining,
                        ...(updatedComps ? { companions: updatedComps } : {})
                    });
                    notices.push(...birthNotices);
                }
            }
        });
    });
    return notices;
}

// Baby feeding: every hour until 1 year old; a missed feeding costs a little HP.
function handleBabyFeeding(userId, character) {
    const children = Array.isArray(character.children) ? character.children : [];
    const babies = children.filter(c => c.isChild && family.getAgeYears(c.birthDate) < 1);
    if (babies.length === 0) return '';
    const now = Date.now();
    const updates = [];
    let changed = false;
    babies.forEach(child => {
        const needBy = (child.nextFeedAt || child.birthDate + family.FAMILY_CONFIG.babyFeedingIntervalMs);
        const missed = Math.floor((now - needBy) / family.FAMILY_CONFIG.babyFeedingIntervalMs);
        if (missed > 0) {
            // Log the missed feedings and schedule the next one.
            child.nextFeedAt = needBy + missed * family.FAMILY_CONFIG.babyFeedingIntervalMs;
            const penalty = missed * family.FAMILY_CONFIG.babyMissedFeedingPenalty;
            child.currentHP = Math.max(1, (child.currentHP || 10) - penalty);
            child.bonusStats = child.bonusStats || {};
            updates.push(`🍼 **${child.name}** missed **${missed}** feeding${missed > 1 ? 's' : ''} and lost **${penalty} HP** (now ${child.currentHP}).`);
            changed = true;
        }
    });
    if (changed) characterManager.updateCharacter(userId, character.id, { children });
    return updates.join('\n');
}

// Run periodically: resolve due births and baby feedings for every character.
function runFamilyTick() {
    const notices = processPendingBirths();
    const users = Object.keys(characterManager.characters || {});
    users.forEach(userId => {
        (characterManager.characters[userId] || []).forEach(character => {
            handleBabyFeeding(userId, character);
        });
    });
    notices.forEach(n => console.log('[family]', n));
    return notices;
}

// In-memory procreation requests (short-lived accept/decline; births use persistent timestamps).
const procreationRequests = new Map();

// Start a pregnancy where a PLAYER character is the mother.
function startPlayerPregnancy(ownerUserId, motherChar, fatherInfo, incest) {
    if (motherChar.pregnancy && !motherChar.pregnancy.resolved) {
        return `❌ **${motherChar.name}** is already pregnant!`;
    }
    motherChar.pregnancy = {
        motherType: 'character',
        motherId: motherChar.id, motherName: motherChar.name, motherRace: motherChar.race, motherUserId: ownerUserId,
        fatherId: fatherInfo.id, fatherName: fatherInfo.name, fatherRace: fatherInfo.race, fatherUserId: fatherInfo.userId,
        motherStats: { ...(motherChar.stats || {}) },
        fatherStats: { ...(fatherInfo.stats || {}) },
        dueAt: Date.now() + family.FAMILY_CONFIG.pregnancyDurationMs,
        resolved: false, incest: !!incest
    };
    characterManager.updateCharacter(ownerUserId, motherChar.id, { pregnancy: motherChar.pregnancy });
    return `🤰 **${motherChar.name}** is now pregnant (a ${motherChar.race} mother)! The baby will arrive in about an in-game day.`;
}

// Start a pregnancy where a COMPANION is the mother (child lives with the player's party).
function startCompanionPregnancy(ownerUserId, ownerChar, motherComp, fatherInfo, incest) {
    const arr = Array.isArray(ownerChar.companionPregnancies) ? ownerChar.companionPregnancies : [];
    if (arr.some(p => !p.resolved && p.companionId === motherComp.id)) {
        return `❌ **${motherComp.name}** is already pregnant!`;
    }
    // Companions have a 1-day cooldown after giving birth (players do not).
    if (motherComp.lastBirthAt) {
        const elapsed = Date.now() - motherComp.lastBirthAt;
        if (elapsed < family.FAMILY_CONFIG.companionBirthCooldownMs) {
            const remaining = family.FAMILY_CONFIG.companionBirthCooldownMs - elapsed;
            return `❌ **${motherComp.name}** recently gave birth — they must wait **${formatDuration(remaining)}** before procreating again!`;
        }
    }
    arr.push({
        motherType: 'companion', companionId: motherComp.id, motherName: motherComp.name, motherRace: motherComp.race, motherUserId: ownerUserId,
        fatherId: fatherInfo.id, fatherName: fatherInfo.name, fatherRace: fatherInfo.race, fatherUserId: fatherInfo.userId,
        motherStats: entityStatsForProcreation(motherComp, ownerChar),
        fatherStats: { ...(fatherInfo.stats || {}) },
        dueAt: Date.now() + family.FAMILY_CONFIG.pregnancyDurationMs,
        resolved: false, incest: !!incest
    });
    characterManager.updateCharacter(ownerUserId, ownerChar.id, { companionPregnancies: arr });
    return `🤰 **${motherComp.name}** (companion) is now pregnant! The baby will arrive in about an in-game day.`;
}

// Incest consequence: the offending parent's alignment drops.
function reduceAlignmentForIncest(userId, character) {
    const alignValue = clampAlignmentValue((getPlayerAlignmentValue(character) || 0) - family.FAMILY_CONFIG.incestAlignmentDrop);
    const alignment = alignValue >= 0 ? 'Positive' : 'Negative';
    characterManager.updateCharacter(userId, character.id, { alignmentValue: alignValue, alignment });
    checkManiacOffer(userId, character);
    return `😈 **${character.name}**'s alignment dropped by **${family.FAMILY_CONFIG.incestAlignmentDrop}** (now ${alignValue}) for procreating with their own child!`;
}

// When a character's alignment is at -900 or lower, offer the Maniac fighting style via DM.
// No mentor — it's offered every time their alignment changes while at/below -900.
function checkManiacOffer(userId, character) {
    if (!character || character.fightingStyle === 'Maniac') return;
    if (character.fightingStyle) return; // Maniac requires having NO fighting style.
    if (getPlayerAlignmentValue(character) > -900) return;
    if (!client || !client.users || !userId) return;
    const row = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('maniac_accept')
                .setLabel('🌀 Become a Maniac')
                .setStyle(ButtonStyle.Danger),
            new ButtonBuilder()
                .setCustomId('maniac_decline')
                .setLabel('🙅 Resist')
                .setStyle(ButtonStyle.Secondary)
        );
    client.users.send(userId, {
        content: `🌀 Your alignment is **${getPlayerAlignmentValue(character)}** — the darkness is calling. Give in to the **Maniac** fighting style?`,
        components: [row]
    }).catch(() => {});
}

// Track the player's last procreation partner (for the companion betrayal check).
function setProcreationPartner(userId, character, partner) {
    character.lastProcreationPartner = { id: partner.id, type: partner.type, name: partner.name, companionship: Number(partner.companionship) || 0 };
    characterManager.updateCharacter(userId, character.id, { lastProcreationPartner: character.lastProcreationPartner });
}

// Betrayal: if the player already has a bonded companion they procreated with, and the new
// procreation target is someone else, roll 1d5. 3+ = companion dismissed (and a pregnancy was
// lost); 2 or less = companion loses all companionship and refuses to spar until it rises back
// to at least 50% of what it was originally.
function resolveCompanionBetrayal(userId, character, newTarget) {
    const prev = character.lastProcreationPartner;
    if (!prev || prev.type !== 'companion') return { text: '' };
    const sameCompanion = newTarget && newTarget.type === 'companion' && newTarget.id === prev.id;
    if (sameCompanion) return { text: '' };

    const cmp = (Array.isArray(character.companions) ? character.companions : []).find(c => c.id === prev.id);
    if (!cmp) return { text: '' };

    const roll = getRandomInt(5);
    if (roll >= 3) {
        const companions = (Array.isArray(character.companions) ? character.companions : []).filter(c => c.id !== cmp.id);
        const pregnancies = Array.isArray(character.companionPregnancies)
            ? character.companionPregnancies.filter(p => !(p.companionId === cmp.id && !p.resolved))
            : [];
        const lostPregnancy = pregnancies.length !== (character.companionPregnancies || []).length;
        characterManager.updateCharacter(userId, character.id, { companions, companionPregnancies: pregnancies, lastProcreationPartner: null });
        return { text: `\n💔 **${cmp.name}** caught your infidelity (1d5 = **${roll}**)! They were **dismissed**.${lostPregnancy ? ' The pregnancy was lost!' : ''}` };
    }

    // Companion stays, but loses all companionship and refuses to spar until it recovers.
    const threshold = Math.max(1, Math.round((prev.companionship || 0) * 0.5));
    cmp.companionship = 0;
    cmp.sparRefusalThreshold = threshold;
    const comps = (Array.isArray(character.companions) ? character.companions : []).map(c => c.id === cmp.id ? cmp : c);
    characterManager.updateCharacter(userId, character.id, { companions: comps });
    return { text: `\n😤 **${cmp.name}** caught your infidelity (1d5 = **${roll}**)!\nThey **lost all companionship** and refuse to spar until it rises back to **${threshold}**.` };
}

// Find a child on a custodian character by name (or by id prefix).
function findChildOnCharacter(character, nameOrId) {
    const children = getChildrenOf(character);
    const q = String(nameOrId || '').trim().toLowerCase();
    return children.find(c => c.id === nameOrId || String(c.name).toLowerCase() === q);
}

// Build the attack event as discrete steps (one line each) so it can be animated.
function buildAttackEventSteps(attackerName, defender, result) {
    const steps = [];
    steps.push(`🎲 **${attackerName}** attacks **${defender.username}**!\n`);
    steps.push(`Attack Roll: **${result.attackRoll}** + DEX mod = **${result.attackTotal}**\n`);
    steps.push(`Defense Roll: **${result.defenseRoll}** + DEX mod = **${result.defenseTotal}**\n`);
    if (result.steadyBase) {
        steps.push('🦩 **Steady Base!** The Taekwondo stays grounded and **negates the Off-Balance**!\n');
    }

    if (result.critical) {
        steps.push('💥 **CRITICAL HIT!** (+5 damage)\n');
    }

    if (result.hit) {
        steps.push('✅ **HIT LANDS!**\n');
        if (result.spiritTiger) {
            steps.push('🐯 **Spirit of the Tiger!** The Tiger takes the hit instead of dodging and forces a WIL save!\n');
            if (result.spiritFrighten) {
                steps.push(`😨 The attacker fails the save and is **FRIGHTENED** for 1 turn!\n`);
            }
        }
        if (result.grappleBroken) {
            steps.push('🤼💨 The grapple is broken!\n');
        }
        steps.push(`Damage: ${result.damageRoll}${result.statMod !== undefined ? ` + ${result.statMod} mod` : ' + mod'}${result.flatBonus ? ` ${result.flatBonus > 0 ? '+' : ''}${result.flatBonus} bonus` : ''} = **${result.damage} damage**\n`);
        if (result.craneMarkBonus) {
            steps.push(`🐦 **Crane's Mark** sears into the wound, adding **+${result.craneMarkBonus} damage**!\n`);
        }
        if (result.turtleTenacity) {
            steps.push(`🐢 **Turtle Tenacity!** Negates **${result.turtleTenacity} damage**${result.turtleAbsorb ? ` and absorbs **${result.turtleAbsorb} Ki**` : ''}!\n`);
        }
        if (result.tempestStrike) {
            steps.push(`🦶 **Wings of the Tempest!** Two kicks land — **${attackerName}** gains a **free third strike** (+DEX mod)!\n`);
        }
        if (result.battlefieldControl) {
            steps.push(`🔱 **Battlefield Control!** The polearm knocks **${defender.username}** **OFF-BALANCE** for 1 turn!\n`);
        }
        if (result.wolfBarrage) {
            steps.push(`🐺 **Swift Onslaught!** The barrage lands **${result.wolfBarrage} strikes** for **${result.damage} damage**!\n`);
        }

        if (result.craneMark) {
            steps.push(`🐦 **Crane's Marking Strike!** **${defender.username}** is MARKED for **${result.craneMark} turn${result.craneMark === 1 ? '' : 's'}** (-10% DEX to attack & defense rolls)!\n`);
        }

        if (result.bleed) {
            steps.push(`🩸 **${defender.username}** starts BLEEDING for **${result.bleed} turn${result.bleed === 1 ? '' : 's'}**!\n`);
        }

        if (result.tigerExtraAction) {
            steps.push(`🐯 **Fearless Strikes!** A **crit** lets **${attackerName}** act again and imposes **disadvantage** on **${defender.username}**!\n`);
        }

        if (result.limbBreakAttempt) {
            const lb = result.limbBreakAttempt;
            steps.push(lb.success
                ? `🦴 **${lb.type.toUpperCase()}!** (${lb.limb})${lb.effects ? ` — ${lb.effects}` : ''}\n`
                : lb.message ? `🛡️ ${lb.message}\n` : '🛡️ Limb break resisted!\n');
        }

        if (result.combatAddicted) {
            steps.push(`🌀 **Combat Addicted!** **${defender.username}** refuses to fall, clawing back to **${defender.currentHP} HP** as the sadism burns away!\n`);
        }

        if (result.knockedOut) {
            steps.push(`💀 **${defender.username} is KNOCKED OUT!**\n`);
        }
    } else if (result.blocked) {
        steps.push('🛡️ **BLOCKED!** (80% damage reduction)\n');
        if (result.grappledTargetHit) {
            steps.push(`🤼 The grappled **${result.grappledTargetHit}** takes the blow instead!\n`);
        } else {
            steps.push(`Damage: ${result.damageRoll}${result.statMod !== undefined ? ` + ${result.statMod} mod` : ' + mod'} × 0.2 = **${result.damage} damage**\n`);
        }
        if (result.ironBone) {
            steps.push(`🦴 **Iron Bone Conditioning!** The Tiger's bones absorb the blow and reflect **${result.ironBone} damage** back at **${attackerName}**!\n`);
        }
        if (result.shellGuard) {
            steps.push(`🐢 **Shell Guard!** Blocking negates an extra **${result.shellGuard}%** damage!\n`);
        }
    } else if (result.dodged) {
        steps.push('💨 **DODGED!**\n');
        if (result.headMovement) {
            steps.push(`🥊 **Head Movement!** The Boxer slips out and gains **Rhythm** — drains **${result.headMovementKi} Ki** from the attacker!\n`);
        }
        if (result.reactionText) {
            steps.push(result.reactionText + '\n');
        } else if (result.reactionPending) {
            steps.push('🎯 **A reaction is available!**\n');
        } else if (!result.groundGlider) {
            steps.push('(No damage taken.)\n');
        }
        if (result.groundGlider) {
            steps.push('🤼 **Ground Glider!** The Wrestler slips the attack and **GRAPPLES** the attacker!\n');
        }
        if (result.hesitant) {
            steps.push(`😰 The attacker fails the WIL save (${result.phantomStepSave ? `${result.phantomStepSave.save} vs ${result.phantomStepSave.dc}` : ''}) and becomes **HESITANT** (-15% DEX mod on attacks)!\n`);
        } else if (result.phantomStepResist) {
            steps.push(`😤 The attacker resists **Phantom Step** (${result.phantomStepResist.save} vs ${result.phantomStepResist.dc})!\n`);
        }
    } else if (result.clash) {
        steps.push('⚡ **CLASH!** Both fighters are evenly matched!\n');
        steps.push(`${result.clashType === 'frenzy' ? '🤜🤛 **Clash Frenzy**' : '🔮 **Ki Struggle**'} — first to win **twice in a row**!\n`);
        (result.clashRounds || []).forEach((r, i) => {
            const label = r.aWin ? 'Attacker' : r.dWin ? 'Defender' : 'Tie';
            steps.push(`Round ${i + 1}: **${attackerName}** ${r.a} vs **${defender.username}** ${r.d} — ${label}\n`);
        });
        steps.push(`🏆 **${result.clashWinner}** wins the ${result.clashType === 'frenzy' ? 'Clash Frenzy' : 'Ki Struggle'}!\n`);
        steps.push(`Damage: ${result.clashDamageRoll} + mod = **${result.clashDamage} damage**\n`);
        if (result.clashKnockedOut) {
            steps.push(`💀 **${result.clashLoser} is KNOCKED OUT!**\n`);
        }
        steps.push(`${result.clashLoser}'s HP: **${result.clashLoserHP}**\n`);
    }

    steps.push(`${defender.username}'s HP: **${defender.currentHP}**\n`);
    return steps;
}

// One-shot formatted attack event (no per-step pacing).
function formatAttackEvent(attackerName, defender, result) {
    return buildAttackEventSteps(attackerName, defender, result).join('');
}

// Animate an attack event line-by-line, updating `onProgress` after each step.
// "Moment" lines (CRITICAL HIT! / HIT LANDS! / BLOCKED!) pause longer for emphasis.
async function animateAttackEvent(text, attackerName, defender, result, onProgress) {
    const steps = buildAttackEventSteps(attackerName, defender, result);
    const MOMENT_MARKERS = ['**CRITICAL HIT!**', '**HIT LANDS!**', '**BLOCKED!**'];
    const MOMENT_PAUSE = 750; // ~0.75s
    const NORMAL_PAUSE = 200; // ~0.2s
    for (const step of steps) {
        text += step;
        if (onProgress) await onProgress(text);
        await sleep(MOMENT_MARKERS.some(m => step.includes(m)) ? MOMENT_PAUSE : NORMAL_PAUSE);
    }
    return text;
}

function formatDeathSaveEvent(entry) {
    const save = entry.save;
    if (save.dead) return `☠️ **${entry.username} has DIED!**\n\n`;
    if (save.stable) return `💀 **${entry.username}** rolls a death save: **${save.roll}** (Success) — they are now **STABLE!**\n\n`;
    let text = `💀 **${entry.username}** rolls a death save: **${save.roll}** ${save.success ? '(Success)' : '(Failure)'}`;
    if (save.failedSaves !== undefined && save.succeededSaves !== undefined) {
        text += `\nSuccesses: ${save.succeededSaves}/2 | Failures: ${save.failedSaves}/3`;
    }
    return text + '\n\n';
}

function formatStunEvent(entry) {
    return `⚡ **${entry.username}** is STUNNED and loses their turn!\n\n`;
}

function formatKiRegenEvent(entry) {
    return `🔋 **${entry.username}** regenerates **${entry.gained} Ki**!\n\n`;
}

function formatBleedEvent(entry) {
    return `🩸 **${entry.username}** bleeds for **${entry.damage} damage**! (${entry.turns} turn${entry.turns === 1 ? '' : 's'} left)\n\n`;
}

function formatRuptureEvent(entry) {
    return `💔 **${entry.username}** suffers from **Rupture** — **${entry.damage} damage** and **${entry.ki} Ki** lost! (${entry.turns} turn${entry.turns === 1 ? '' : 's'} left)\n\n`;
}

function formatPoisonEvent(entry) {
    let text = `☠️ **${entry.username}** is poisoned and takes **${entry.damage} damage**!`;
    if (entry.blinded) text += ` They are BLINDED (disadvantage on their next attack).`;
    return text + ` (${entry.turns} turn${entry.turns === 1 ? '' : 's'} left)\n\n`;
}

function formatCraneMarkExpireEvent(entry) {
    return entry.stunned
        ? `🐦 **Crane's Mark** wears off — **${entry.marker}** forces a CON save and **${entry.username}** is STUNNED for 1 turn!\n\n`
        : `🐦 **Crane's Mark** wears off on **${entry.username}** — they resist the CON save!\n\n`;
}

function formatGrappleHoldEvent(entry) {
    return `🤼 **${entry.username}** is grappled by **${entry.grappler}** and can't break free! (${entry.roll} vs ${entry.save}) — they lose their turn.\n\n`;
}

function formatGrappleEscapeEvent(entry) {
    return `🤼💨 **${entry.username}** breaks free of the grapple! (${entry.roll} vs ${entry.save})\n\n`;
}

function formatLssjRampEvent(entry) {
    return `📈 **${entry.username}** (Legendary Super Saiyan) ramps up on turn ${entry.turn}: +**${entry.modGain} ALL MODS**!\n🔋 +${entry.kiGain} Ki (d80) − ${entry.drain} drain\n\n`;
}

function formatHopfDrainEvent(entry) {
    return `🌟💫 **${entry.username}** (Hope of the Universe) loses **${entry.damage} HP** to **Give Me Everything**!\n\n`;
}

function formatPassiveDrainEvent(entry) {
    const emoji = entry.passive === 'Ki Sense' ? '👁️' : entry.passive === 'Ki Application' ? '💥' : '🕊️';
    const off = entry.off ? ' and turns off (no Ki left)!' : '';
    return `🌀 ${emoji} **${entry.username}**'s **${entry.passive}** drains **${entry.drain} Ki**${off}!\n\n`;
}

// Once a Saiyan has unlocked a Super Saiyan form, they can no longer awaken False Super Saiyan.
function hasSuperSaiyanForm(entity) {
    const forms = Array.isArray((entity || {}).forms) ? entity.forms : [];
    return forms.includes('Super Saiyan') || forms.includes('Super Saiyan 2') || forms.includes('Super Saiyan 3');
}

// False Super Saiyan: Saiyan fury when under 50% HP (1d100 + WIL mod/2 vs 95, once per battle, no action).
// Applies to Saiyans whether they're the player, a companion, or an enemy.
function tryFalseSuperSaiyanAwakening(battle, participant) {
    if (!participant || participant.isDead || participant.isIncapacitated || participant.awakened) return '';
    if (participant.race !== 'Saiyan') return '';
    const { character, companion } = getParticipantEntity(participant);
    const entity = isCompanion(participant) ? companion : character;
    if (entity && entity.activeForm === 'False Super Saiyan') return '';
    if (hasSuperSaiyanForm(entity)) return '';
    if (participant.fssjActive) return '';
    if ((participant.currentHP || 0) >= (participant.hp || 1) * 0.5) return '';

    participant.awakened = true;
    const wilMod = battle.getEffectiveModifier(participant, 'wil');
    const roll = battle.rollDice(100);
    const total = roll + Math.round(wilMod / 2);

    if (total >= 95) {
        // +5 ALL MODS (except INT)
        participant.modBonus = participant.modBonus || {};
        ['str', 'dex', 'con', 'wil', 'spi'].forEach(s => {
            participant.modBonus[s] = (participant.modBonus[s] || 0) + 5;
        });
        participant.fssjActive = true;
        const forms = Array.isArray((entity || {}).forms) ? entity.forms : [];
        if (!forms.includes('False Super Saiyan')) forms.push('False Super Saiyan');
        if (isCompanion(participant) && companion) {
            companion.forms = forms;
            companion.activeForm = 'False Super Saiyan';
            const owner = characterManager.getCharacter(participant.ownerUserId);
            if (owner) characterManager.updateCharacter(participant.ownerUserId, owner.id, { companions: owner.companions });
        } else if (character) {
            characterManager.updateCharacter(participant.userId, character.id, { forms, activeForm: 'False Super Saiyan' });
        }
        return `😡🔥 **${participant.username}** falls under 50% HP and their fury erupts — **FALSE SUPER SAIYAN** awakens automatically! (${roll}+${Math.round(wilMod / 2)} = ${total} vs 95)\n+5 ALL MODS, no action used.\n\n`;
    }

    return `**${participant.username}** falls under 50% HP and tries to awaken... (${roll}+${Math.round(wilMod / 2)} = ${total} vs 95)\nThe fury fades.\n\n`;
}

// Intense Anger (Saiyan racial passive): at 10% HP (last stand) add 25% of base stats,
// roll 1d50 — crit unlocks the next Super Saiyan transformation, fail = 25% chance of False Super Saiyan.
function tryIntenseAnger(battle, participant) {
    if (!participant || participant.intenseAngerUsed || participant.isDead || participant.isIncapacitated) return '';
    if (participant.race !== 'Saiyan' && participant.race !== 'Half-Saiyan') return '';
    const { character, companion } = getParticipantEntity(participant);
    if ((participant.currentHP || 0) >= (participant.hp || 1) * 0.1) return ''; // last stand = 10% HP

    participant.intenseAngerUsed = true;
    let text = `😠💥 **${participant.username}** is on their **LAST STAND** (10% HP) — **Intense Anger** triggers!\n`;

    // +25% (Saiyan) / +50% (Half-Saiyan) of base stats
    const pct = participant.race === 'Half-Saiyan' ? 0.5 : 0.25;
    const gains = [];
    ['str', 'dex', 'con', 'wil', 'spi'].forEach(s => {
        const base = (participant.stats && participant.stats[s]) || 0;
        const add = Math.round(base * pct);
        if (add > 0) {
            participant.stats[s] = (participant.stats[s] || 0) + add;
            gains.push(`${s.toUpperCase()} +${add}`);
        }
    });
    text += `📈 +${Math.round(pct * 100)}% of base stats: **${gains.join(' | ')}**\n`;

    // 1d50 (Saiyan) / 1d40 (Half-Saiyan) — crit unlocks the next Super Saiyan transformation
    const critDie = participant.race === 'Half-Saiyan' ? 40 : 50;
    const roll = battle.rollDice(critDie);
    const entity = isCompanion(participant) ? companion : character;
    if (roll === critDie) {
        const chain = ['Super Saiyan', 'Super Saiyan 2', 'Super Saiyan 3'];
        const forms = Array.isArray((entity || {}).forms) ? entity.forms : [];
        const next = chain.find(f => !forms.includes(f));
        if (next) {
            forms.push(next);
            if (isCompanion(participant) && companion) {
                companion.forms = forms;
                const owner = characterManager.getCharacter(participant.ownerUserId);
                if (owner) characterManager.updateCharacter(participant.ownerUserId, owner.id, { companions: owner.companions });
            } else if (character) {
                characterManager.updateCharacter(participant.userId, character.id, { forms });
            }
            text += `🎲 1d${critDie} = **${roll} — CRITICAL SUCCESS!** You unlock **${next}**!\n`;
        } else {
            text += `🎲 1d${critDie} = **${roll} — CRITICAL SUCCESS!** (No further Super Saiyan transformations to unlock)\n`;
        }
        return text + '\n';
    }

    // Fail: 25% chance to awaken False Super Saiyan (only if the Saiyan has NO Super Saiyan form).
    const awakenRoll = getRandomInt(100);
    if (awakenRoll <= 25) {
        const alreadyInFSSJ = participant.fssjActive || (character && character.activeForm === 'False Super Saiyan');
        if (!alreadyInFSSJ && !hasSuperSaiyanForm(entity)) {
            participant.modBonus = participant.modBonus || {};
            ['str', 'dex', 'con', 'wil', 'spi'].forEach(s => {
                participant.modBonus[s] = (participant.modBonus[s] || 0) + 5;
            });
            participant.fssjActive = true;
            const forms = Array.isArray((entity || {}).forms) ? entity.forms : [];
            if (!forms.includes('False Super Saiyan')) forms.push('False Super Saiyan');
            if (isCompanion(participant) && companion) {
                companion.forms = forms;
                companion.activeForm = 'False Super Saiyan';
                const owner = characterManager.getCharacter(participant.ownerUserId);
                if (owner) characterManager.updateCharacter(participant.ownerUserId, owner.id, { companions: owner.companions });
            } else if (character) {
                characterManager.updateCharacter(participant.userId, character.id, { forms, activeForm: 'False Super Saiyan' });
            }
            text += `🎲 1d${critDie} = ${roll} (fail) — 25% roll: **${awakenRoll}** → the fury takes hold — **FALSE SUPER SAIYAN** awakens! (+5 ALL MODS)\n`;
        } else {
            const blocked = hasSuperSaiyanForm(entity) ? 'you already have **Super Saiyan**' : 'you\'re already in **False Super Saiyan**';
            text += `🎲 1d${critDie} = ${roll} (fail) — 25% roll: **${awakenRoll}** succeeds, but ${blocked}.\n`;
        }
    } else {
        text += `🎲 1d${critDie} = ${roll} (fail) — 25% roll: **${awakenRoll}** fails. The fury fades.\n`;
    }
    return text + '\n';
}

// Hope of the Universe (Earthling/Half-Saiyan mutation): any time you're knocked under 20% HP,
// tap into your full potential — heal to half HP, +20 STR, refill Ki, then drain 10% max HP per turn.
function tryHopeOfTheUniverse(battle, participant) {
    if (!participant || participant.isNPC || participant.hopfTriggered || participant.isDead || participant.isIncapacitated) return '';
    const character = characterManager.getCharacter(participant.userId);
    if (!character || character.mutation !== 'Hope of the Universe') return '';
    if (participant.currentHP >= participant.hp * 0.2) return ''; // under 20% HP

    participant.hopfTriggered = true;
    participant.hopfActive = true;

    participant.modBonus = participant.modBonus || {};
    participant.modBonus.str = (participant.modBonus.str || 0) + 20; // My Weapon is Judgement

    const healTo = Math.round(participant.hp * 0.5);
    participant.currentHP = healTo; // Renewed Reason
    participant.currentKi = participant.ki || participant.currentKi; // Give Me Everything: energy to max

    return `🌟💫 **${participant.username}** is on the brink — **HOPE OF THE UNIVERSE** ignites!\n` +
        `💚 **Renewed Reason** — healed to **${healTo} HP**\n` +
        `⚔️ **My Weapon is Judgement** — **+20 STR**\n` +
        `⚡ **Give Me Everything** — Ki restored to max, but **-10% max HP per turn**\n\n`;
}

// Hera "Ultimate Power": triggered by a traumatic experience — when a Hera's HP is knocked
// under 40% in battle (with the form + 60k PL), it awakens without using a turn.
function tryUltimatePowerAwakening(battle, participant) {
    if (!participant || isNPC(participant) || isCompanion(participant) || participant.ultimatePowerAwakened) return '';
    if (participant.race !== 'Hera') return '';
    if (participant.formName === 'Ultimate Power') return '';
    const { character } = getParticipantEntity(participant);
    if (!character || !Array.isArray(character.forms) || !character.forms.includes('Ultimate Power')) return '';
    if ((character.powerLevel || participant.powerLevel || 0) < 60000) return '';
    if ((participant.currentHP || 0) > (participant.hp || 1) * 0.4) return ''; // trauma = knocked under 40% HP

    participant.ultimatePowerAwakened = true;
    const form = FORMS['Ultimate Power'];
    const mastery = (character.formMastery || {})['Ultimate Power'] || 0;
    const bonusMultiplier = 1 + mastery * 0.1;
    participant.modBonus = participant.modBonus || {};
    const formMods = {};
    Object.entries(form.modBonus || {}).forEach(([s, m]) => {
        const mm = Math.round(m * bonusMultiplier);
        participant.modBonus[s] = (participant.modBonus[s] || 0) + mm;
        formMods[s] = mm;
    });
    const mmods = (form.masteryMods || {})[mastery] || {};
    Object.entries(mmods).forEach(([s, m]) => {
        participant.modBonus[s] = (participant.modBonus[s] || 0) + m;
        formMods[s] = (formMods[s] || 0) + m;
    });
    participant.formName = 'Ultimate Power';
    participant.formDrain = getFormDrain('Ultimate Power', mastery);
    participant.formMods = formMods;
    return `🔥 **${participant.username}** suffers a **traumatic flashback** — **ULTIMATE POWER** awakens! (+15 ALL MODS, x75 PL, no action used, drains ${participant.formDrain} Ki/turn)\n`;
}

// Saiyans automatically unlock Super Saiyan when they hit 3,000,000 PL
function checkSaiyanSuperSaiyanUnlock(userId, character) {
    if (!character) return '';
    const fresh = characterManager.getCharacter(userId, character.id) || character;
    let text = '';
    // Saiyan: auto-unlock Super Saiyan at 3,000,000 PL.
    if (fresh.race === 'Saiyan' && (fresh.powerLevel || 0) >= 3000000) {
        const forms = Array.isArray(fresh.forms) ? fresh.forms : [];
        if (!forms.includes('Super Saiyan')) {
            forms.push('Super Saiyan');
            fresh.forms = forms;
            characterManager.updateCharacter(userId, fresh.id, { forms });
            text += `⚡🌟 **${fresh.name}** crossed **3,000,000 PL** and automatically unlocked **SUPER SAIYAN**!\n\n`;
        }
    }
    // Hera: auto-unlock Ultra Power (10k PL) and Ultimate Power (60k PL).
    if (fresh.race === 'Hera') {
        const forms = Array.isArray(fresh.forms) ? fresh.forms : [];
        let changed = false;
        if (!forms.includes('Ultra Power') && (fresh.powerLevel || 0) >= 10000) {
            forms.push('Ultra Power');
            changed = true;
            text += `⚡ **${fresh.name}** reached **10,000 PL** and unlocked **ULTRA POWER**!\n\n`;
        }
        if (!forms.includes('Ultimate Power') && (fresh.powerLevel || 0) >= 60000) {
            forms.push('Ultimate Power');
            changed = true;
            text += `💥 **${fresh.name}** reached **60,000 PL** and unlocked **ULTIMATE POWER**!\n\n`;
        }
        if (changed) {
            fresh.forms = forms;
            characterManager.updateCharacter(userId, fresh.id, { forms });
        }
    }
    return text;
}

// Discord limits message content to 2000 chars; clamp long battle logs so they don't crash.
function clampMessage(str, max = 2000) {
    if (typeof str !== 'string' || str.length <= max) return str;
    return str.slice(0, max - 3) + '...';
}

// Show a combatant's base → mod/boost → effective modifier for each stat (used in battle UI).
function formatFightModBreakdown(battle, p) {
    const labels = [['str', 'STR'], ['dex', 'DEX'], ['con', 'CON'], ['wil', 'WIL'], ['spi', 'SPI'], ['int', 'INT']];
    const parts = labels.map(([key, label]) => {
        const base = (p.stats || {})[key] || 0;
        if (key === 'int' && base === 0) return null;
        const baseMod = battle.getModifier(base);
        const boost = (p.modBonus || {})[key] || 0;
        const eff = battle.getEffectiveModifier(p, key);
        return `**${label}** ${base}(${baseMod >= 0 ? '+' : ''}${baseMod}${boost !== 0 ? `+${boost >= 0 ? '+' : ''}${boost}` : ''})→${eff >= 0 ? '+' : ''}${eff}`;
    }).filter(Boolean);
    return parts.join(' | ');
}

function buildBattleContent(battle, logText = '') {
    const current = battle.getCurrentTurn();
    if (!current) return '💀 No active combatants remain.';

    const surprise = battle.surpriseRound && battle.round === 1 ? '🎯 **SURPRISE ROUND!** Your side got the drop on the enemy!\n\n' : '';
    let message = `⚔️ **Round ${battle.round}** — It's **${current.username}**'s turn!\n\n${surprise}`;
    message += '**Initiative Order:**\n';

    battle.turnOrder.forEach((p, index) => {
        const marker = p.userId === current.userId ? '▶️ ' : '';
        let status = '';
        if (p.isDead) status = ' 💀';
        else if (p.isIncapacitated) status = ' 😵';
        if (p.stunned) status += ' ⚡';
        if (p.flying) status += ' 🕊️';
        if (p.grappledBy) status += ' 🤼';
        if (p.bleedTurns > 0) status += ' 🩸';
        if (p.poisonTurns > 0) status += ' ☠️';
        if (p.isAlly) status += ' 🤝';
        if (p.fightingStyle === 'Maniac' && p.sadism != null) status += ` 😈${p.sadism}/${p.sadistMax}`;
        // Companions/enemies have a viewable INT stat.
        const intDisplay = (isCompanion(p) || isNPC(p)) ? ` | INT: ${(p.stats && p.stats.int) ?? '?'}` : '';
        // Show a combatant's fighting style so you can see what an enemy/reinforcement uses.
        const styleDisplay = p.fightingStyle ? ` | 🥋 ${p.fightingStyle}` : '';
        message += `${marker}${index + 1}. ${p.username}${p.weapon ? ` (${p.weapon})` : ''}${p.armor ? ` 🛡️ ${p.armor}` : ''} — HP: ${p.currentHP}${intDisplay}${styleDisplay}${status}\n`;
    });

    message += `\n**Current:** ${current.username}${current.weapon ? ` (${current.weapon})` : ''}${current.armor ? ` 🛡️ ${current.armor}` : ''}${current.fightingStyle ? ` | 🥋 ${current.fightingStyle}` : ''}\n`;
    message += `HP: ${current.currentHP} | Ki: ${current.currentKi}`;
    if (current.fightingStyle === 'Maniac' && current.sadism != null) {
        message += ` | 😈 Sadism: ${current.sadism}/${current.sadistMax}`;
    }
    // Mod/boost/base breakdown for the active combatant (so you can see what's being rolled).
    message += `\n🧮 **Mods:** ${formatFightModBreakdown(battle, current)}`;

    const actions = [];
    if (!current.hasActed) actions.push('Action');
    if (!current.hasBonusActed) actions.push('Bonus Action');
    message += actions.length > 0 ? `\nAvailable: ${actions.join(' + ')}` : '\nNo actions left — end your turn!';

    if (current.turnDisadvantage) {
        message += '\n⚠️ **DISADVANTAGE** on all rolls this turn!';
    }

    if (logText) {
        message += `\n\n${logText}`;
    }

    return clampMessage(message);
}

// ----- 10-second turn timer -----
const battleTurnTimers = new Map(); // battle.id -> timeout

function clearBattleTurnTimer(battle) {
    const t = battleTurnTimers.get(battle.id);
    if (t) { clearTimeout(t); battleTurnTimers.delete(battle.id); }
}

// Arm a 10s timer on the current player's turn. If they don't act, auto-resolve the turn.
function armBattleTurnTimer(battle) {
    clearBattleTurnTimer(battle);
    if (!battleManager.hasBattle(battle.id) || battle.isBattleOver()) return;
    const current = battle.getCurrentTurn();
    if (!current || isNPC(current) || isCompanion(current) || current.isDead || current.isIncapacitated) return;
    const timeout = setTimeout(() => {
        battleTurnTimers.delete(battle.id);
        resolveBattleTurnAuto(battle);
    }, BATTLE_TURN_TIMEOUT_MS);
    battleTurnTimers.set(battle.id, timeout);
}

// Append formatted battle-log entries to a text string.
function appendBattleLog(logText, log) {
    log.forEach(entry => {
        if (entry.type === 'deathSave') logText += formatDeathSaveEvent(entry);
        else if (entry.type === 'stun') logText += formatStunEvent(entry);
        else if (entry.type === 'kiRegen') logText += formatKiRegenEvent(entry);
        else if (entry.type === 'lssjRamp') logText += formatLssjRampEvent(entry);
        else if (entry.type === 'bleed') logText += formatBleedEvent(entry);
        else if (entry.type === 'rupture') logText += formatRuptureEvent(entry);
        else if (entry.type === 'poison') logText += formatPoisonEvent(entry);
        else if (entry.type === 'craneMarkExpire') logText += formatCraneMarkExpireEvent(entry);
        else if (entry.type === 'hopfDrain') logText += formatHopfDrainEvent(entry);
        else if (entry.type === 'passiveDrain') logText += formatPassiveDrainEvent(entry);
        else if (entry.type === 'grappleHold') logText += formatGrappleHoldEvent(entry);
        else if (entry.type === 'grappleEscape') logText += formatGrappleEscapeEvent(entry);
        else if (entry.type === 'limitBreak') logText += `\n✨ **${entry.username}** breaks their limits! (**LIMIT BREAK**, turn ${entry.round})`;
    });
    return logText;
}

// Edit a battle's channel message in place (used by the background turn timer).
async function editBattleMessage(battle, content, components, messageIdOverride) {
    const channel = client.channels.cache.get(battle.channelId);
    const messageId = messageIdOverride || battleMessages.get(battle.id);
    if (!channel || !messageId) return;
    try {
        const msg = await channel.messages.fetch(messageId);
        await msg.edit({ content, components });
    } catch (e) {}
}

// Auto-resolve a player's turn after the 10s timer fires: if they haven't acted, auto-attack
// a random target, then advance the turn and re-render the battle.
async function resolveBattleTurnAuto(battle) {
    clearBattleTurnTimer(battle);
    if (!battleManager.hasBattle(battle.id) || battle.isBattleOver()) return;

    // Leave any open target/skill submenu so the auto-resolved turn renders cleanly.
    const ui = ensureBattleUI(battle);
    ui.mode = 'turn';
    ui.pendingSkill = null;

    // Capture the message id BEFORE checkBattleOver clears it, so an ended battle can
    // still render its "battle over" state (and not leave stale, non-working buttons).
    const msgId = battleMessages.get(battle.id);

    const current = battle.getCurrentTurn();
    let logText = '';
    if (current && !isNPC(current) && !isCompanion(current) && !current.isDead && !current.isIncapacitated) {
        if (!current.hasActed) {
            const targets = getAliveTargets(battle, current.userId);
            if (targets.length > 0) {
                const target = targets[getRandomInt(targets.length) - 1];
                const result = await battle.attack(current.userId, target.userId, 'physical', true);
                logText += `⏱️ **${current.username}** took too long and auto-attacked **${target.username}**!`;
                if (result.success && result.hit) logText += `\n${current.username} hits for **${result.damage} damage**!`;
                else if (result.success) logText += `\nThe attack misses!`;
                else logText += `\n(${result.message || 'no attack'})`;
            } else {
                logText += `⏱️ **${current.username}** took too long (no targets left).`;
            }
        } else {
            logText += `⏱️ **${current.username}**'s turn timed out.`;
        }
        const { log } = battle.advance();
        logText = appendBattleLog(logText + '\n\n', log);
    } else {
        const { log } = battle.advance();
        logText = appendBattleLog(logText, log);
    }

    logText = await resolveNPCTurns(battle, logText);
    logText += maybeUnlockShogun(battle, current);
    logText += maybeCallReinforcements(battle);
    // A player defender dodged and can react — pause for their Yes/No choice.
    const rp = buildReactionPromptData(battle, logText);
    if (rp) {
        await editBattleMessage(battle, rp.content, rp.components);
        return;
    }
    const over = checkBattleOver(battle);
    if (over) {
        await editBattleMessage(battle, clampMessage(`${buildBattleContent(battle, logText)}\n\n${over.content}`), over.components || [], msgId);
        return;
    }
    await editBattleMessage(battle, buildBattleContent(battle, logText), buildTurnComponents(battle, null));
}

function buildTurnComponents(battle, viewer) {
    const current = battle.getCurrentTurn();
    const components = [];
    const row = new ActionRowBuilder();

    // Always render the current player's buttons (so co-op/duel turns work for every player)
    if (current && !isNPC(current) && !isCompanion(current)) {
        row.addComponents(
            new ButtonBuilder()
                .setCustomId('bt_attack')
                .setLabel(current.hasActed ? '⚔️ Attack (used)' : '⚔️ Attack')
                .setStyle(ButtonStyle.Primary)
                .setDisabled(current.hasActed),
            new ButtonBuilder().setCustomId('bt_items').setLabel('🎒 Items').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId('bt_retreat').setLabel(current.grappledBy ? '🤼 Retreat (grappled)' : '🏃 Retreat').setStyle(ButtonStyle.Danger).setDisabled(!!current.grappledBy),
            new ButtonBuilder().setCustomId('bt_save').setLabel('💊 Save Ally').setStyle(ButtonStyle.Success),
            new ButtonBuilder().setCustomId('bt_endturn').setLabel('➡️ End Turn').setStyle(ButtonStyle.Primary)
        );
        components.push(row);

        const skillRow = new ActionRowBuilder()
            .addComponents(
                new ButtonBuilder().setCustomId('bt_skills').setLabel('🧠 Techniques').setStyle(ButtonStyle.Secondary),
                new ButtonBuilder().setCustomId('bt_grapple').setLabel(current.grappling ? '🤼 Grappling' : '🤼 Grapple').setStyle(ButtonStyle.Secondary).setDisabled(current.hasActed || !!current.grappling),
                new ButtonBuilder().setCustomId('bt_transform').setLabel('✨ Transform').setStyle(ButtonStyle.Secondary)
            );
        // Reactions are optional: a Tiger can toggle Spirit of the Tiger, a Wrestler Ground Glider.
        if (current.fightingStyle === 'Tiger' || current.fightingStyle === 'Wrestler') {
            skillRow.addComponents(
                new ButtonBuilder().setCustomId('bt_reactions')
                    .setLabel(current.useReactions === false ? '🙅 Reactions: Off' : '🛡️ Reactions: On')
                    .setStyle(current.useReactions === false ? ButtonStyle.Danger : ButtonStyle.Secondary)
            );
        }
        // Talk: try to persuade an enemy to join you (mission battles only — not mentors,
        // duels, or custom battles. Saga missions never allow recruiting).
        const ui = ensureBattleUI(battle);
        const canTalk = activeMissions.has(battle.id) && !ui.recruited && !isSagaBattle(battle) && getEnemyTargets(battle).length > 0;
        if (canTalk) {
            skillRow.addComponents(
                new ButtonBuilder().setCustomId('bt_talk').setLabel(current.hasActed ? '🗨️ Talk (used)' : '🗨️ Talk')
                    .setStyle(ButtonStyle.Secondary)
                    .setDisabled(current.hasActed)
            );
        }
        components.push(skillRow);

        // Saibamen "PTSD": self-implode, dealing current HP + current Ki to all enemies (ends your life).
        // A grappled Saibamen can still blow up as a last resort.
        if (current.race === 'Saibamen') {
            components.push(
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder().setCustomId('bt_explode').setLabel('💥 Implode (PTSD)').setStyle(ButtonStyle.Danger).setDisabled(current.hasActed && !current.grappledBy)
                )
            );
        }

        // Namekian Regeneration: spend 10 Ki to restore 10 HP (uses your action + bonus action).
        if (current.race === 'Namekian') {
            components.push(
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder().setCustomId('bt_regen')
                        .setLabel(current.hasActed ? '🩹 Regenerate (used)' : '🩹 Regenerate (10 Ki → 10 HP)')
                        .setStyle(ButtonStyle.Success)
                        .setDisabled(current.hasActed || (current.currentKi || 0) < 10)
                )
            );
        }

        // Cerealian Evolved Right Eye: toggle whether ki attacks auto-reroll at a Ki cost.
        if (current.race === 'Cerealian') {
            components.push(
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder().setCustomId('bt_eye')
                        .setLabel(current.eyeRerollEnabled === false ? '👁️ Eye Reroll: Off' : '👁️ Eye Reroll: On')
                        .setStyle(current.eyeRerollEnabled === false ? ButtonStyle.Secondary : ButtonStyle.Primary)
                )
            );
        }
    } else {
        const label = (current ? `Waiting for ${current.username}...` : 'Battle over...').slice(0, 80);
        row.addComponents(
            new ButtonBuilder().setCustomId('bt_wait').setLabel(label).setStyle(ButtonStyle.Secondary).setDisabled(true)
        );
        components.push(row);
    }

    armBattleTurnTimer(battle);
    return components;
}

function buildTargetComponents(battle, viewer) {
    const ui = ensureBattleUI(battle);
    const components = [];
    const current = battle.getCurrentTurn();
    let targets = getAliveTargets(battle, viewer.id);
    // While grappling, you can only strike the opponent you're holding.
    if (current && current.grappling) {
        const held = battle.turnOrder.find(p => p.userId === current.grappling && !p.isDead && !p.isIncapacitated);
        targets = held ? [held] : [];
    }

    // Only allow ki-based attacks if the active player has learned Ki Application.
    const currentChar = current && !isNPC(current) ? characterManager.getCharacter(current.userId) : null;
    const canKi = !!(current && current.kiApplicationLearned) || !!(currentChar && hasKiApplication(currentChar));
    const effectiveType = ui.attackType === 'ki' && !canKi ? 'physical' : ui.attackType;
    // Cap at 15 targets (3 rows of 5 + type + back = 5 rows, Discord's limit).
    targets = targets.slice(0, 15);

    let row = new ActionRowBuilder();
    targets.forEach(t => {
        if (row.components.length >= 5) {
            components.push(row);
            row = new ActionRowBuilder();
        }
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`bt_tgt_${t.userId}`)
                .setLabel(`${t.username} (${t.currentHP})`)
                .setStyle(ButtonStyle.Danger)
        );
    });
    if (row.components.length > 0) components.push(row);

    const typeRow = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('bt_type_physical')
                .setLabel(effectiveType === 'physical' ? '⚔️ Physical ✓' : '⚔️ Physical')
                .setStyle(effectiveType === 'physical' ? ButtonStyle.Primary : ButtonStyle.Secondary),
            new ButtonBuilder()
                .setCustomId('bt_type_ki')
                .setLabel(effectiveType === 'ki' ? '🔮 Ki-Based ✓' : '🔮 Ki-Based')
                .setStyle(effectiveType === 'ki' ? ButtonStyle.Primary : ButtonStyle.Secondary)
                .setDisabled(!canKi)
        );
    components.push(typeRow);

    const backRow = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder().setCustomId('bt_back').setLabel('⬅️ Back').setStyle(ButtonStyle.Secondary)
        );
    components.push(backRow);

    armBattleTurnTimer(battle);
    return components;
}

function buildSaveComponents(battle, viewer) {
    const components = [];
    const allies = battle.turnOrder.filter(p => p.userId !== viewer.id && p.isIncapacitated && !p.isDead).slice(0, 20);

    let row = new ActionRowBuilder();
    allies.forEach(ally => {
        if (row.components.length >= 5) {
            components.push(row);
            row = new ActionRowBuilder();
        }
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`bt_save_${ally.userId}`)
                .setLabel(`💊 ${ally.username}`)
                .setStyle(ButtonStyle.Success)
        );
    });
    if (row.components.length > 0) components.push(row);

    const backRow = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder().setCustomId('bt_back').setLabel('⬅️ Back').setStyle(ButtonStyle.Secondary)
        );
    components.push(backRow);

    armBattleTurnTimer(battle);
    return components;
}

function getConsumables(viewer) {
    const character = characterManager.getCharacter(viewer.id);
    if (!character || !character.inventory) return [];
    return character.inventory
        .map((item, index) => ({ item, index, data: typeof item === 'string' ? { name: item, type: 'unknown' } : item }))
        .filter(entry => getConsumableEffect(entry.item) !== null);
}

function buildItemComponents(battle, viewer) {
    const components = [];
    // Cap at 20 items (4 rows of 5 + back = 5 rows, Discord's limit).
    const consumables = getConsumables(viewer).slice(0, 20);

    let row = new ActionRowBuilder();
    consumables.forEach(entry => {
        if (row.components.length >= 5) {
            components.push(row);
            row = new ActionRowBuilder();
        }
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`bt_item_${entry.index}`)
                .setLabel(entry.data.name.length > 40 ? entry.data.name.slice(0, 40) : entry.data.name)
                .setStyle(ButtonStyle.Primary)
        );
    });
    if (row.components.length > 0) components.push(row);

    const backRow = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder().setCustomId('bt_back').setLabel('⬅️ Back').setStyle(ButtonStyle.Secondary)
        );
    components.push(backRow);

    armBattleTurnTimer(battle);
    return components;
}

// Roll whether enemies finish a downed player off after a lost mission (d20).
// Positive alignment: 17+ kills. Negative alignment: 19+ kills.
// Saga missions: positive always kills; negative kills on 11+.
function enemiesKillPlayer(missionType, alignment) {
    if (missionType === 'saga') {
        if (alignment === 'negative') return getRandomInt(20) > 10; // 11-20
        return true; // positive saga enemies always kill
    }
    if (alignment === 'negative') return getRandomInt(20) >= 19; // 19-20
    return getRandomInt(20) >= 17; // 17-20
}

// Is the Ancient Wuxia Talisman protection currently active?
function hasActiveTalisman(character) {
    return (character.talismanUntil || 0) > Date.now();
}

// Where a dead soul ends up: negative alignment → Hell, otherwise → Otherworld.
function afterlifeLocationName(character) {
    return (Number(character && character.deathAlignmentValue) || 0) < 0 ? 'Hell' : 'Otherworld';
}

// Kill a character: flag them dead and send them to the afterlife (Hell or Otherworld).
function killCharacter(userId) {
    const character = characterManager.getCharacter(userId);
    if (!character) return null;
    // Ancient Wuxia Talisman: otherworldly entities cannot interact with you.
    if (hasActiveTalisman(character)) {
        characterManager.updateCharacter(userId, character.id, { currentHP: 1 });
        return { name: character.name, protected: true };
    }

    // Namekian Rebirth: if the character has an intact egg and isn't on a 5-saga cooldown, they
    // are reborn from the egg instead of dying (100%+1d20% of previous stats on top of fresh rolls).
    if (character.race === 'Namekian' && character.namekianEgg !== false
        && !(character.rebirthSaga && globalSaga < character.rebirthSaga + 5)) {
        const keepPct = 1 + (getRandomInt(20) / 100); // 100% + 1d20%
        const fresh = rollFreshStats(character.race);
        const newStats = {};
        ['str', 'dex', 'con', 'wil', 'spi', 'int'].forEach(s => {
            newStats[s] = Math.max(1, (fresh[s] || 0) + Math.floor(((character.stats || {})[s] || 0) * keepPct));
        });
        const maxHP = calculateHP(newStats.con, character.race);
        const maxKi = calculateKi(newStats.spi, character.race);
        const modifiers = calculateAllModifiers(newStats);
        const powerLevel = characterManager.calculatePowerLevel({ ...newStats, maxHP, maxKi });
        const spawnLocation = getDefaultLocation(character.race);
        const spawnSpace = getRandomInt(PLANET_SPACES[spawnLocation] || 100);
        characterManager.updateCharacter(userId, character.id, {
            dead: false,
            location: spawnLocation,
            space: spawnSpace,
            stats: newStats,
            modifiers,
            maxHP,
            maxKi,
            currentHP: maxHP,
            currentKi: maxKi,
            fatigue: 0,
            peakFatigue: 0,
            powerLevel,
            rebirthSaga: globalSaga,
            deathLocation: null,
            deathSpace: null,
            deathAlignmentValue: null
        });
        if (client && client.users && userId) {
            client.users.send(userId, `🥚 **${character.name}** was slain, but their **Namekian egg** hatches! They are **reborn** at **${spawnLocation} - Space ${spawnSpace}** (100%+${Math.round((keepPct - 1) * 100)}% of old stats kept).`).catch(() => {});
        }
        return { name: character.name, reborn: true };
    }

    const deathAlignValue = getPlayerAlignmentValue(character);
    // Negative-alignment souls go to Hell; everyone else goes to the Otherworld.
    const afterlife = deathAlignValue < 0 ? 'Hell' : 'Otherworld';
    const updates = {
        dead: true,
        location: afterlife,
        space: 1,
        currentHP: 0,
        deathAlignmentValue: deathAlignValue,
        deathAlignment: character.alignment,
        deathLocation: character.location || 'Earth',
        deathSpace: character.space || 1
    };
    if (afterlife === 'Hell') updates.hellSaga = globalSaga;
    characterManager.updateCharacter(userId, character.id, updates);
    // Let the player know where they were sent.
    if (client && client.users && userId) {
        const afterlifeText = afterlife === 'Hell'
            ? `👿 **${character.name}** was killed and sent to **Hell**! (negative alignment)\n\nYou can \`/reincarnate\` — but Hell keeps you for **2 sagas** before you can escape.`
            : `☠️ **${character.name}** was killed and sent to the **Otherworld**!\n\nYou can \`/reincarnate\`, speak to King Yemma with \`/king-yemma\` (if you died with **1000+ positive alignment**), or train in the Otherworld (**3.5x** results, sparring **2x** — use \`/train\`).`;
        client.users.send(userId, afterlifeText).catch(() => {});
    }
    return character;
}

// Post-duel execution choice buttons (winner may execute or spare the loser).
function duelExecutionComponents(battleId) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`duel_execute_${battleId}`).setLabel('⚔️ Execute').setStyle(ButtonStyle.Danger),
        new ButtonBuilder().setCustomId(`duel_spare_${battleId}`).setLabel('💠 Spare').setStyle(ButtonStyle.Success)
    );
}

function checkBattleOver(battle) {
    if (!battle.isBattleOver()) return null;

    battle.active = false;
    clearBattleTurnTimer(battle);
    battleManager.endBattle(battle.id);
    battleMessages.delete(battle.id);

    const alive = battle.turnOrder.filter(p => !p.isDead && !p.isIncapacitated);

    // Saiyans unlock Super Saiyan automatically at 3M PL
    let unlockText = '';
    // Non-spar battles generate fatigue based on HP lost (max 25%); surfaced in the battle-over message.
    let battleFatigueText = '';

    // Conscious participants can roll for mastery after the fight;
    // Zenkai mutations trigger for survivors under 10% HP
    battle.turnOrder.forEach(p => {
        if (!isNPC(p)) {
            // Companion post-battle handling: revert any form and bank a Zenkai if they survived near death.
            if (isCompanion(p)) {
                const { companion } = getParticipantEntity(p);
                if (companion) {
                    if (companion.activeForm) {
                        companion.activeForm = null;
                        const owner0 = characterManager.getCharacter(p.ownerUserId);
                        if (owner0) characterManager.updateCharacter(p.ownerUserId, owner0.id, { companions: owner0.companions });
                    }
                    if (!p.isDead) {
                        let gainPercent = 0;
                        let threshold = 0.1;
                        let zenkaiSource = '';
                        if (companion.race === 'Saiyan') {
                            gainPercent = getRandomInt(8); // Saiyan Zenkai: PL x (1d8/100)
                            zenkaiSource = 'Saiyan Zenkai';
                            if (companion.class === 'Low Class') threshold = 0.2;
                        } else if (companion.race === 'Half-Saiyan') {
                            gainPercent = getRandomInt(4); // Half-Saiyan Zenkai: PL x (1d4/100)
                            zenkaiSource = 'Half-Saiyan Zenkai';
                        }
                        if (battle.isSpar) gainPercent = Math.floor(gainPercent * 0.2);
                        const zenkaiMaxHP = p.hp || 1;
                        if (gainPercent > 0 && p.currentHP < zenkaiMaxHP * threshold) {
                            const points = Math.max(1, Math.ceil((p.powerLevel || 1) * gainPercent / 100));
                            companion.zenkaiPending = { source: zenkaiSource, gainPercent, powerLevel: p.powerLevel || 1 };
                            const owner = characterManager.getCharacter(p.ownerUserId);
                            if (owner) characterManager.updateCharacter(p.ownerUserId, owner.id, { companions: owner.companions });
                            unlockText += `\n✨ **ZENKAI pending!** **${companion.name}** survived near death (${zenkaiSource}) — heal them back to **full HP** to trigger it (+${points} stat points)!`;
                        }
                    }
                }
                return;
            }
            const participantChar = characterManager.getCharacter(p.userId);
            if (!participantChar) return;
            // After a battle, characters revert to base form (no transformation persists).
            if (participantChar.activeForm) {
                characterManager.updateCharacter(p.userId, participantChar.id, { activeForm: null });
            }
            if (p.isDead) return;

            // Survivors: mark mastery ready. Knocked-out (but not dead): wake up with 1 HP.
            if (!p.isIncapacitated) {
                characterManager.updateCharacter(p.userId, participantChar.id, { masteryReady: true });
            } else {
                const kiLeft = Math.max(0, p.currentKi || 0);
                characterManager.updateCharacter(p.userId, participantChar.id, {
                    currentHP: 1,
                    currentKi: Math.min(participantChar.maxKi || kiLeft, kiLeft)
                });
            }

            // Zenkai: survive a battle near death. This is REPEATABLE for Saiyans/Half-Saiyans
            // (and Zenkai mutations), so it checks every non-dead participant — standing or knocked out.
            let gainPercent = 0;
            let threshold = 0.1;
            let zenkaiSource = '';
            if (participantChar.mutation === 'Zenkai Strain') {
                gainPercent = getRandomInt(40) + 15; // 1d40+15
                zenkaiSource = 'Zenkai Strain';
            } else if (participantChar.mutation === 'Extreme Potential') {
                gainPercent = getRandomInt(25) + 15; // 1d25+15
                zenkaiSource = 'Extreme Potential';
            } else if (participantChar.race === 'Saiyan') {
                gainPercent = getRandomInt(8); // Saiyan Zenkai: PL x (1d8/100)
                zenkaiSource = 'Saiyan Zenkai';
                if (participantChar.class === 'Low Class') threshold = 0.2; // Low Class Zenkai (20%)
            } else if (participantChar.race === 'Half-Saiyan') {
                gainPercent = getRandomInt(4); // Half-Saiyan Zenkai: PL x (1d4/100)
                zenkaiSource = 'Half-Saiyan Zenkai';
            }

            // "Less than 10% of your health" refers to MAX HP (not battle-entry HP).
            // Zenkai is EARNED at battle end (near death) but only TRIGGERS when the character heals to full.
            // A sparring (non-combat) Zenkai yields 80% less stats than a real fight.
            if (battle.isSpar) gainPercent = Math.floor(gainPercent * 0.2);
            const zenkaiMaxHP = participantChar.maxHP || p.hp || 1;
            if (gainPercent > 0 && p.currentHP < zenkaiMaxHP * threshold) {
                // Zenkai is limited to 3 charges per saga.
                if (getZenkaiCharges(participantChar) <= 0) {
                    unlockText += `\n⚠️ **${participantChar.name}** would Zenkai, but has **no Zenkai charges** left this saga!`;
                } else {
                    const points = Math.max(1, Math.ceil((participantChar.powerLevel || 1) * gainPercent / 100));
                    characterManager.updateCharacter(p.userId, participantChar.id, {
                        zenkaiPending: { source: zenkaiSource, gainPercent, powerLevel: participantChar.powerLevel || 1 }
                    });
                    unlockText += `\n✨ **ZENKAI pending!** **${participantChar.name}** survived near death (${zenkaiSource}) — heal back to **full HP** to trigger it (+${points} stat points)!`;
                }
            }

            // Persist the HP/Ki you left the battle with (survivors keep their ending HP;
            // the knocked-out wake with 1 HP).
            const finalChar = characterManager.getCharacter(p.userId);
            if (finalChar) {
                const savedHP = p.isIncapacitated ? 1 : Math.max(0, Math.floor(p.currentHP || 0));
                // Battles (not spars) generate fatigue based on how much HP you lost, capped at 25%.
                let battleFatigueGain = 0;
                if (!battle.isSpar && !battle.isCompanionSpar) {
                    const bMaxHP = finalChar.maxHP || p.hp || 1;
                    const lostHP = Math.max(0, bMaxHP - Math.max(0, Math.floor(p.currentHP || 0)));
                    battleFatigueGain = Math.min(25, Math.floor((lostHP / bMaxHP) * 25));
                }
                const newBattleFatigue = Math.min(100, (finalChar.fatigue || 0) + battleFatigueGain);
                characterManager.updateCharacter(p.userId, finalChar.id, {
                    currentHP: Math.min(savedHP, finalChar.maxHP || p.hp || 1),
                    currentKi: Math.min(Math.max(0, Math.floor(p.currentKi || 0)), finalChar.maxKi || 1),
                    fatigue: newBattleFatigue,
                    peakFatigue: Math.max(finalChar.peakFatigue || 0, newBattleFatigue)
                });
                if (battleFatigueGain > 0) {
                    battleFatigueText += `\n😓 **${finalChar.name}** took **${battleFatigueGain}% fatigue** from the fight!`;
                }
            }
        }
    });

    // Mentor fights and quests: reward the winner
    let rewardText = unlockText + battleFatigueText;

    // Limit break reward: entities that broke their limits this battle get d20 + 10% PL stat
    // points. Once broken, the next break needs 150% of the PL they last broke from.
    if (Array.isArray(battle.limitBreakers) && battle.limitBreakers.length > 0) {
        battle.limitBreakers.forEach(uid => {
            const p = battle.turnOrder.find(x => x.userId === uid);
            if (!p || isNPC(p)) return; // enemies are transient — no persistent reward
            const { character, companion } = getParticipantEntity(p);
            if (companion) {
                const cmpPL = getCompanionPowerLevel(companion, character);
                if (companion.lastLimitBreakPL && cmpPL < companion.lastLimitBreakPL * LIMIT_BREAK_PL_REQ) return;
                const points = getRandomInt(LIMIT_BREAK_GAIN_DICE) + Math.floor(cmpPL * LIMIT_BREAK_GAIN_PCT);
                const gains = distributeGain(points, ['str', 'dex', 'con', 'wil', 'spi']);
                const bonusStats = { ...(companion.bonusStats || {}) };
                Object.entries(gains).forEach(([s, g]) => { bonusStats[s] = (bonusStats[s] || 0) + g; });
                companion.bonusStats = bonusStats;
                companion.lastLimitBreakPL = cmpPL;
                companion.limitBreakMult = LIMIT_BREAK_GAIN_MULT;
                if (character) characterManager.updateCharacter(p.ownerUserId, character.id, { companions: character.companions });
                const gainParts = Object.entries(gains).map(([s, g]) => `${s.toUpperCase()}+${g}`).join(' | ');
                rewardText += `\n✨ **${companion.name}** broke their limit! **+${points}** stat points (${gainParts}) — permanent **10×** stat gains (not missions)!`;
            } else if (character) {
                const pl = character.powerLevel || 0;
                const reqMult = character.lastLimitBreakReq || LIMIT_BREAK_PL_REQ;
                if (character.lastLimitBreakPL && pl < character.lastLimitBreakPL * reqMult) return;
                let points = getRandomInt(LIMIT_BREAK_GAIN_DICE) + Math.floor(pl * LIMIT_BREAK_GAIN_PCT);
                let nextReq = LIMIT_BREAK_PL_REQ;
                if (character.doublePotential) {
                    points *= 2;
                    nextReq = LIMIT_BREAK_PL_REQ * 2;
                    character.doublePotential = false;
                }
                characterManager.updateCharacter(p.userId, character.id, {
                    unspentPoints: (character.unspentPoints || 0) + points,
                    lastLimitBreakPL: pl,
                    lastLimitBreakReq: nextReq,
                    limitBreakMult: LIMIT_BREAK_GAIN_MULT
                });
                rewardText += `\n✨ **${character.name}** broke their limit! **+${points} stat points** — permanent **10×** stat gains (not missions)!`;
            }
        });
    }

    let endComponents = [];
    const mentorFight = activeMentorFights.get(battle.id);
    if (mentorFight) activeMentorFights.delete(battle.id);
    const mission = activeMissions.get(battle.id);
    if (mission) activeMissions.delete(battle.id);
    const hunt = activeHunts.get(battle.id);
    if (hunt) activeHunts.delete(battle.id);
    const raidBattle = activeRaidBattles.get(battle.id);
    if (raidBattle) activeRaidBattles.delete(battle.id);

    const winners = alive.filter(p => !isNPC(p));

    // Mentor fight: reward the mentor-fight participant if they won
    if (mentorFight) {
        const winner = winners.find(w => w.userId === mentorFight.userId);
        if (winner) {
            const winnerChar = characterManager.getCharacter(winner.userId);
            if (winnerChar) {
                const style = MENTOR_STYLES[mentorFight.style];
                const choices = getMentorRewardChoices(winnerChar, mentorFight.style);
                if (choices.length > 0) {
                    pendingMentorRewards.set(winner.userId, {
                        style: mentorFight.style,
                        choices,
                        createdAt: Date.now()
                    });
                    endComponents = buildMentorRewardComponents(winner.userId, choices);
                    rewardText += `\n\n🎓 **${style.name}** offers to teach **${winnerChar.name}**. Choose **one** reward below.`;
                } else {
                    rewardText += `\n🧠 ${winnerChar.name} already knows everything this mentor can teach!`;
                }

                // The mentor fight counts as spar training
                const tier = getGravityTier(getTrainingGravity(winnerChar), winnerChar.powerLevel || 0);
                const sparSpec = (winnerChar.mutation === 'Hunter of Legend') ? addDiceToSpec(tier.spar, 2) : tier.spar;
                const sparPoints = Math.floor(rollDiceString(sparSpec) * globalSaga * 3 * getLimitBreakGainMult(winnerChar));
                const sparGains = distributeGain(sparPoints, ['str', 'dex', 'con', 'wil', 'spi']);
                const sparStats = { ...(winnerChar.stats || {}) };
                Object.entries(sparGains).forEach(([stat, pts]) => {
                    sparStats[stat] = (sparStats[stat] || 0) + pts;
                });
                const sparVitals = recalcVitals(winnerChar, sparStats);
                characterManager.updateCharacter(winner.userId, winnerChar.id, {
                    stats: sparStats,
                    modifiers: calculateAllModifiers(sparStats),
                    ...sparVitals,
                    powerLevel: characterManager.calculatePowerLevel({ ...sparStats, maxHP: sparVitals.maxHP, maxKi: sparVitals.maxKi })
                });
                rewardText += checkSaiyanSuperSaiyanUnlock(winner.userId, winnerChar);
                const gainParts = Object.entries(sparGains).map(([s, p]) => `${s.toUpperCase()} +${p}`).join(' | ');
                rewardText += `\n🏋️ Spar training gain: **${gainParts}**`;
            }
        } else {
            // Losing to a mentor still counts as a (reduced) spar training.
            const loserChar = characterManager.getCharacter(mentorFight.userId);
            if (loserChar) {
                const tier = getGravityTier(getTrainingGravity(loserChar), loserChar.powerLevel || 0);
                const sparSpec = (loserChar.mutation === 'Hunter of Legend') ? addDiceToSpec(tier.spar, 2) : tier.spar;
                const sparPoints = Math.max(1, Math.floor(rollDiceString(sparSpec) * globalSaga * 0.5 * 3 * getLimitBreakGainMult(loserChar)));
                const sparGains = distributeGain(sparPoints, ['str', 'dex', 'con', 'wil', 'spi']);
                const sparStats = { ...(loserChar.stats || {}) };
                Object.entries(sparGains).forEach(([stat, pts]) => {
                    sparStats[stat] = (sparStats[stat] || 0) + pts;
                });
                const sparVitals = recalcVitals(loserChar, sparStats);
                characterManager.updateCharacter(mentorFight.userId, loserChar.id, {
                    stats: sparStats,
                    modifiers: calculateAllModifiers(sparStats),
                    ...sparVitals,
                    powerLevel: characterManager.calculatePowerLevel({ ...sparStats, maxHP: sparVitals.maxHP, maxKi: sparVitals.maxKi })
                });
                rewardText += checkSaiyanSuperSaiyanUnlock(mentorFight.userId, loserChar);
                const gainParts = Object.entries(sparGains).map(([s, p]) => `${s.toUpperCase()} +${p}`).join(' | ');
                rewardText += `\n🏋️ Spar training (loss): **${gainParts}**`;
                // The Assassin Mentor is lethal: losing gives a chance to be killed (1d20, save 11).
                if (mentorFight.style === 'Assassin') {
                    const killRoll = getRandomInt(20);
                    if (killRoll < 11) {
                        const deadChar = killCharacter(mentorFight.userId);
                        if (deadChar) {
                            rewardText += deadChar.protected
                                ? `\n🧿 **${deadChar.name}** was protected by the **Ancient Wuxia Talisman** and survived the Assassin!`
                                : deadChar.reborn
                                    ? `\n🥚 **${deadChar.name}** was assassinated by the **Assassin Mentor** (1d20 = **${killRoll}**, save 11), but their **Namekian egg** hatches — they are reborn!`
                                    : `\n☠️ **${deadChar.name}** was assassinated by the **Assassin Mentor** (1d20 = **${killRoll}**, save 11) and sent to **${afterlifeLocationName(deadChar)}**!`;
                        }
                    } else {
                        rewardText += `\n🛡️ The **Assassin Mentor** strikes, but **${loserChar.name}** escapes death! (1d20 = **${killRoll}**, save 11)`;
                    }
                }
            }
        }
    }

    // /hunt (or an NPC hunt quest): on victory, reward the hunter with meat (+ the quest reward).
    if (hunt) {
        winners.forEach(winner => {
            if (winner.userId !== hunt.userId) return;
            const winnerChar = characterManager.getCharacter(winner.userId);
            if (!winnerChar) return;
            const qty = hunt.animal.meatQty();
            const inv = Array.isArray(winnerChar.inventory) ? winnerChar.inventory : [];
            // Hunted meat is raw — it must be cooked before eating.
            for (let k = 0; k < qty; k++) inv.push(makeRawMeat(hunt.animal.meat));
            const statPoints = (hunt.reward && hunt.reward.statPoints) || 0;
            const zeni = (hunt.reward && hunt.reward.zeni) || 0;
            const updates = { inventory: inv };
            if (statPoints || zeni) {
                updates.unspentPoints = (winnerChar.unspentPoints || 0) + statPoints;
                updates.zeni = (winnerChar.zeni || 0) + zeni;
            }
            characterManager.updateCharacter(winner.userId, winnerChar.id, updates);
            rewardText += `\n🏹 **${winnerChar.name}** hunted down the **${hunt.animal.emoji} ${hunt.animal.name}** and got **${qty}× ${hunt.animal.meat}** (raw — cook it with \`/cook\`)!`;
            if (statPoints || zeni) {
                rewardText += `\n🎁 **${winnerChar.name}** completed the NPC quest: **+${statPoints} stat points** and **${zeni.toLocaleString()} zeni**!`;
            }
        });
    }

    // Raid ambush: repelling a raid grants 2× stat gain.
    if (raidBattle) {
        winners.forEach(winner => {
            if (winner.userId !== raidBattle.userId) return;
            const winnerChar = characterManager.getCharacter(winner.userId);
            if (!winnerChar) return;
            const sp = getMissionStatReward(winnerChar.powerLevel || 0, 'casual', globalSaga) * 2;
            characterManager.updateCharacter(winner.userId, winnerChar.id, { unspentPoints: (winnerChar.unspentPoints || 0) + sp });
            rewardText += `\n🐉 **${winnerChar.name}** repelled the **RAID**! **+${sp} stat points** (2× raid bonus)!`;
        });
    }

    // Quest completed: reward every surviving player (co-op missions share the win)
    if (mission) {
        const saga = globalSaga;
        winners.forEach(winner => {
            const winnerChar = characterManager.getCharacter(winner.userId);
            if (!winnerChar) return;
            let statPoints = 0;
            let zeni = 0;
            // Stat rewards now scale with the player's power level (like enemy stats do).
            statPoints = getMissionStatReward(winnerChar.powerLevel || 0, mission.missionType, saga);
            // Enemies called in as reinforcements grant +11% more stats each.
            const reinforcements = mission.reinforcementsCalled || 0;
            if (reinforcements > 0) statPoints = Math.floor(statPoints * (1 + 0.11 * reinforcements));
            if (mission.missionType === 'casual') zeni = 5000;
            else if (mission.missionType === 'hard') zeni = 10000;
            else if (mission.missionType === 'very hard') zeni = 15000;
            else if (mission.missionType === 'saga') {
                for (let i = 0; i < 500; i++) zeni += getRandomInt(100); // 500d100 zeni
            }

            // Winning by talking (recruiting everyone) gives no alignment and only 50% stat rewards.
            const wonByTalk = battle.wonByTalk === true;
            if (wonByTalk) statPoints = Math.floor(statPoints * 0.5);

            // Companions take a 20% cut of the owner's XP each (more companions = less XP for you).
            const compResult = applyCompanionXp(winner.userId, winnerChar, statPoints);
            if (compResult.companions && compResult.companions.length > 0) {
                characterManager.updateCharacter(winner.userId, winnerChar.id, { companions: compResult.companions });
                rewardText += compResult.text;
            }

            const ownedPoints = compResult.ownerPoints;
            const unspent = (winnerChar.unspentPoints || 0) + ownedPoints;
            // Revert the mission-start alignment gain for a talk-win (host only).
            const alignRestore = (wonByTalk && winner.userId === mission.userId)
                ? { alignment: winnerChar.preMissionAlignment || 'Neutral', alignmentValue: Number(winnerChar.preMissionAlignValue) || 0 }
                : {};
            characterManager.updateCharacter(winner.userId, winnerChar.id, {
                unspentPoints: unspent,
                zeni: (winnerChar.zeni || 0) + zeni,
                ...alignRestore
            });
            rewardText += checkSaiyanSuperSaiyanUnlock(winner.userId, winnerChar);
            rewardText += `\n🎁 Quest complete for **${winnerChar.name}**: **+${ownedPoints} stat points** (spend them with \`/allocate\`) and **${zeni.toLocaleString()} zeni**!${wonByTalk ? '\n🗨️ *Won by talking — no alignment gain and reduced rewards.*' : ''}`;
        });
    }

    // PvP spar: both participants earn spar training gains (winner full, loser reduced) and +10% fatigue.
    // Spars must run at least 15 rounds before they count as training (a quick KO earns nothing).
    // PvP spar rewards. Guarded so a re-run of checkBattleOver can't grant them (or the leech) twice.
    if (battle.isSpar && Array.isArray(battle.sparUsers) && !battle.sparRewarded) {
        battle.sparRewarded = true;
        battle.sparUsers.forEach(uid => {
                const p = battle.turnOrder.find(x => x.userId === uid);
                if (!p) return;
                const char = characterManager.getCharacter(uid);
                if (!char) return;
                const won = alive.some(a => a.userId === uid);
                const tier = getGravityTier(getTrainingGravity(char), char.powerLevel || 0);
                const sparSpec = (char.mutation === 'Hunter of Legend') ? addDiceToSpec(tier.spar, 2) : tier.spar;
                let sparPoints = rollDiceString(sparSpec) * globalSaga * 3;
                if (!won) sparPoints = Math.max(1, Math.floor(sparPoints * 0.5));
                // Fatigue reduces spar training gains (like any /train).
                const fatigueMult = getFatigueGainMultiplier(getTotalFatigue(char));
                sparPoints = Math.floor(sparPoints * fatigueMult * getLimitBreakGainMult(char));
                const sparGains = distributeGain(sparPoints, ['str', 'dex', 'con', 'wil', 'spi']);
                // Leech: if the sparring opponent is 250%+ of you, absorb 15% of their stats.
                // Kept separate from the base gains so it isn't double-counted in the result text.
                const opponentUid = (battle.sparUsers || []).find(u => u !== uid);
                const opponentChar = opponentUid ? characterManager.getCharacter(opponentUid) : null;
                const leechStats = { str: 0, dex: 0, con: 0, wil: 0, spi: 0 };
                let leechParts = [];
                if (opponentChar && opponentChar.stats) {
                    const oppPL = opponentChar.powerLevel || 0;
                    const myPL = char.powerLevel || 1;
                    if (oppPL / Math.max(1, myPL) >= 2.5) {
                        ['str', 'dex', 'con', 'wil', 'spi'].forEach(stat => {
                            const leech = Math.max(0, Math.floor((Number(opponentChar.stats[stat]) || 0) * 0.15));
                            if (leech > 0) {
                                leechStats[stat] = leech;
                                leechParts.push(`${stat.toUpperCase()} +${leech}`);
                            }
                        });
                    }
                }
                const sparStats = { ...(char.stats || {}) };
                Object.entries(sparGains).forEach(([stat, pts]) => { sparStats[stat] = (sparStats[stat] || 0) + pts; });
                Object.entries(leechStats).forEach(([stat, pts]) => { sparStats[stat] = (sparStats[stat] || 0) + pts; });
                const sparVitals = recalcVitals(char, sparStats);
                // Sparring is training: both fighters gain +10% fatigue.
                const newFatigue = Math.min(100, (char.fatigue || 0) + 10);
                characterManager.updateCharacter(uid, char.id, { stats: sparStats, modifiers: calculateAllModifiers(sparStats), ...sparVitals, powerLevel: characterManager.calculatePowerLevel({ ...sparStats, maxHP: sparVitals.maxHP, maxKi: sparVitals.maxKi }), fatigue: newFatigue, peakFatigue: Math.max(char.peakFatigue || 0, newFatigue) });
                const gainParts = Object.entries(sparGains).map(([s, p]) => `${s.toUpperCase()} +${p}`).join(' | ');
                rewardText += `\n🏋️ **${char.name}** spar trained (${won ? 'win' : 'loss'}): **${gainParts}**${fatigueMult < 1 ? ` (fatigue ×${fatigueMult})` : ''}\n😓 Fatigue: **+10%**`;
                if (leechParts.length) rewardText += `\n🩸 Leeched from **${opponentChar.name}**: **${leechParts.join(' | ')}**`;
                rewardText += checkSaiyanSuperSaiyanUnlock(uid, char);
            });
    }

    // Companion spar: owner gets spar gains, the companion gains bonus stats.
    if (battle.isCompanionSpar && !battle.companionSparRewarded) {
        battle.companionSparRewarded = true;
        const ownerId = battle.companionOwnerId;
        const ownerChar = characterManager.getCharacter(ownerId);
        if (ownerChar) {
            const won = alive.some(a => a.userId === ownerId);
            const tier = getGravityTier(getTrainingGravity(ownerChar), ownerChar.powerLevel || 0);
            const sparSpec = (ownerChar.mutation === 'Hunter of Legend') ? addDiceToSpec(tier.spar, 2) : tier.spar;
            let sparPoints = rollDiceString(sparSpec) * globalSaga * 3;
            if (!won) sparPoints = Math.max(1, Math.floor(sparPoints * 0.5));
            // Fatigue reduces spar training gains (like any /train).
            const fatigueMult = getFatigueGainMultiplier(getTotalFatigue(ownerChar));
            sparPoints = Math.floor(sparPoints * fatigueMult * getLimitBreakGainMult(ownerChar));
            const sparGains = distributeGain(sparPoints, ['str', 'dex', 'con', 'wil', 'spi']);
            const sparStats = { ...(ownerChar.stats || {}) };
            Object.entries(sparGains).forEach(([stat, pts]) => { sparStats[stat] = (sparStats[stat] || 0) + pts; });
            const sparVitals = recalcVitals(ownerChar, sparStats);
            // Companion sparring is training: +10% fatigue (like any /train).
            const newFatigue = Math.min(100, (ownerChar.fatigue || 0) + 10);
            characterManager.updateCharacter(ownerId, ownerChar.id, { stats: sparStats, modifiers: calculateAllModifiers(sparStats), ...sparVitals, powerLevel: characterManager.calculatePowerLevel({ ...sparStats, maxHP: sparVitals.maxHP, maxKi: sparVitals.maxKi }), fatigue: newFatigue, peakFatigue: Math.max(ownerChar.peakFatigue || 0, newFatigue) });
            const gainParts = Object.entries(sparGains).map(([s, p]) => `${s.toUpperCase()} +${p}`).join(' | ');
            rewardText += `\n🏋️ **${ownerChar.name}** spar trained with their companion (${won ? 'win' : 'loss'}): **${gainParts}**${fatigueMult < 1 ? ` (fatigue ×${fatigueMult})` : ''}\n😓 Fatigue: **+10%**`;
            rewardText += checkSaiyanSuperSaiyanUnlock(ownerId, ownerChar);
        }
        const cmp = (ownerChar && Array.isArray(ownerChar.companions)) ? ownerChar.companions[(battle.companionSlot || 1) - 1] : null;
        if (cmp) {
            const tier = getGravityTier(getTrainingGravity(ownerChar), ownerChar.powerLevel || 0);
            // Companions suffer fatigue like players: their spar gains fall at higher fatigue.
            const cmpFatigueMult = getFatigueGainMultiplier(cmp.fatigue || 0);
            const sparSpec = (cmp.mutation === 'Hunter of Legend') ? addDiceToSpec(tier.spar, 2) : tier.spar;
            let sparPoints = Math.floor(rollDiceString(sparSpec) * globalSaga * 3 * cmpFatigueMult * getLimitBreakGainMult(cmp));
            // When the owner is 250%+ the companion's PL, the companion trains against a far
            // stronger opponent: its spar gains are boosted ×2.5, and it leeches 15% of the
            // owner's current stats as a reward on top.
            let leechText = '';
            let leechGains = [];
            const cStats = getCompanionBattleStats(cmp, ownerChar);
            const cmaxHP = calculateHP(cStats.con, cmp.race || null);
            const cmaxKi = calculateKi(cStats.spi, cmp.race || null);
            const cmpPL = characterManager.calculatePowerLevel({ str: cStats.str, dex: cStats.dex, con: cStats.con, wil: cStats.wil, spi: cStats.spi, maxHP: cmaxHP, maxKi: cmaxKi });
            const gapRatio = (ownerChar.powerLevel || 0) / Math.max(1, cmpPL);
            const leeching = gapRatio >= 2.5;
            if (leeching) {
                sparPoints = Math.floor(sparPoints * 2.5);
                leechText = ' 🏆 (owner 250%+ stronger: gains ×2.5)';
            }
            let gain = distributeGain(sparPoints, ['str', 'dex', 'con', 'wil', 'spi']);
            // Child stat-growth multiplier (0% <6, 15% 6-11, 50% 12-17, 100% 18+).
            if (cmp.isChild) {
                const age = family.getAgeYears(cmp.birthDate);
                gain = distributeGain(Math.max(0, Math.floor(sparPoints * family.getChildGrowthMultiplier(age))), ['str', 'dex', 'con', 'wil', 'spi']);
            }
            const bonusStats = { ...(cmp.bonusStats || {}) };
            Object.entries(gain).forEach(([stat, value]) => { bonusStats[stat] = (bonusStats[stat] || 0) + value; });
            // Leech 15% of the owner's current stats that the companion absorbs.
            if (leeching && ownerChar.stats) {
                ['str', 'dex', 'con', 'wil', 'spi'].forEach(stat => {
                    const leech = Math.max(0, Math.floor((Number(ownerChar.stats[stat]) || 0) * 0.15));
                    if (leech > 0) {
                        bonusStats[stat] = (bonusStats[stat] || 0) + leech;
                        leechGains.push(`${stat.toUpperCase()} +${leech}`);
                    }
                });
            }
            cmp.bonusStats = bonusStats;
            // Direct 1v1 spar builds the strongest bond.
            cmp.companionship = (cmp.companionship || 0) + family.getCompanionshipGain(1, 1);
            // Sparring is training: the companion gains +10% fatigue too, and rests if too tired.
            cmp.fatigue = Math.min(100, (cmp.fatigue || 0) + 10);
            const cmpRestText = companionRestIfNeeded(cmp);
            // Roll for technique mastery after the spar (same chances as a player).
            const masteryText = rollCompanionMastery(cmp);
            const comps = [...(ownerChar.companions || [])];
            comps[(battle.companionSlot || 1) - 1] = cmp;
            characterManager.updateCharacter(ownerId, ownerChar.id, { companions: comps });
            const gainParts = Object.entries(gain).map(([s, p]) => `${s.toUpperCase()} +${p}`).join(' | ');
            rewardText += `\n🤝 **${cmp.name}** gained: **${gainParts}**${cmpFatigueMult < 1 ? ` (fatigue ×${cmpFatigueMult})` : ''}${leechText}${leechGains.length ? `\n🩸 Leeched from **${ownerChar.name}**: **${leechGains.join(' | ')}**` : ''}${cmpRestText}`;
            rewardText += masteryText;
        }
    }

    // Persist any recruited allies as the owner's companions (max 4), for survivors only.
    battle.turnOrder.filter(p => p.recruited && p.ownerUserId && !p.isDead).forEach(p => {
        const ownerChar = characterManager.getCharacter(p.ownerUserId);
        if (ownerChar) {
            rewardText += persistRecruitAsCompanion(p.ownerUserId, p, ownerChar);
        }
    });

    // On a mission loss, enemies may decide to kill the downed players.
    // Mentors never kill, and PvP has no enemies — only missions can result in death.
    let deathText = '';
    if (mission && winners.length === 0) {
        const alignment = mission.alignment || 'positive';
        battle.turnOrder.filter(p => !isNPC(p) && !isCompanion(p)).forEach(p => {
            if (enemiesKillPlayer(mission.missionType, alignment)) {
                const deadChar = killCharacter(p.userId);
                if (deadChar) {
                    if (deadChar.protected) {
                        deathText += `\n🧿 **${deadChar.name}** was protected by the **Ancient Wuxia Talisman** and survived!`;
                    } else if (deadChar.reborn) {
                        deathText += `\n🥚 **${deadChar.name}** was killed by the enemies, but their **Namekian egg** hatches — they are **reborn**!`;
                    } else {
                        deathText += `\n☠️ **${deadChar.name}** was killed by the enemies and sent to **${afterlifeLocationName(deadChar)}**!`;
                    }
                }
            }
        });
    }

    // Post-duel execution: after a legitimate duel, the winner may execute the defeated player.
    if (battle.isDuel && !duelExecutions.has(battle.id)) {
        const winner = winners.find(w => !isNPC(w) && !isCompanion(w));
        const losers = battle.turnOrder.filter(p => !isNPC(p) && !isCompanion(p)
            && (p.isDead || p.isIncapacitated) && p.userId !== (winner && winner.userId));
        if (winner && losers.length === 1) {
            const loser = losers[0];
            duelExecutions.set(battle.id, { winnerId: winner.userId, loserId: loser.userId, resolved: false });
            endComponents = [...endComponents, duelExecutionComponents(battle.id)];
            rewardText += `\n\n⚔️ **${winner.username}** may now **execute** or **spare** **${loser.username}**!`;
        }
    }

    // Rival defeat: if the active rival was present and got beaten, offer Spare / Kill.
    const rivalP = battle.turnOrder.find(p => p.isRival && (p.isDead || p.isIncapacitated));
    if (rivalP && !battle.rivalResolved && rivalP.rivalOwnerId && winners.some(w => w.userId === rivalP.rivalOwnerId)) {
        battle.rivalResolved = true;
        const ownerChar = characterManager.getCharacter(rivalP.rivalOwnerId);
        if (ownerChar && ownerChar.rival) {
            const rival = ownerChar.rival;
            rival.defeats = (rival.defeats || 0) + 1; // rival_defeats
            upgradeRivalGear(rival);
            const flags = getRivalPassiveFlags(rival);
            const passives = flags.passives;
            // Persist unlocked passives so a recruited rival keeps them as a companion.
            rival.flying = flags.flying || false;
            rival.kiSense = flags.kiSense || false;
            rival.kiAppDamage = flags.kiAppDamage || 0;
            rival.passives = passives;
            const killChance = getRivalKillChance(rival);
            const killRoll = getRandomInt(100);
            const killUnlocked = killRoll <= killChance;
            pendingRivalResolutions.set(rivalP.rivalOwnerId, { ownerId: rivalP.rivalOwnerId, ownerCharId: ownerChar.id, killUnlocked, killRoll });
            characterManager.updateCharacter(rivalP.rivalOwnerId, ownerChar.id, { rival });
            rewardText += `\n\n⚔️ **${rival.name}** has been defeated! (defeats: **${rival.defeats}**)`;
            rewardText += `\n🧠 Passive abilities: ${passives.length ? passives.join(', ') : 'none'}`;
            rewardText += `\n🗣️ Persuasion DC (use **Talk** in fights): **${getRivalPersuasionDC(rival)}**`;
            rewardText += `\n💬 Persuasion progress: **${rival.persuasionProgress || 0}/${RIVAL_RECRUIT_TARGET}**`;
            if (killUnlocked) rewardText += `\n☠️ **Kill (Permanent)** unlocked (**${killRoll} ≤ ${killChance}%**) — you can end them for good!`;
            if (killUnlocked) {
                // The Spare option only appears when you could also kill them.
                const rivalRow = new ActionRowBuilder()
                    .addComponents(new ButtonBuilder().setCustomId(`rival_spare_${rivalP.rivalOwnerId}`).setLabel('🤝 Spare').setStyle(ButtonStyle.Success))
                    .addComponents(new ButtonBuilder().setCustomId(`rival_kill_${rivalP.rivalOwnerId}`).setLabel('☠️ Kill (Permanent)').setStyle(ButtonStyle.Danger));
                endComponents = [...endComponents, rivalRow];
            } else {
                rewardText += `\n🏃 **${rival.name}** limps away, vowing to return...`;
            }
        }
    }

    // Rival generation: after a mission win with no active rival, a defeated non-boss enemy may
    // become the player's rival (20% roll).
    if (mission && winners.some(w => w.userId === mission.userId)) {
        const hostId = mission.userId;
        if (!hasActiveRival(hostId) && getRandomInt(100) <= RIVAL_GENERATE_CHANCE) {
            const defeated = battle.turnOrder.filter(p => isNPC(p) && !p.isAlly && !p.isRival && !p.saga && (p.isDead || p.isIncapacitated));
            if (defeated.length > 0) {
                const source = defeated[getRandomInt(defeated.length) - 1];
                const ownerChar = characterManager.getCharacter(hostId);
                if (ownerChar) {
                    const rival = createRivalFromEnemy(ownerChar, source);
                    characterManager.updateCharacter(hostId, ownerChar.id, { rival });
                    rewardText += `\n\n🔥 **A RIVAL has emerged!** **${rival.name}** (${rival.race}) steps forward from the fallen...\n"${rival.name}: **You will regret this! I will return!**"`;
                }
            }
        }
    }

    let content;
    if (alive.length === 0) {
        content = '💀 **BATTLE OVER!** Everyone is down.' + deathText + rewardText;
    } else if (winners.length > 0) {
        const names = winners.map(w => w.username).join(', ');
        content = `🏆 **BATTLE OVER!** **${names}** win${winners.length === 1 ? 's' : ''} the battle!` + rewardText;
    } else {
        content = '💀 **BATTLE OVER!** The enemies win!' + deathText + rewardText;
    }
    return { content: clampMessage(content), components: endComponents };
}

// Trigger a pending Zenkai once the character has healed back to full HP.
// Returns a short message (or ''). Clears the pending flag on trigger.
function checkPendingZenkai(userId, character) {
    if (!character || !character.zenkaiPending) return '';
    if ((character.currentHP || 0) < (character.maxHP || 1)) return '';
    const pending = character.zenkaiPending;
    // Zenkai is limited to 3 charges per saga.
    const charges = getZenkaiCharges(character);
    if (charges <= 0) {
        characterManager.updateCharacter(userId, character.id, { zenkaiPending: null });
        return `\n⚠️ **${character.name}** healed back to full HP, but has **no Zenkai charges** left this saga!`;
    }
    const points = Math.max(1, Math.ceil((pending.powerLevel || character.powerLevel || 1) * pending.gainPercent / 100));
    const zenkaiStats = { ...(character.stats || {}) };
    const distribution = distributeGain(points, ['str', 'dex', 'con', 'wil', 'spi']);
    Object.entries(distribution).forEach(([stat, value]) => {
        zenkaiStats[stat] = (zenkaiStats[stat] || 0) + value;
    });
    const zenkaiVitals = recalcVitals(character, zenkaiStats);
    const exhaustedUntil = Date.now() + ZENKAI_EXHAUST_MS;
    characterManager.updateCharacter(userId, character.id, {
        stats: zenkaiStats,
        modifiers: calculateAllModifiers(zenkaiStats),
        ...zenkaiVitals,
        powerLevel: characterManager.calculatePowerLevel({ ...zenkaiStats, maxHP: zenkaiVitals.maxHP, maxKi: zenkaiVitals.maxKi }),
        zenkaiPending: null,
        zenkaiCharges: charges - 1,
        zenkaiSaga: globalSaga,
        zenkaiExhaustedUntil: exhaustedUntil
    });
    return `\n✨ **ZENKAI!** **${character.name}** healed back to full HP (${pending.source}) and gained **+${points} stat points**! (Zenkai charges left: **${charges - 1}/${ZENKAI_CHARGES_PER_SAGA}** this saga)\n😮‍💨 **${character.name}** is exhausted for **24 hours** (disadvantage on physical checks, reduced Ki recovery)!`;
}

// Pause helper so NPC turns play out visibly (~1s per action)
function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Auto-resolve NPC turns until a player's turn comes up.
// onProgress: optional async (text) => {} called after each NPC action so players can watch.
// Recompute an NPC's fatigue from their missing Ki (enemies suffer the same fatigue penalties as players).
function updateNPCFatigue(npc) {
    npc.currentFatigue = Math.min(100, getKiFatigue(npc.currentKi || 0, npc.ki || 1));
    // Apply the same flat stat-mod penalties from the Trello "Fatigue" card.
    const mods = getFatigueMods(npc.currentFatigue);
    npc.modBonus = { ...(npc.modBonus || {}), str: mods.str, dex: mods.dex, spi: mods.spi, con: mods.con };
}

// Execute a technique on behalf of an NPC. Returns { text, used }.
async function runNPCSkill(battle, npc, target, skillName, onProgress, text) {
    const skill = COMBAT_SKILLS[skillName];
    if (!skill) return { text, used: false };
    // A technique that needs a target can't run when none was passed (e.g. bonus actions like
    // Leaping Tiger Fist are dispatched with target=null — skip them safely).
    if (skill.needsTarget && !target) return { text, used: false };

    const maxKi = npc.ki || 0;
    let kiCost = 0;
    switch (skill.ki) {
        case 'pct5': kiCost = Math.max(1, Math.round(maxKi * 0.05)); break;
        case 'd10pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(10) / 100)); break;
        case 'd10-2pct': kiCost = Math.max(1, Math.round(maxKi * Math.max(1, battle.rollDice(10) - 2) / 100)); break;
        case 'd20pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(20) / 100)); break;
        case 'd12pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(12) / 100)); break;
        case 'd14pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(14) / 100)); break;
        case 'd15pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(15) / 100)); break;
        case 'd16pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(16) / 100)); break;
        case 'd18pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(18) / 100)); break;
        case 'd35pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(35) / 100)); break;
        case 'd40pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(40) / 100)); break;
        case 'd25pct': kiCost = Math.max(1, Math.round(maxKi * battle.rollDice(25) / 100)); break;
        case 'flat3': kiCost = 3; break;
        case 'flat5': kiCost = 5; break;
        case 'flat10': kiCost = 10; break;
        case 'flat15': kiCost = 15; break;
        case 'flat20': kiCost = 20; break;
        case 'flat30': kiCost = 30; break;
        case 'flat45': kiCost = 45; break;
        default: kiCost = 0;
    }
    // Turning OFF a sustained passive (lowering Ki Sense, landing) is free — conserve Ki / manage fatigue.
    if ((skillName === 'Ki Sense' && npc.kiSense) || (skillName === 'Fly' && npc.flying) || (skillName === 'Ki Application' && npc.kiApplicationActive)) {
        kiCost = 0;
    }
    if (npc.currentKi < kiCost) return { text, used: false };
    if (skill.cost === 'action' && npc.hasActed) return { text, used: false };
    if (skill.cost === 'bonus' && npc.hasBonusActed) return { text, used: false };
    if (skill.cost === 'action+bonus' && (npc.hasActed || npc.hasBonusActed)) return { text, used: false };

    // Consume action/bonus + Ki, then recompute fatigue.
    if (skill.cost === 'action') npc.hasActed = true;
    else if (skill.cost === 'bonus') npc.hasBonusActed = true;
    else if (skill.cost === 'action+bonus') { npc.hasActed = true; npc.hasBonusActed = true; }
    npc.currentKi -= kiCost;
    updateNPCFatigue(npc);

    let log = `🧠 **${npc.username}** uses **${skill.name}**! (${kiCost} Ki)\n`;

    const dexMod = battle.getEffectiveModifier(npc, 'dex');
    const strMod = battle.getEffectiveModifier(npc, 'str');
    const wilMod = battle.getEffectiveModifier(npc, 'wil');
    const conMod = battle.getEffectiveModifier(npc, 'con');

    if (skillName === 'Fly') {
        npc.flying = !npc.flying;
        log += npc.flying ? `🕊️ **${npc.username}** is flying!\n` : `🕊️ ${npc.username} landed.\n`;
    } else if (skillName === 'Ki Sense') {
        npc.kiSense = !npc.kiSense;
        log += npc.kiSense
            ? `👁️ ${npc.username} activates **Ki Sense**! (+1 defense)\n`
            : `👁️ ${npc.username} lowers their **Ki Sense**.\n`;
    } else if (skillName === 'Ki Application') {
        if (npc.kiApplicationActive) {
            npc.kiApplicationActive = false;
            npc.kiAppDamage = 0;
            log += `💥 ${npc.username} lowers their **Ki Application**.\n`;
        } else {
            npc.kiApplicationActive = true;
            log += `💥 ${npc.username} activates **Ki Application**!\n`;
        }
    } else if (skillName === 'Ki Sharpening') {
        npc.kiSharpened = true;
        log += `⚔️ ${npc.username} sharpens their attack! (+1d4 next damage)\n`;
    } else if (skillName === 'Pump Up') {
        const enhanced = hasEnhancedPumpUp(npc);
        if (npc.pumpUpActive) {
            npc.pumpUpActive = false;
            npc.pumpUpCost = 0;
            const pmods = npc.pumpUpMods || {};
            npc.modBonus = npc.modBonus || {};
            ['str', 'con', 'dex'].forEach(s => {
                npc.modBonus[s] = Math.max(0, (npc.modBonus[s] || 0) - (pmods[s] || 0));
            });
            npc.pumpUpMods = null;
            log += `💪 ${npc.username} **relaxes** their **Pump Up**.\n`;
        } else {
            const pStr = enhanced ? 15 : 10;
            const pCon = enhanced ? 9 : 5;
            const pDex = enhanced ? 4 : -5;
            npc.pumpUpActive = true;
            npc.modBonus = npc.modBonus || {};
            npc.pumpUpMods = { str: pStr, con: pCon, dex: pDex };
            npc.modBonus.str = (npc.modBonus.str || 0) + pStr;
            npc.modBonus.con = (npc.modBonus.con || 0) + pCon;
            npc.modBonus.dex = (npc.modBonus.dex || 0) + pDex;
            npc.pumpUpCost = enhanced ? 10 : 45;
            log += `💪 **${npc.username}** activates **Pump Up**!${enhanced ? ' **(Enhanced)**' : ''} (+${pStr} STR, +${pCon} CON, ${pDex} DEX — drains ${npc.pumpUpCost} Ki/turn)\n`;
            // Enhanced variant is a free action — it doesn't take their turn.
            if (enhanced) npc.hasActed = false;
        }
    } else if (skillName === 'Shove') {
        // Shove (Wrestler): target makes a DEX save vs DC d20+CON mod, or they're Off-Balance (-50% DEX defense).
        // Success gives the shover their action back (extra action), like the player version.
        // Crushing Physicality: a Wrestler substitutes STR for CON in the shove's attack roll.
        const dc = battle.rollDice(20) + battle.getEffectiveModifier(npc, npc.fightingStyle === 'Wrestler' ? 'str' : 'con');
        const save = battle.rollDice(20) + battle.getEffectiveModifier(target, 'dex');
        if (save >= dc) {
            log += `🛡️ **${target.username}** resists the shove (${save} vs ${dc})!`;
        } else {
            target.offBalance = true;
            npc.hasActed = false; // regain the action
            log += `💥 **${target.username}** is shoved OFF-BALANCE! (-50% DEX defense)\n↩️ ${npc.username} regains their action!`;
        }
    } else if (skillName === 'Wolf Fang Fist') {
        // Wolf Fang Fist: gain an extra action and +10% DEX mod on attack rolls this turn.
        npc.hasActed = false; // grant the extra action
        npc.wolfFang = true;
        npc.wolfFangDexPct = 10;
        npc.wolfFangExtraUsed = false;
        log += `🐺 ${npc.username} gains an extra action and **+10% DEX mod** on attack rolls this turn!\n`;
    } else if (skillName === 'Neo Wolf Fang Fist') {
        // Neo Wolf Fang Fist: gain an extra action, +30% DEX mod and +25% STR mod to damage.
        npc.hasActed = false;
        npc.wolfFang = true;
        npc.wolfFangDexPct = 30;
        npc.neoWolfFang = true;
        npc.wolfFangExtraUsed = false;
        log += `🐺 **Neo Wolf Fang Fist!** ${npc.username} gains an extra action, **+30% DEX mod** and **+25% STR mod** to damage!\n`;
    } else if (skillName === 'Whirlwind Kick') {
        // Whirlwind Kick: a spinning kick (d20+DEX vs d20+DEX); hit = 1d9+STR and a CON save or Off-Balance.
        const atkDice = battle.getDexDice(npc.stats.dex);
        const defDice = battle.getDexDice(target.stats.dex);
        let atk = battle.rollDice(atkDice) + dexMod + (npc.weaponAttackMod || 0) + (npc.flying ? 2 : 0);
        if (npc.wolfFang) atk += Math.max(1, Math.round(dexMod * ((npc.wolfFangDexPct || 10) / 100)));
        const def = battle.rollDice(defDice) + battle.getEffectiveModifier(target, 'dex') + (target.flying ? 2 : 0) + (target.kiSense ? 1 : 0);
        log += `💨 Attack Roll: **${atk}** vs Defense Roll: **${def}**\n`;
        if (atk > def) {
            const dmg = battle.rollDice(9) + strMod + (npc.neoWolfFang ? Math.round(strMod * 0.25) : 0);
            target.currentHP -= dmg;
            if (target.currentHP <= 0 && !target.isIncapacitated) target.isIncapacitated = true;
            log += `💥 Hit for **${dmg} damage**!\n`;
            const dc = battle.rollDice(20) + battle.getEffectiveModifier(npc, 'str');
            const save = battle.rollDice(20) + battle.getEffectiveModifier(target, 'con');
            if (save < dc) { target.turnDisadvantage = true; log += `🌀 **${target.username}** is knocked OFF-BALANCE!\n`; }
            else { log += `🛡️ ${target.username} keeps their balance.\n`; }
        } else {
            log += `💨 The kick misses!\n`;
        }
    } else if (skillName === 'Thrusting Strikes') {
        // Legionary: attack twice, but -8 DEX and -10% DEX mod on the attack roll; crit to strike once more.
        const atkDice = battle.getDexDice(npc.stats.dex);
        const defDice = battle.getDexDice(target.stats.dex);
        const atkPenalty = 8 + Math.round(dexMod * 0.10);
        const dmgSides = 5;
        let hits = 0, total = 0, critBonus = false;
        for (let i = 0; i < 2; i++) {
            const rawAtk = battle.rollDice(atkDice);
            let atk = rawAtk + dexMod - atkPenalty;
            if (atk < 0) atk = 0;
            const def = battle.rollDice(defDice) + battle.getEffectiveModifier(target, 'dex');
            if (atk > def) {
                hits++;
                total += rollXdY(2, dmgSides) + strMod;
                if (rawAtk === atkDice) critBonus = true;
            } else {
                log += `💨 A thrust misses!\n`;
            }
        }
        if (critBonus && hits > 0) {
            const extra = battle.rollDice(5) + Math.round(strMod / 4);
            total += extra; hits++;
            log += `⚡ **Critical thrust!** An extra strike lands for **${extra} damage**!\n`;
        }
        if (hits === 0) {
            log += `💨 The polearm thrusts miss entirely!\n`;
        } else {
            target.currentHP -= total;
            if (target.currentHP <= 0 && !target.isIncapacitated) target.isIncapacitated = true;
            log += `🔱 **${hits}** thrust${hits === 1 ? '' : 's'} hit **${target.username}** for **${total} damage**!\n`;
        }
    } else if (skillName === 'Lacerating Slash') {
        // Legionary: d30+(DEX+CON mod) save vs d20+2×STR; on fail d20+½ STR and Bleed 1 turn.
        const dc = battle.rollDice(20) + (2 * strMod);
        const save = battle.rollDice(30) + dexMod + conMod;
        if (save >= dc) {
            log += `🛡️ **${target.username}** braces against the slash! (${save} vs ${dc})\n`;
        } else {
            const dmg = battle.rollDice(20) + Math.round(strMod / 2);
            target.currentHP -= dmg;
            if (target.currentHP <= 0 && !target.isIncapacitated) target.isIncapacitated = true;
            log += `💥 Hit for **${dmg} damage**!\n`;
            target.bleedTurns = (target.bleedTurns || 0) + 1;
            log += `🩸 **${target.username}** starts BLEEDING for **1 turn**!\n`;
        }
    } else if (skillName === 'Kamehameha') {
        // Turtle charge mechanic for enemies/companions: charge one turn, release the next.
        if (npc.kamehamehaCharging) {
            const atkDice = battle.getDexDice(npc.stats.dex);
            const defDice = battle.getDexDice(target.stats.dex);
            let atk = battle.rollDice(atkDice) + dexMod + (npc.flying ? 2 : 0);
            if (npc.weaponAttackMod) atk += npc.weaponAttackMod;
            const def = battle.rollDice(defDice) + battle.getEffectiveModifier(target, 'dex') + (target.flying ? 2 : 0) + (target.kiSense ? 1 : 0);
            const chargeBonus = (npc.kamehamehaCharge || 0) * 2;
            if (atk > def) {
                const dmg = battle.rollDice(10) + wilMod + chargeBonus;
                target.currentHP -= dmg;
                if (target.currentHP <= 0 && !target.isIncapacitated) target.isIncapacitated = true;
                log += `💥 **Kamehameha!** ${npc.username} releases the charge for **${dmg} damage**!\n`;
            } else {
                log += `💨 The charged Kamehameha misses!\n`;
            }
            npc.kamehamehaCharging = false;
            npc.kamehamehaCharge = 0;
        } else {
            npc.kamehamehaCharging = true;
            npc.kamehamehaCharge = 1;
            log += `🔵 **${npc.username}** begins charging a **Kamehameha**!\n`;
        }
    } else if (skill.attack) {
        const atkDice = battle.getDexDice(npc.stats.dex);
        const defDice = battle.getDexDice(target.stats.dex);
        let atk = battle.rollDice(atkDice) + dexMod;
        if (npc.weaponAttackMod) atk += npc.weaponAttackMod;
        if (npc.flying) atk += 2;
        if (npc.wolfFang) atk += Math.max(1, Math.round(dexMod * ((npc.wolfFangDexPct || 10) / 100)));
        // Cerealian "Evolved Right Eye": spend Ki to reroll the strike (once per attack).
        if (npc.race === 'Cerealian' && !npc.evolvedRightEyeUsed && (npc.currentKi || 0) > 0) {
            const eyeCost = npc.mutation === 'Hunter of Legend' ? 5 : 7;
            if ((npc.currentKi || 0) >= eyeCost) {
                let eyeReroll = battle.rollDice(atkDice);
                if (npc.mutation === 'Hunter of Legend') eyeReroll += 2;
                npc.evolvedRightEyeUsed = true;
                if (eyeReroll > atk) {
                    npc.currentKi -= eyeCost;
                    atk = eyeReroll;
                    log += `👁️ **${npc.username}**'s **Evolved Right Eye** rerolls the strike! (${eyeReroll})\n`;
                }
            }
        }
        let def = battle.rollDice(defDice) + battle.getEffectiveModifier(target, 'dex');
        if (target.flying) def += 2;
        const hit = atk > def;
        log += `Attack Roll: **${atk}** vs Defense Roll: **${def}**\n`;
        if (hit) {
            let dmg;
            if (skill.vitalStrike) {
                // Vital Strike is a precision (DEX) strike: scale damage with DEX dice + DEX mod.
                dmg = battle.rollDice(battle.getStrDice(npc.stats.dex)) + dexMod;
            } else {
                const m = /^(\d+)d(\d+)$/i.exec(skill.attack.dice);
                const count = m ? parseInt(m[1], 10) : 1;
                const sides = m ? parseInt(m[2], 10) : 8;
                dmg = 0;
                for (let i = 0; i < count; i++) dmg += battle.rollDice(sides);
                const statModName = skill.attack.mod || 'str';
                const statMod = statModName === 'wil' ? wilMod : statModName === 'dex' ? dexMod : strMod;
                dmg += statMod;
            }
            if (npc.kiAppDamage) dmg += npc.kiAppDamage;
            // Cerealian "Vital Strike": drains Energy from the target (10, or d16+WIL for Hunter of Legend).
            if (skill.vitalStrike && (target.currentKi || 0) > 0) {
                const vsDrain = npc.mutation === 'Hunter of Legend' ? (battle.rollDice(16) + wilMod) : 10;
                target.currentKi = Math.max(0, (target.currentKi || 0) - vsDrain);
                log += `🎯 **Vital Strike** drains **${vsDrain} Energy** from **${target.username}**!\n`;
            }
            dmg = Math.max(dmg, 0);
            // Crane's Mark: an NPC ki attacker deals +1d15 extra damage to a marked entity.
            if (npc.fightingStyle === 'Crane' && target.craneMarkTurns > 0) {
                const markBonus = battle.rollDice(15);
                dmg += markBonus;
                log += `🐦 **Crane's Mark** adds **+${markBonus} damage**!\n`;
            }
            target.currentHP -= dmg;
            if (target.currentHP <= 0 && !target.isIncapacitated) target.isIncapacitated = true;
            log += `💥 Hit for **${dmg} damage**!\n`;
            // Crane's Marking Strike: a Crane's ki technique marks the opponent for 1d5 turns.
            if (npc.fightingStyle === 'Crane' && !target.isIncapacitated) {
                const markTurns = battle.rollDice(5);
                if (markTurns > (target.craneMarkTurns || 0)) {
                    target.craneMarkTurns = markTurns;
                    target.craneMarkBy = npc.userId;
                    log += `🐦 **Crane's Marking Strike!** **${target.username}** is MARKED for **${markTurns} turn${markTurns === 1 ? '' : 's'}** (-10% DEX)!\n`;
                }
            }
            // Technique save effects (e.g. Legionary Sweeping Swing's Prone).
            const saveSpec = skill.attack.save;
            if (saveSpec) {
                const dc = saveSpec.dc.mod === 'str' ? battle.rollDice(18) + strMod
                    : battle.rollDice(20) + battle.getEffectiveModifier(npc, saveSpec.dc.mod);
                const save = battle.rollDice(20) + battle.getEffectiveModifier(target, saveSpec.vs);
                if (save < dc) {
                    if (saveSpec.effect === 'offbalance') { target.turnDisadvantage = true; log += `🌀 **${target.username}** is knocked OFF-BALANCE!\n`; }
                    else if (saveSpec.effect === 'disadvantage') { target.nextAttackDisadvantage = true; log += `⚠️ ${target.username} has disadvantage on their next attack!\n`; }
                    else if (saveSpec.effect === 'stun') { target.stunned = true; target.stunnedTurns = 1; log += `⚡ **${target.username}** is STUNNED!\n`; }
                    else if (saveSpec.effect === 'prone') { target.offBalance = true; target.turnDisadvantage = true; log += `🦵 **${target.username}** is knocked PRONE (off-balance)!\n`; }
                    else if (saveSpec.effect === 'bleed') { target.bleedTurns = (target.bleedTurns || 0) + 1; log += `🩸 **${target.username}** starts BLEEDING!\n`; }
                } else {
                    log += `🛡️ ${target.username} resists! (${save} vs ${dc})\n`;
                }
            }
        } else {
            log += `💨 Missed!\n`;
        }
    } else {
        // Can't execute this skill generically; refund and bail.
        npc.currentKi += kiCost;
        if (skill.cost === 'action') npc.hasActed = false;
        else if (skill.cost === 'bonus') npc.hasBonusActed = false;
        else if (skill.cost === 'action+bonus') { npc.hasActed = false; npc.hasBonusActed = false; }
        updateNPCFatigue(npc);
        return { text, used: false };
    }

    text += log;
    if (onProgress) await onProgress(text);
    await sleep(200);
    return { text, used: true };
}

// How generously an NPC spends Ki on abilities as their Ki runs low.
// Between ~60% and 40% Ki they start conserving; below 40% they use abilities sparingly.
function getNpcKiConservationFactor(kiRatio) {
    if (kiRatio >= 0.6) return 1;
    if (kiRatio <= 0.4) return 0.15;
    return 0.15 + (kiRatio - 0.4) / 0.2 * 0.85; // 0.4 -> 0.15, 0.6 -> 1.0
}

// Auto-resolve NPC turns until a player's turn comes up.
// onProgress: optional async (text) => {} called after each NPC action so players can watch.
// Namekian Flexible: NPC Namekians auto-spend 8 Ki for +4 to grapple attempts.
function npcGrappleOptions(p) {
    if (p && p.race === 'Namekian' && (p.currentKi || 0) >= 8) {
        p.currentKi -= 8;
        return { grappleBonus: 4 };
    }
    return {};
}

async function resolveNPCTurns(battle, logText, onProgress = null) {
    let text = logText;

    while (battle.active && !battle.isBattleOver()) {
        const current = battle.getCurrentTurn();
        // Auto-resolve both enemies AND player-side allies/companions (companions act for you).
        if (!current || (!isNPC(current) && !isCompanion(current))) break;

        const isAllyTurn = isCompanion(current);
        const targets = isAllyTurn ? getEnemyTargets(battle) : getPlayerTargets(battle);
        if (targets.length === 0) {
            battle.active = false;
            break;
        }

        let target = targets[Math.floor(Math.random() * targets.length)];
        // Assassins strike the weakest foe: pick the lowest-HP target.
        if (current.fightingStyle === 'Assassin' && targets.length > 1) {
            target = targets.reduce((low, t) => (t.currentHP < low.currentHP ? t : low));
        }

        // Enemies (and allies) suffer the same fatigue penalties as players when low on Ki.
        updateNPCFatigue(current);

        // Chance to use a technique scales with Ki and falls as fatigue rises.
        const tools = Array.isArray(current.techniques) ? current.techniques : [];
        // Bonus toggles: skip any already-active sustained passive so the NPC doesn't waste Ki re-activating it.
        const bonusTools = tools.filter(t => COMBAT_SKILLS[t] && COMBAT_SKILLS[t].cost === 'bonus'
            && !(t === 'Ki Sense' && current.kiSense)
            && !(t === 'Fly' && current.flying)
            && !(t === 'Ki Application' && current.kiApplicationActive));
        const offensive = tools.filter(t => COMBAT_SKILLS[t] && (COMBAT_SKILLS[t].cost === 'action' || COMBAT_SKILLS[t].cost === 'action+bonus'));
        const kiRatio = current.currentKi / (current.ki || 1);
        const fatigue = current.currentFatigue || 0;
        const conserve = getNpcKiConservationFactor(kiRatio);

        // Manage fatigue: when conserving Ki, drop an active Ki Sense (free) to save Ki.
        if (current.kiSense && conserve < 0.5) {
            current.kiSense = false;
            text += `👁️ ${current.username} lowers their **Ki Sense** to conserve Ki.\n`;
        }

        // Optional bonus ability first (Fly / Ki Sense).
        if (bonusTools.length > 0 && current.currentKi > 0 && !current.hasBonusActed) {
            const chance = Math.max(0.02, Math.min(0.6, (0.15 + kiRatio * 0.4 - (fatigue / 100) * 0.3) * conserve));
            let skillName = bonusTools[Math.floor(Math.random() * bonusTools.length)];
            // Assassins go invisible (Incognito) before attacking whenever possible.
            const assassinIncognito = current.fightingStyle === 'Assassin' && !current.invisible && bonusTools.includes('Incognito');
            if (assassinIncognito) skillName = 'Incognito';
            if (Math.random() < chance || assassinIncognito) {
                const skillTarget = COMBAT_SKILLS[skillName] && COMBAT_SKILLS[skillName].needsTarget ? target : null;
                const r = await runNPCSkill(battle, current, skillTarget, skillName, onProgress, text);
                text = r.text;
            }
        }

        // Wrestlers: shove (Off-Balance) very often and grapple instead of attacking;
        // basic attacks are only a last resort (when the target is already grappled).
        // Once a Wrestler holds someone, they stay locked on them and attack only that victim
        // until the grapple is broken (no shoving/grappling/switching to a new target).
        if (current.fightingStyle === 'Wrestler' && !current.hasActed) {
            const held = current.grappling
                ? battle.turnOrder.find(p => p.userId === current.grappling && !p.isDead && !p.isIncapacitated)
                : null;
            if (held) {
                target = held;
                text += `🤼 **${current.username}** bears down on **${held.username}**!\n`;
            } else {
                const d = Math.random();
                if (current.currentKi > 0 && !target.offBalance && d < 0.7) {
                    const r = await runNPCSkill(battle, current, target, 'Shove', onProgress, text);
                    text = r.text;
                }
                if (!current.hasActed && !target.grappledBy) {
                    const g = battle.grapple(current.userId, target.userId, npcGrappleOptions(current));
                    if (g.failed) {
                        text += `🤼 **${current.username}** tries to grapple **${target.username}**... (${g.atk} vs ${g.def}) — they break free!\n`;
                    } else if (g.success) {
                        text += `🤼 **${current.username}** GRAPPLES **${target.username}**! (${g.atk} vs ${g.def})\n${target.username} is GRAPPLED: -90% DEX defense!\n`;
                    } else if (g.message) {
                        text += `🤼 ${g.message}\n`;
                    }
                    if (!current.hasActed) current.hasActed = true;
                }
            }
        }

        // Random low chance for any enemy NPC (non-Wrestler — those grapple on their own)
        // to grapple the selected target.
        if (isNPC(current) && current.fightingStyle !== 'Wrestler' && !current.hasActed
            && !target.grappledBy && !current.grappling && Math.random() < 0.1) {
            const g = battle.grapple(current.userId, target.userId, npcGrappleOptions(current));
            if (g.failed) {
                text += `🤼 **${current.username}** tries to grapple **${target.username}**... (${g.atk} vs ${g.def}) — they break free!\n`;
            } else if (g.success) {
                text += `🤼 **${current.username}** GRAPPLES **${target.username}**! (${g.atk} vs ${g.def})\n${target.username} is GRAPPLED: -90% DEX defense!\n`;
            } else if (g.message) {
                text += `🤼 ${g.message}\n`;
            }
            if (!current.hasActed) current.hasActed = true;
        }

        // Offensive technique as the action, or a basic physical attack.
        if (offensive.length > 0 && current.currentKi > 0 && !current.hasActed) {
            const chance = Math.max(0.03, Math.min(0.7, (0.2 + kiRatio * 0.4 - (fatigue / 100) * 0.4) * conserve));
            if (Math.random() < chance) {
                const skillName = offensive[Math.floor(Math.random() * offensive.length)];
                const r = await runNPCSkill(battle, current, target, skillName, onProgress, text);
                text = r.text;
            }
        }

        if (!current.hasActed) {
            const result = await battle.attack(current.userId, target.userId, 'physical', true);
            if (result.success) {
                text = await animateAttackEvent(text, current.username, target, result, onProgress);
                text += `(${current.username} used their action)\n\n`;
                text += tryFalseSuperSaiyanAwakening(battle, target);
                text += tryIntenseAnger(battle, target);
                text += tryHopeOfTheUniverse(battle, target);
                text += tryUltimatePowerAwakening(battle, target);
                // Fearless Strikes (Tiger): a critical refunds the action, so act again without advancing.
                if (result.tigerExtraAction) {
                    text += `🐯 **${current.username}** gets **another action** from **Fearless Strikes** and presses the attack!\n\n`;
                    continue;
                }
                // Wings of the Tempest (Taekwondo): two kick hits grant a free third strike.
                if (result.tempestStrike) {
                    text += `🦶 **${current.username}** gains a **free third strike** from **Wings of the Tempest**!\n\n`;
                    continue;
                }
                // A player defender has a pending dodge reaction — pause for their Yes/No choice.
                if (result.reactionPending) {
                    ensureBattleUI(battle).pendingReaction = target.pendingReaction || null;
                    break;
                }
            }
        } else {
            text += `(${current.username} used their action)\n\n`;
        }

        // Wolf Fang Fist / Neo Wolf Fang Fist grant ONE extra action — act again without advancing.
        if (current.wolfFang && !current.wolfFangExtraUsed) {
            current.wolfFangExtraUsed = true;
            current.hasActed = false;
            text += `🐺 **${current.username}** uses the **extra action** from **Wolf Fang Fist**!\n\n`;
            continue;
        }

        const advance = battle.advance();
        advance.log.forEach(entry => {
            if (entry.type === 'deathSave') text += formatDeathSaveEvent(entry);
            else if (entry.type === 'stun') text += formatStunEvent(entry);
            else if (entry.type === 'kiRegen') text += formatKiRegenEvent(entry);
            else if (entry.type === 'lssjRamp') text += formatLssjRampEvent(entry);
            else if (entry.type === 'bleed') text += formatBleedEvent(entry);
            else if (entry.type === 'rupture') text += formatRuptureEvent(entry);
            else if (entry.type === 'poison') text += formatPoisonEvent(entry);
            else if (entry.type === 'craneMarkExpire') text += formatCraneMarkExpireEvent(entry);
            else if (entry.type === 'hopfDrain') text += formatHopfDrainEvent(entry);
            else if (entry.type === 'passiveDrain') text += formatPassiveDrainEvent(entry);
            else if (entry.type === 'grappleHold') text += formatGrappleHoldEvent(entry);
            else if (entry.type === 'grappleEscape') text += formatGrappleEscapeEvent(entry);
        });

        // Let the player watch each NPC action unfold (~1s per action) only when there's a
        // message being edited. When resolveNPCTurns runs before the battle's first reply
        // (e.g. /hunt), sleeping would push the setup past Discord's 3s reply window and
        // leave the player stuck "in battle" with no visible fight.
        if (onProgress) {
            await onProgress(text);
            await sleep(1000);
        }
    }

    return text;
}

// Advance to the next combatant, auto-run any NPC turns, then re-render the battle message
async function advanceBattleTurn(interaction, battle, introText) {
    // Defer so NPC turns (1s each) don't exceed Discord's 3s interaction window
    await interaction.deferUpdate().catch(() => {});

    let logText = introText ? introText + '\n\n' : '';

    const ending = battle.getCurrentTurn();
    if (ending) ending.wolfFang = false;

    const { log } = battle.advance();
    log.forEach(entry => {
        if (entry.type === 'deathSave') logText += formatDeathSaveEvent(entry);
        else if (entry.type === 'stun') logText += formatStunEvent(entry);
        else if (entry.type === 'kiRegen') logText += formatKiRegenEvent(entry);
        else if (entry.type === 'lssjRamp') logText += formatLssjRampEvent(entry);
        else if (entry.type === 'bleed') logText += formatBleedEvent(entry);
        else if (entry.type === 'rupture') logText += formatRuptureEvent(entry);
        else if (entry.type === 'poison') logText += formatPoisonEvent(entry);
        else if (entry.type === 'craneMarkExpire') logText += formatCraneMarkExpireEvent(entry);
        else if (entry.type === 'grappleHold') logText += formatGrappleHoldEvent(entry);
        else if (entry.type === 'grappleEscape') logText += formatGrappleEscapeEvent(entry);
    });

    logText = await resolveNPCTurns(battle, logText, async (text) => {
        await interaction.editReply({
            content: buildBattleContent(battle, `${text}\n\n⏳ ...`),
            components: []
        }).catch(() => {});
    });
    logText += maybeRivalRescues(battle);
    logText += maybeUnlockShogun(battle, ending);
    logText += maybeCallReinforcements(battle);

    // A player defender dodged and can react — pause for their Yes/No choice.
    if (await maybeShowReactionPrompt(interaction, battle, logText)) return;

    const over = checkBattleOver(battle);
    if (over) {
        return interaction.editReply({ content: clampMessage(`${buildBattleContent(battle, logText)}\n\n${over.content}`), components: over.components });
    }

    return interaction.editReply({
        content: buildBattleContent(battle, logText),
        components: buildTurnComponents(battle, interaction.user)
    });
}

// Handle all battle-related button clicks
async function handleBattleButton(interaction) {
    const battle = battleManager.getBattleForUser(interaction.user.id);

    if (!battle) {
        return interaction.reply({ content: 'You are not in a battle!', ephemeral: true });
    }

    // Only accept clicks on the battle's own message. Battle buttons use shared customIds,
    // so without this another player's battle in the same channel could hijack your actions.
    const battleMsgId = battleMessages.get(battle.id);
    if (battleMsgId && interaction.message && interaction.message.id !== battleMsgId) {
        return interaction.reply({ content: '❌ This button belongs to another battle.', ephemeral: true });
    }

    const customId = interaction.customId;
    const viewer = interaction.user;
    const ui = ensureBattleUI(battle);

    // A dodge reaction (Spirit of the Tiger / Ground Glider / Decisive Strikes) lets the
    // DEFENDER respond even though it's the attacker's turn — handle it before the turn guard
    // so the defender isn't told "it's not your turn".
    if (customId === 'bt_reaction_use' || customId === 'bt_reaction_skip') {
        const pending = ui.pendingReaction;
        if (!pending || pending.defenderUserId !== interaction.user.id) {
            return interaction.reply({ content: '❌ No pending reaction for you!', ephemeral: true });
        }
        const use = customId === 'bt_reaction_use';
        ui.pendingReaction = null;
        const text = battle.resolveDodgeReaction(pending, use);
        const cur = battle.getCurrentTurn();
        if (cur && (isNPC(cur) || isCompanion(cur))) {
            // The interrupt was an NPC's turn — advance and continue auto-resolution.
            return advanceBattleTurn(interaction, battle, text);
        }
        return interaction.update({
            content: buildBattleContent(battle, text || '💨 You chose not to use your reaction.'),
            components: buildTurnComponents(battle, interaction.user)
        });
    }

    if (customId === 'bt_endbattle') {
        const isAdmin = interaction.memberPermissions !== null && interaction.memberPermissions.has(PermissionsBitField.Flags.Administrator);
        if (!isAdmin) {
            return interaction.reply({ content: '❌ Only administrators can end the battle this way. Use `/battle-end`.', ephemeral: true });
        }
        battleManager.endBattle(battle.id);
        battleMessages.delete(battle.id);
        return interaction.update({ content: '⚔️ **Battle ended** by an administrator.', components: [] });
    }

    const current = battle.getCurrentTurn();

    if (!current || current.userId !== viewer.id) {
        return interaction.reply({ content: `It's not your turn! Waiting for ${current ? current.username : 'the battle to end'}.`, ephemeral: true });
    }

    // The current player is acting — drop the stale 10s timer (it's re-armed on the next render).
    clearBattleTurnTimer(battle);

    if (customId === 'bt_attack') {
        if (getAliveTargets(battle, viewer.id).length === 0) {
            return interaction.reply({ content: '❌ No valid targets left!', ephemeral: true });
        }
        ui.mode = 'targets';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose a target below 👇'),
            components: buildTargetComponents(battle, viewer)
        });
    }

    if (customId === 'bt_skills') {
        if (getKnownSkills(viewer).length === 0) {
            return interaction.reply({ content: '❌ You don\'t know any combat techniques!', ephemeral: true });
        }
        ui.mode = 'skills';
        armBattleTurnTimer(battle);
        return interaction.update({
            content: buildBattleContent(battle, 'Choose a technique 👇'),
            components: buildSkillComponents(viewer)
        });
    }

    if (customId === 'bt_transform') {
        const char = characterManager.getCharacter(viewer.id);
        const hasForms = char && Array.isArray(char.forms) && char.forms.some(f => f !== 'False Super Saiyan' && FORMS[f] && formAllowedForRace(FORMS[f], char.race));
        if (!hasForms && !(char && char.activeForm)) {
            return interaction.reply({ content: '❌ You don\'t have any transformations!', ephemeral: true });
        }
        ui.mode = 'transform';
        armBattleTurnTimer(battle);
        return interaction.update({
            content: buildBattleContent(battle, 'Choose a form 👇'),
            components: buildTransformComponents(viewer)
        });
    }

    if (customId === 'bt_transform_revert') {
        const char = characterManager.getCharacter(viewer.id);
        if (char && char.activeForm) {
            characterManager.updateCharacter(viewer.id, char.id, { activeForm: null });
            const fresh = characterManager.getCharacter(viewer.id) || char;
            const bs = applyFormToStats(fresh);
            const p = battle.getCurrentTurn();
            if (p && p.userId === viewer.id) {
                p.stats = bs.stats;
                p.modBonus = bs.modBonus;
                p.kiAppDamage = bs.kiAppDamage;
                p.lssjActive = false;
                p.formName = null;
                p.formDrain = 0;
                p.formMods = null;
                p.kiRegen = getBattleKiRegen(fresh);
            }
            ui.mode = 'turn';
            return interaction.update({
                content: buildBattleContent(battle, `⬇️ **${fresh.name}** reverted to base form.`),
                components: buildTurnComponents(battle, viewer)
            });
        }
        ui.mode = 'turn';
        return interaction.update({ content: buildBattleContent(battle), components: buildTurnComponents(battle, viewer) });
    }

    if (customId.startsWith('bt_transform_')) {
        const formName = customId.slice('bt_transform_'.length);
        const char = characterManager.getCharacter(viewer.id);
        if (!char) {
            return interaction.reply({ content: '❌ No character found!', ephemeral: true });
        }
        if (formName === 'False Super Saiyan') {
            return interaction.reply({ content: '❌ **False Super Saiyan** cannot be transformed into manually — it awakens automatically in battle!', ephemeral: true });
        }
        const form = FORMS[formName];
        if (!form || !Array.isArray(char.forms) || !char.forms.includes(formName)) {
            return interaction.reply({ content: '❌ You don\'t have that form!', ephemeral: true });
        }
        if (!formAllowedForRace(form, char.race)) {
            const raceText = Array.isArray(form.race) ? form.race.join('/') : form.race;
            return interaction.reply({ content: `❌ **${formName}** is a ${raceText} form!`, ephemeral: true });
        }
        if (char.activeForm === formName) {
            return interaction.reply({ content: `❌ You are already in **${formName}**!`, ephemeral: true });
        }
        // Hera forms have trigger conditions (Trello "Ultra Power"/"Ultimate Power" cards).
        if (formName === 'Ultimate Power') {
            return interaction.reply({ content: '❌ **Ultimate Power** awakens automatically when you suffer a **traumatic experience** in battle — you can\'t transform manually!', ephemeral: true });
        }
        if (formName === 'Ultra Power') {
            const cur = battle.getCurrentTurn();
            if (cur && cur.userId === viewer.id && (cur.currentHP || 0) > (cur.hp || 1) * 0.7) {
                return interaction.reply({ content: '❌ **Ultra Power** can only be triggered at **70% HP or lower**!', ephemeral: true });
            }
        }
        characterManager.updateCharacter(viewer.id, char.id, { activeForm: formName });
        const fresh = characterManager.getCharacter(viewer.id) || char;
        const bs = applyFormToStats(fresh);
        const p = battle.getCurrentTurn();
        if (p && p.userId === viewer.id) {
            p.stats = bs.stats;
            p.modBonus = bs.modBonus;
            p.kiAppDamage = bs.kiAppDamage;
            p.lssjActive = fresh.activeForm === 'Legendary Super Saiyan';
            p.formName = bs.gear ? bs.gear.formName : fresh.activeForm;
            p.formDrain = bs.gear ? bs.gear.formDrain : 0;
            p.formMods = bs.gear ? bs.gear.formMods : null;
            // Frost Demon suppression forms (and racial Ki regen) apply once transformed.
            p.kiRegen = getBattleKiRegen(fresh);
            // Ultra Power takes an action to transform (Trello card).
            if (formName === 'Ultra Power') p.hasActed = true;
        }
        ui.mode = 'turn';
        return interaction.update({
            content: buildBattleContent(battle, `🔥 **${fresh.name}** transformed into **${formName}**!`),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId === 'bt_grapple') {
        if (current.hasActed) {
            return interaction.reply({ content: '❌ You already used your action this turn!', ephemeral: true });
        }
        if (getAliveTargets(battle, viewer.id).length === 0) {
            return interaction.reply({ content: '❌ No valid targets left!', ephemeral: true });
        }
        ui.mode = 'grappleTargets';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose who to grapple 👇'),
            components: buildGrappleTargetComponents(battle, viewer)
        });
    }

    if (customId === 'bt_regen') {
        if (current.race !== 'Namekian') {
            return interaction.reply({ content: '❌ Only **Namekians** can use **Regeneration**!', ephemeral: true });
        }
        if (current.hasActed) {
            return interaction.reply({ content: '❌ You already used your action this turn!', ephemeral: true });
        }
        const regenCost = 10;
        if ((current.currentKi || 0) < regenCost) {
            return interaction.reply({ content: `❌ You need **${regenCost} Ki** to regenerate!`, ephemeral: true });
        }
        current.currentKi -= regenCost;
        const beforeHP = current.currentHP || 0;
        current.currentHP = Math.min(current.hp || current.maxHP, beforeHP + regenCost);
        const healed = current.currentHP - beforeHP;
        current.hasActed = true;
        current.hasBonusActed = true;
        ui.mode = 'turn';
        return interaction.update({
            content: buildBattleContent(battle, `🩹 **${current.username}** regenerates **${healed} HP** (${regenCost} Ki → ${regenCost} HP)!`),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId === 'bt_eye') {
        if (current.race !== 'Cerealian') {
            return interaction.reply({ content: '❌ Only **Cerealians** can use **Evolved Right Eye**!', ephemeral: true });
        }
        const newVal = current.eyeRerollEnabled === false;
        current.eyeRerollEnabled = newVal;
        ui.mode = 'turn';
        return interaction.update({
            content: buildBattleContent(battle, `👁️ **${current.username}** ${newVal ? 'enables' : 'disables'} **Evolved Right Eye** — ki attacks ${newVal ? 'will' : 'will no longer'} reroll for a Ki cost (taking the better).`),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_grappletgt_')) {
        const targetId = customId.slice('bt_grappletgt_'.length);
        const target = battle.turnOrder.find(p => p.userId === targetId);

        if (!target || target.isDead || target.isIncapacitated) {
            return interaction.reply({ content: '❌ That target is no longer available!', ephemeral: true });
        }

        // Namekian Flexible: spend 8 Ki to gain +4 mod to the grapple attempt.
        const grappleOpts = {};
        let flexibleNote = '';
        if (viewer.race === 'Namekian' && (viewer.currentKi || 0) >= 8) {
            viewer.currentKi -= 8;
            grappleOpts.grappleBonus = 4;
            flexibleNote = ' *(Flexible: -8 Ki, +4 to grapple)*';
        }
        const result = battle.grapple(viewer.id, targetId, grappleOpts);
        if (!result.success) {
            return interaction.reply({ content: `❌ ${result.message}`, ephemeral: true });
        }

        ui.mode = 'turn';
        const logText = result.failed
            ? (result.sprawlCounter
                ? `🤼 **${viewer.username}** tries to grapple **${target.username}**... but **${target.username}** (Sprawl) slips out and **counter-GRAPPLES** ${viewer.username}! (${result.atk} vs ${result.def})\nYou are GRAPPLED: -90% DEX defense.`
                : `🤼 **${viewer.username}** tries to grapple **${target.username}**... (${result.atk} vs ${result.def}) — they break free!`)
            : `🤼 **${viewer.username}** GRAPPLES **${target.username}**! (${result.atk} vs ${result.def})\n${target.username} is GRAPPLED: -90% DEX defense, escape roll each turn. Attacks against the grappler can break it.`;

        return interaction.update({
            content: buildBattleContent(battle, logText + flexibleNote),
            components: buildTurnComponents(battle, viewer)
        });
    }

    // Toggle optional dodge reactions (Spirit of the Tiger / Ground Glider) on/off.
    if (customId === 'bt_reactions') {
        const cur = battle.getCurrentTurn();
        if (!cur || isNPC(cur) || isCompanion(cur)) {
            return interaction.reply({ content: '❌ Not your turn!', ephemeral: true });
        }
        cur.useReactions = (cur.useReactions === false) ? true : false;
        const state = cur.useReactions === false ? '**OFF**' : '**ON**';
        return interaction.update({
            content: buildBattleContent(battle, `🛡️ **${cur.username}** set their dodge reactions to ${state}.`),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_skill_')) {
        const skillName = customId.slice('bt_skill_'.length);
        const skill = COMBAT_SKILLS[skillName];
        if (!skill) {
            return interaction.reply({ content: '❌ Unknown technique!', ephemeral: true });
        }
        if (skill.needsTarget) {
            if (getAliveTargets(battle, viewer.id).length === 0) {
                return interaction.reply({ content: '❌ No valid targets left!', ephemeral: true });
            }
            ui.pendingSkill = skillName;
            ui.mode = 'skillTargets';
            return interaction.update({
                content: buildBattleContent(battle, `Choose a target for **${skillName}** 👇`),
                components: buildSkillTargetComponents(battle, viewer)
            });
        }
        return await executeCombatSkill(interaction, battle, viewer, skill, null);
    }

    if (customId.startsWith('bt_skilltgt_')) {
        const targetId = customId.slice('bt_skilltgt_'.length);
        const skillName = ui.pendingSkill;
        if (!skillName || !COMBAT_SKILLS[skillName]) {
            return interaction.reply({ content: '❌ No technique selected!', ephemeral: true });
        }
        ui.pendingSkill = null;
        return await executeCombatSkill(interaction, battle, viewer, COMBAT_SKILLS[skillName], targetId);
    }

    if (customId === 'bt_type_physical' || customId === 'bt_type_ki') {
        if (customId === 'bt_type_ki') {
            const cur = battle.getCurrentTurn();
            const curChar = cur && !isNPC(cur) ? characterManager.getCharacter(cur.userId) : null;
            const learned = (cur && cur.kiApplicationLearned) || (curChar && hasKiApplication(curChar));
            if (!learned) {
                return interaction.reply({ content: '❌ You need to learn **Ki Application** from a mentor before you can use ki-based attacks!', ephemeral: true });
            }
        }
        ui.attackType = customId === 'bt_type_physical' ? 'physical' : 'ki';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose a target below 👇'),
            components: buildTargetComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_tgt_')) {
        const targetId = customId.slice('bt_tgt_'.length);
        // Prefer a living target with this id (guards against any legacy duplicate enemy ids).
        let target = battle.turnOrder.find(p => p.userId === targetId && !p.isDead && !p.isIncapacitated);
        if (!target) target = battle.turnOrder.find(p => p.userId === targetId);

        if (!target || target.isDead || target.isIncapacitated) {
            return interaction.reply({ content: '❌ That target is no longer available!', ephemeral: true });
        }

        // While grappling, you can only strike the opponent you're holding.
        if (current.grappling && targetId !== current.grappling) {
            return interaction.reply({ content: '🤼 You can only attack the person you are **grappling**!', ephemeral: true });
        }

        // Attacks always use your Action. Bonus actions are only for abilities/items that specifically use them.
        if (current.hasActed) {
            return interaction.reply({ content: '❌ You already used your action this turn!', ephemeral: true });
        }
        const isAction = true;

        const result = await battle.attack(viewer.id, targetId, ui.attackType, isAction);
        if (!result.success) {
            return interaction.reply({ content: `❌ ${result.message}`, ephemeral: true });
        }

        ui.mode = 'turn';
        const actionNote = `(${isAction ? 'Action' : 'Bonus Action'} used)`;
        const awake = tryFalseSuperSaiyanAwakening(battle, target) + tryIntenseAnger(battle, target) + tryHopeOfTheUniverse(battle, target) + tryUltimatePowerAwakening(battle, target);

        // Animate the attack line-by-line (0.1s per step) for the same pacing as NPC turns.
        await interaction.deferUpdate().catch(() => {});
        let logText = '';
        const steps = buildAttackEventSteps(current.username, target, result);
        for (const step of steps) {
            logText += step;
            await interaction.editReply({ content: buildBattleContent(battle, logText), components: [] }).catch(() => {});
            await sleep(100);
        }
        logText += actionNote + awake;

        // If the defender is a player who can react to the dodge, pause for their Yes/No choice.
        if (result.reactionPending) {
            if (await maybeShowReactionPrompt(interaction, battle, logText)) return;
        }

        const over = checkBattleOver(battle);
        if (over) {
            return interaction.editReply({ content: clampMessage(`${buildBattleContent(battle, logText)}\n\n${over.content}`), components: over.components });
        }

        return interaction.editReply({
            content: buildBattleContent(battle, logText),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId === 'bt_items') {
        if (getConsumables(viewer).length === 0) {
            return interaction.reply({ content: '❌ You have no consumable items!', ephemeral: true });
        }
        ui.mode = 'items';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose an item to use 👇'),
            components: buildItemComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_item_')) {
        const slot = parseInt(customId.slice('bt_item_'.length), 10);
        const character = characterManager.getCharacter(viewer.id);

        if (!character) {
            return interaction.reply({ content: '❌ No character found!', ephemeral: true });
        }

        const item = character.inventory[slot];
        if (!item) {
            return interaction.reply({ content: '❌ Item no longer exists!', ephemeral: true });
        }

        const itemData = typeof item === 'string' ? { name: item, type: 'unknown' } : item;
        const spec = getConsumableEffect(item);
        if (!spec) {
            return interaction.reply({ content: `❌ **${itemData.name}** is not a consumable item!`, ephemeral: true });
        }

        // Support items (healing/restoring consumables) are unavailable in mentor fights.
        if (activeMentorFights.has(battle.id)) {
            return interaction.reply({ content: '❌ Support items are **disabled** in mentor fights!', ephemeral: true });
        }

        // Support items are on a 5-round cooldown once used in combat.
        const lastItemRound = current.supportItemCdRound || 0;
        if (lastItemRound > 0 && battle.round - lastItemRound < 5) {
            const left = 5 - (battle.round - lastItemRound);
            return interaction.reply({ content: `❌ Support items are on cooldown! **${left} round${left === 1 ? '' : 's'}** remaining.`, ephemeral: true });
        }

        if (current.hasBonusActed) {
            return interaction.reply({ content: '❌ You already used your bonus action this turn!', ephemeral: true });
        }

        current.hasBonusActed = true;
        current.supportItemCdRound = battle.round;

        const effect = computeConsumableEffect(spec, character);
        const effects = [];
        const oldHP = current.currentHP;
        const oldKi = current.currentKi;
        const oldFatigue = current.currentFatigue || 0;

        if (effect.full) {
            current.currentHP = current.hp;
            current.currentKi = current.ki;
            current.currentFatigue = 0;
            effects.push(`❤️ HP: ${oldHP} → ${current.currentHP}`);
            effects.push(`💙 Ki: ${oldKi} → ${current.currentKi}`);
            effects.push(`😓 Fatigue: ${oldFatigue}% → 0%`);
            characterManager.updateCharacter(viewer.id, character.id, { currentHP: character.maxHP, currentKi: character.maxKi, fatigue: 0, peakFatigue: 0 });
        } else {
            if (effect.hpHeal > 0) {
                current.currentHP = Math.min(oldHP + effect.hpHeal, current.hp);
                effects.push(`❤️ HP: ${oldHP} → ${current.currentHP}`);
                characterManager.modifyHP(viewer.id, character.id, effect.hpHeal);
            }
            if (effect.kiHeal > 0) {
                current.currentKi = Math.min(oldKi + effect.kiHeal, current.ki);
                effects.push(`💙 Ki: ${oldKi} → ${current.currentKi}`);
                characterManager.modifyKi(viewer.id, character.id, effect.kiHeal);
            }
            if (effect.fatigueDelta !== 0) {
                current.currentFatigue = Math.max(0, Math.min(100, oldFatigue + effect.fatigueDelta));
                effects.push(`😓 Fatigue: ${oldFatigue}% → ${current.currentFatigue}%`);
                characterManager.modifyFatigue(viewer.id, character.id, effect.fatigueDelta);
            }
        }

        // Remove one item from the character's inventory (decrement stacks)
        consumeInventorySlot(character.inventory, slot);
        characterManager.updateCharacter(viewer.id, character.id, { inventory: character.inventory });

        ui.mode = 'turn';
        const logText = `${viewer.username} consumed **${itemData.name}**!\n${effects.length > 0 ? effects.join('\n') : '✨ No effects!'}\n(Bonus Action used)`;

        return interaction.update({
            content: buildBattleContent(battle, logText),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId === 'bt_retreat') {
        const opponent = battle.turnOrder.find(p => p.userId !== viewer.id && !p.isDead && !p.isIncapacitated);

        if (!opponent) {
            battleManager.endBattle(battle.id);
            battleMessages.delete(battle.id);
            activeMissions.delete(battle.id);
            activeMentorFights.delete(battle.id);
            activeHunts.delete(battle.id);
            return interaction.update({ content: `🏃 **${viewer.username}** escaped! There was nobody left to stop them.`, components: [] });
        }

        const result = battle.attemptRetreat(viewer.id, opponent.userId);

        if (result.grappled) {
            const msg = `🤼 **${viewer.username}** is **grappled** and can't retreat!\n\nYou lose your turn and gain disadvantage.`;
            return advanceBattleTurn(interaction, battle, msg);
        }

        let message = `🏃 **${viewer.username}** attempts to retreat!\n\n`;
        message += `Your roll: **${result.participantRoll}**\n`;
        message += `Required: **${result.requiredRoll}**\n\n`;

        if (result.escaped) {
            // Flee to a valid slot on the character's current planet and move them there.
            const character = characterManager.getCharacter(viewer.id);
            const inTransit = character ? getRemainingTravelMs(character) > 0 : false;
            const planet = (character && character.location) || 'Earth';
            let escapeArea = character ? (character.space || 1) : 1;
            if (!inTransit) {
                // Only relocate when not mid-travel — retreat must not teleport you to a new
                // area (which would let you bypass travel / re-roll gather+search limits).
                const maxSpace = PLANET_SPACES[planet] || 100;
                escapeArea = getRandomInt(maxSpace);
                if (escapeArea === (character.space || 1) && maxSpace > 1) {
                    escapeArea = (escapeArea % maxSpace) + 1; // ensure a different slot when possible
                }
            }
            if (character) {
                characterManager.updateCharacter(viewer.id, character.id, { space: escapeArea });
            }
            message += inTransit
                ? `✅ **ESCAPED!** You break away from the fight and continue your journey!`
                : `✅ **ESCAPED!** You flee to **${planet} - Space ${escapeArea}**!`;
            battleManager.endBattle(battle.id);
            battleMessages.delete(battle.id);
            activeMissions.delete(battle.id);
            activeMentorFights.delete(battle.id);
            activeHunts.delete(battle.id);
            return interaction.update({ content: message, components: [] });
        }

        message += '❌ **FAILED!** You lose your full turn and gain disadvantage!';
        return advanceBattleTurn(interaction, battle, message);
    }

    if (customId === 'bt_explode') {
        const cur = battle.getCurrentTurn();
        if (!cur || cur.race !== 'Saibamen') {
            return interaction.reply({ content: '❌ Only **Saibamen** can implode! (PTSD)', ephemeral: true });
        }
        // A grappled Saibamen can still blow up (their action was lost to the grapple, not spent).
        if (cur.hasActed && !cur.grappledBy) {
            return interaction.reply({ content: '❌ You already used your action this turn!', ephemeral: true });
        }

        const dmg = (cur.currentHP || 0) + (cur.currentKi || 0);
        let logText = `💥 **${cur.username}** fires every synapse at once — **PTSD implosion**!\n\n`;
        logText += `💥 **${cur.username}** detonates for **${dmg} damage**!`;
        let hitAnyone = false;
        getAliveTargets(battle, cur.userId).forEach(t => {
            t.currentHP = Math.max(0, t.currentHP - dmg);
            if (t.currentHP <= 0 && !t.isIncapacitated) {
                // The blast is lethal — kill enemies outright (send them to the Otherworld).
                t.isIncapacitated = true;
                let killed = true;
                let deathRes = null;
                if (!battle.isSpar && !isNPC(t) && !isCompanion(t)) {
                    deathRes = killCharacter(t.userId);
                    if (deathRes && deathRes.protected) killed = false;
                }
                if (killed) {
                    t.isDead = true;
                    logText += deathRes && deathRes.reborn
                        ? `\n🥚 **${t.username}** is slain by the blast, but their **Namekian egg** hatches — they are reborn!`
                        : `\n💀 **${t.username}** is KILLED by the blast and sent to **${afterlifeLocationName(deathRes || t)}**!`;
                } else {
                    t.currentHP = 1;
                    logText += `\n🧿 **${t.username}** was protected by the **Ancient Wuxia Talisman** and survived!`;
                }
            } else {
                logText += `\n${t.username} takes **${dmg} damage**!`;
            }
            hitAnyone = true;
        });
        if (!hitAnyone) logText += `\nNobody was within the blast.`;
        // The Saibamen dies instantly (sent to the Otherworld).
        let died = true;
        let selfDeathRes = null;
        if (!battle.isSpar && !isNPC(cur) && !isCompanion(cur)) {
            selfDeathRes = killCharacter(cur.userId);
            if (selfDeathRes && selfDeathRes.protected) died = false;
        }
        cur.hasActed = true;
        if (died) {
            cur.isDead = true;
            cur.currentHP = 0;
            cur.isIncapacitated = true;
            logText += selfDeathRes && selfDeathRes.reborn
                ? `\n🥚 **${cur.username}** dies in the blast, but their **Namekian egg** hatches — they are reborn!`
                : `\n💀 **${cur.username}** dies in the blast!`;
        } else {
            cur.currentHP = 1;
            logText += `\n🧿 **${cur.username}** was protected by the **Ancient Wuxia Talisman** and survived their own blast!`;
        }
        ui.mode = 'turn';

        const over = checkBattleOver(battle);
        if (over) {
            return interaction.update({ content: clampMessage(`${buildBattleContent(battle, logText)}\n\n${over.content}`), components: over.components || [] });
        }

        await interaction.deferUpdate().catch(() => {});
        const { log } = battle.advance();
        logText = appendBattleLog(logText + '\n\n', log);
        logText = await resolveNPCTurns(battle, logText, async (text) => {
            await interaction.editReply({ content: clampMessage(buildBattleContent(battle, `${text}\n\n⏳ ...`)), components: [] }).catch(() => {});
        });
        if (await maybeShowReactionPrompt(interaction, battle, logText)) return;
        const over2 = checkBattleOver(battle);
        if (over2) {
            return interaction.editReply({ content: clampMessage(`${buildBattleContent(battle, logText)}\n\n${over2.content}`), components: over2.components || [] });
        }
        return interaction.editReply({ content: buildBattleContent(battle, logText), components: buildTurnComponents(battle, viewer) });
    }

    if (customId === 'bt_save') {
        const allies = battle.turnOrder.filter(p => p.userId !== viewer.id && p.isIncapacitated && !p.isDead);

        if (allies.length === 0) {
            return interaction.reply({ content: '❌ No incapacitated allies to save!', ephemeral: true });
        }

        ui.mode = 'save';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose who to save 👇'),
            components: buildSaveComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_save_')) {
        const allyId = customId.slice('bt_save_'.length);
        const result = battle.saveAlly(viewer.id, allyId);

        if (!result.success) {
            return interaction.reply({ content: `❌ ${result.message}`, ephemeral: true });
        }

        const ally = battle.turnOrder.find(p => p.userId === allyId);
        ui.mode = 'turn';

        let logText = `🏥 **${viewer.username}** saves **${ally.username}**!\n`;
        logText += result.stable
            ? `✅ ${ally.username} is now **STABLE** and no longer needs death saves!`
            : `${ally.username} succeeds one death save. One more needed to stabilize.`;

        return interaction.update({
            content: buildBattleContent(battle, logText),
            components: buildTurnComponents(battle, viewer)
        });
    }

    if (customId === 'bt_endturn') {
        ui.mode = 'turn';
        return advanceBattleTurn(interaction, battle, `${viewer.username} ends their turn.`);
    }

    if (customId === 'bt_back') {
        ui.mode = 'turn';
        ui.pendingSkill = null;
        return interaction.update({
            content: buildBattleContent(battle),
            components: buildTurnComponents(battle, viewer)
        });
    }

    // Talk: pick an enemy to persuade (3 successful talks recruits them).
    if (customId === 'bt_talk') {
        if (!activeMissions.has(battle.id)) {
            return interaction.reply({ content: '❌ You can only talk to enemies during missions!', ephemeral: true });
        }
        if (isSagaBattle(battle)) {
            return interaction.reply({ content: '❌ Saga enemies can NEVER be allied with!', ephemeral: true });
        }
        if (ui.recruited) {
            return interaction.reply({ content: '❌ You have already recruited an ally this battle!', ephemeral: true });
        }
        const enemies = getEnemyTargets(battle);
        if (enemies.length === 0) {
            return interaction.reply({ content: '❌ No enemies left to talk to!', ephemeral: true });
        }
        if (current && current.userId === viewer.id && current.hasActed) {
            return interaction.reply({ content: '❌ You can only talk once per turn!', ephemeral: true });
        }
        ui.mode = 'talk';
        return interaction.update({
            content: buildBattleContent(battle, 'Choose an enemy to talk to 👇'),
            components: buildTalkTargetComponents(battle, viewer)
        });
    }

    if (customId.startsWith('bt_talk_tgt_')) {
        const enemyId = customId.slice('bt_talk_tgt_'.length);
        const enemy = battle.turnOrder.find(p => p.userId === enemyId);
        if (!enemy || isCompanion(enemy) || enemy.isDead || enemy.isIncapacitated) {
            return interaction.reply({ content: '❌ That enemy is no longer available!', ephemeral: true });
        }
        if (!activeMissions.has(battle.id)) {
            return interaction.reply({ content: '❌ You can only talk to enemies during missions!', ephemeral: true });
        }
        if (isSagaBattle(battle)) {
            return interaction.reply({ content: '❌ Saga enemies can NEVER be allied with!', ephemeral: true });
        }
        if (ui.recruited) {
            return interaction.reply({ content: '❌ You have already recruited an ally this battle!', ephemeral: true });
        }
        if (current && current.userId === viewer.id && current.hasActed) {
            return interaction.reply({ content: '❌ You can only talk once per turn!', ephemeral: true });
        }

        const playerChar = characterManager.getCharacter(viewer.id);
        const isRivalTalk = enemy.isRival === true;
        const rival = isRivalTalk ? (playerChar && playerChar.rival) : null;

        let success;
        let chanceText;
        let progress;
        if (isRivalTalk && rival) {
            // Rival persuasion uses a dynamic DC that lowers as you beat them more, plus a
            // dialogue bonus from prior successful talks and spares.
            const dc = getRivalPersuasionDC(rival);
            const wilMod = calculateModifier((playerChar.stats || {}).wil || 0);
            const bonus = (rival.spares || 0) + (rival.persuasionProgress || 0);
            const roll = getRandomInt(20) + Math.floor(wilMod / 2) + bonus;
            success = roll >= dc;
            chanceText = `🎯 Persuasion roll: **${roll}** (DC **${dc}**)`;
            progress = ui.talkProgress[enemyId] = ui.talkProgress[enemyId] || { successes: 0, attempts: 0 };
        } else {
            const chance = getPersuadeChance(playerChar, enemy);
            const rolled = Math.random();
            success = rolled < chance;
            chanceText = `🎯 Persuade chance: **${Math.round(chance * 100)}%** (roll: ${(rolled * 100).toFixed(1)})`;
            progress = ui.talkProgress[enemyId] = ui.talkProgress[enemyId] || { successes: 0, attempts: 0 };
        }
        progress.attempts++;
        const recruitNeed = isRivalTalk ? RIVAL_RECRUIT_TARGET : 3;

        let logText = `🗨️ **${viewer.username}** tries to persuade **${enemy.username}**...\n`;
        logText += chanceText;

        if (success) {
            progress.successes++;
            if (isRivalTalk && rival) {
                rival.persuasionProgress = (rival.persuasionProgress || 0) + 1;
                characterManager.updateCharacter(viewer.id, playerChar.id, { rival });
            }
            logText += ` — ✅ **SUCCESS!** (${isRivalTalk ? `${rival.persuasionProgress}/${recruitNeed}` : `${progress.successes}/${recruitNeed}`} ${isRivalTalk ? 'persuasions' : 'talks'})`;
        } else {
            logText += ` — ❌ **FAILED!** (${isRivalTalk ? `${rival ? rival.persuasionProgress : 0}/${recruitNeed}` : `${progress.successes}/${recruitNeed}`} ${isRivalTalk ? 'persuasions' : 'talks'} so far)`;
        }

        const recruitTrigger = isRivalTalk && rival
            ? success && rival.persuasionProgress >= RIVAL_RECRUIT_TARGET
            : success && progress.successes >= 3;

        if (recruitTrigger) {
            // Recruit! They reveal their name and switch teams to fight alongside you.
            enemy.isAlly = true;
            enemy.isNPC = false;
            enemy.recruited = true;
            enemy.ownerUserId = viewer.id;
            ui.recruited = true;
            const revealedName = isRivalTalk && rival ? rival.name : rollCompanionName(enemy.gender, enemy.race);
            enemy.companionName = revealedName;
            enemy.username = revealedName; // From now on they're known by their name
            if (isRivalTalk && rival) {
                // Clear the active rival slot now that they've joined for good.
                characterManager.updateCharacter(viewer.id, playerChar.id, { rival: null });
                logText += `\n\n🤝 **${enemy.username}** finally stops fighting... "It's time I stood beside you."\n\n**${enemy.username}** joins your team as a companion!`;
            } else {
                logText += `\n\n🤝 **${enemy.username}** lowers their guard... "My name is **${revealedName}**. I'll fight beside you!"\n\n**${revealedName}** joins your team!`;
            }
        }

        // Talking costs your action (like an attack), so you can't talk and attack in the same turn.
        if (current && current.userId === viewer.id) current.hasActed = true;
        ui.mode = 'turn';

        // Recruiting the last enemy empties the battlefield — end the battle immediately.
        // A win secured by talking gives no alignment and reduced stat rewards.
        if (ui.recruited) battle.wonByTalk = true;
        const over = checkBattleOver(battle);
        if (over) {
            return interaction.update({
                content: clampMessage(`${buildBattleContent(battle, logText)}\n\n${over.content}`),
                components: over.components
            });
        }

        return interaction.update({
            content: buildBattleContent(battle, logText),
            components: buildTurnComponents(battle, viewer)
        });
    }

    // Unknown/disabled battle button - acknowledge quietly
    return interaction.deferUpdate();
}

