// Track mentor fights (channelId -> { userId, style })
const activeMentorFights = new Map();

// Track active /hunt battles (channelId -> { userId, animal }) so winners get their meat.
const activeHunts = new Map();

// Pending mentor challenge (userId -> { style })
const pendingMentors = new Map();
const pendingMentorTeach = new Map(); // userId -> { style, companionId }

// Pending special-area NPC offer (userId -> { npc, specialName, teachChoices })
const pendingNpcOffers = new Map();

// Pending rival defeat resolution (userId -> { ownerId, ownerCharId, killUnlocked, killRoll })
const pendingRivalResolutions = new Map();

// Unclaimed mentor-victory rewards (userId -> { style, choices, createdAt })
const pendingMentorRewards = new Map();

// Pending item gives (id -> { giverId, targetId, itemName, amount, createdAt })
const pendingGives = new Map();

// Pending spar challenges (id -> { challengerId, opponentId, createdAt })
const pendingSpars = new Map();

// Pending vampirism ability choice (userId -> { race, abilities, picked: [] })
const pendingVampirism = new Map();

// Pending interactive /teach session (userId -> { targetType, teachType, teacherId, slot?, studentUserId?, studentId?, whatPage? })
const pendingTeach = new Map();

// True Capsule (Trello "True Capsule"): a portable container that stores up to 5 non-living items.
const MAX_CAPSULE_ITEMS = 5;
const pendingTrueCapsule = new Map(); // userId -> { candidates }

// Items that can be stored in the True Capsule (inventory, home storage, and the placed home).
function getTrueCapsuleCandidates(character) {
    const candidates = [];
    (Array.isArray(character.inventory) ? character.inventory : []).forEach(item => {
        const name = parseItemName(item).name;
        if (name === 'True Capsule') return; // can't store the capsule in itself
        candidates.push({ item, name, kind: 'inventory' });
    });
    (Array.isArray(character.homeStorage) ? character.homeStorage : []).forEach(item => {
        candidates.push({ item, name: parseItemName(item).name, kind: 'homeStorage' });
    });
    if (character.homeType) {
        candidates.push({ item: character.homeType, name: character.homeType, kind: 'placedHome' });
    }
    return candidates;
}

// Remove a candidate from its source (inventory / home storage / placed home) and return a note.
function removeTrueCapsuleCandidate(character, cand) {
    let note = '';
    if (cand.kind === 'inventory') {
        removeInventoryItems(character.inventory, cand.name, 1);
    } else if (cand.kind === 'homeStorage') {
        removeInventoryItems(character.homeStorage, cand.name, 1);
    } else if (cand.kind === 'placedHome') {
        character.homeType = null;
        character.homeLocation = null;
        character.homeSpace = null;
        note = '\n🏠 **Home** packed up into the capsule!';
    }
    return note;
}

// Interactive /teach: build the companion picker dropdown.
function buildTeachCompanionMenu(teacher, teachType) {
    const select = new StringSelectMenuBuilder()
        .setCustomId(`teach_cmp_${teachType}`)
        .setPlaceholder('Choose a companion...');
    (teacher.companions || []).forEach((cmp, i) => {
        const label = String(cmp.name || 'Companion').slice(0, 100);
        select.addOptions(new StringSelectMenuOptionBuilder().setLabel(label).setValue(String(i)));
    });
    return new ActionRowBuilder().addComponents(select);
}

// Interactive /teach: build the technique/style dropdown (paginated to 25 per menu).
// Only shows what the teacher actually knows — you can't teach something you don't know.
function buildTeachWhatComponents(teachType, page = 0, teacher = null) {
    // Style-granted techniques (signature moves) can't be taught individually — you learn them by adopting the style.
    let names = teachType === 'technique'
        ? Object.keys(COMBAT_SKILLS).filter(name => !STYLE_TECHNIQUES.has(name))
        : Object.keys(MENTOR_STYLES);
    if (teacher) {
        names = teachType === 'technique'
            ? names.filter(name => characterKnowsTechnique(teacher, name))
            : names.filter(name => teacher.fightingStyle === name);
    }
    const perPage = 25;
    const totalPages = Math.max(1, Math.ceil(names.length / perPage));
    const pageNames = names.slice(page * perPage, (page + 1) * perPage);
    const select = new StringSelectMenuBuilder()
        .setCustomId(`teach_what_${teachType}`)
        .setPlaceholder(`${teachType === 'technique' ? 'Technique' : 'Fighting style'} (page ${page + 1}/${totalPages})...`);
    pageNames.forEach(name => {
        select.addOptions(new StringSelectMenuOptionBuilder().setLabel(name).setValue(name));
    });
    const components = [new ActionRowBuilder().addComponents(select)];
    const navRow = new ActionRowBuilder();
    if (page > 0) navRow.addComponents(new ButtonBuilder().setCustomId(`teach_whatprev_${teachType}`).setLabel('◂ Prev').setStyle(ButtonStyle.Secondary));
    if (page < totalPages - 1) navRow.addComponents(new ButtonBuilder().setCustomId(`teach_whatnext_${teachType}`).setLabel('Next ▸').setStyle(ButtonStyle.Secondary));
    if (navRow.components.length > 0) components.push(navRow);
    return { components, totalPages };
}

// Apply a chosen technique/style from the /teach dropdown.
function applyTeachSelection(interaction) {
    const teachType = interaction.customId.slice('teach_what_'.length);
    const what = interaction.values[0];
    const pending = pendingTeach.get(interaction.user.id);
    if (!pending) return interaction.update({ content: '❌ This teach session has expired. Use `/teach` again.', components: [] });
    const teacher = characterManager.getCharacter(interaction.user.id);
    if (!teacher) return interaction.update({ content: '❌ You need a character!', components: [] });

    if (teachType === 'technique' && !COMBAT_SKILLS[what]) return interaction.update({ content: `❌ Unknown technique: **"${what}"**!`, components: [] });
    if (teachType === 'style' && !MENTOR_STYLES[what]) return interaction.update({ content: `❌ Unknown fighting style: **"${what}"**!`, components: [] });
    // Style-granted techniques can't be taught directly — they come with adopting the style.
    if (teachType === 'technique' && STYLE_TECHNIQUES.has(what)) {
        return interaction.update({ content: `❌ **${what}** is a **fighting-style** technique and can only be learned by adopting the style, not taught!`, components: [] });
    }

    // You can only teach what you know — the teacher must actually know the skill.
    if (teachType === 'technique' && !characterKnowsTechnique(teacher, what)) {
        return interaction.update({ content: `❌ **${teacher.name}** doesn't know **${what}** and can't teach it!`, components: [] });
    }
    if (teachType === 'style' && teacher.fightingStyle !== what) {
        return interaction.update({ content: `❌ **${teacher.name}** doesn't use the **${what}** style and can't teach it!`, components: [] });
    }

    let studentCmp = null, studentChar = null, studentUserId = null, studentId = null;
    if (pending.targetType === 'companion') {
        const cmp = (teacher.companions || [])[(pending.slot || 1) - 1];
        if (!cmp) return interaction.update({ content: '❌ That companion no longer exists!', components: [] });
        studentCmp = cmp;
    } else {
        const sc = characterManager.getCharacter(pending.studentUserId);
        if (!sc) return interaction.update({ content: '❌ That player no longer has a character!', components: [] });
        studentChar = sc;
        studentUserId = pending.studentUserId;
        studentId = sc.id;
    }

    if (teachType === 'style') {
        if (studentCmp) {
            const oldStyle = studentCmp.fightingStyle;
            let te = Array.isArray(studentCmp.techniques) ? [...studentCmp.techniques] : [];
            te = pruneOffStyleTechniques(te, what);
            (MENTOR_STYLES[what].moves || []).forEach(m => { if (!te.includes(m)) te.push(m); });
            studentCmp.techniques = te;
            studentCmp.fightingStyle = what;
            studentCmp.fatigue = (studentCmp.fatigue || 0) + 20;
            const teachRestText = companionRestIfNeeded(studentCmp);
            teacher.companions[pending.slot - 1] = studentCmp;
            characterManager.updateCharacter(interaction.user.id, teacher.id, { companions: teacher.companions });
            characterManager.modifyFatigue(interaction.user.id, teacher.id, 20);
            pendingTeach.delete(interaction.user.id);
            return interaction.update({ content: `🥋 **${teacher.name}** taught **${studentCmp.name}** the **${what}** style!${oldStyle ? ` It replaces **${oldStyle}**.` : ''} (both +20% fatigue)${teachRestText}`, components: [] });
        }
        // Assassin requires -250 negative alignment (Trello "Assassin" card).
        if (what === 'Assassin' && getPlayerAlignmentValue(studentChar) > -250) {
            return interaction.update({ content: `❌ **Assassin** requires **-250 negative alignment**. **${studentChar.name}** has **${getPlayerAlignmentValue(studentChar)}** alignment.`, components: [] });
        }
        const oldStyle = studentChar.fightingStyle;
        let techniques = Array.isArray(studentChar.techniques) ? [...studentChar.techniques] : [];
        techniques = pruneOffStyleTechniques(techniques, what);
        (MENTOR_STYLES[what].moves || []).forEach(m => { if (!techniques.includes(m)) techniques.push(m); });
        characterManager.updateCharacter(studentUserId, studentId, { fightingStyle: what, techniques });
        characterManager.modifyFatigue(interaction.user.id, teacher.id, 20);
        characterManager.modifyFatigue(studentUserId, studentId, 20);
        pendingTeach.delete(interaction.user.id);
        return interaction.update({ content: `🥋 **${teacher.name}** taught **${studentChar.name}** the **${what}** style!${oldStyle ? ` It replaces **${oldStyle}**.` : ''} (both +20% fatigue)`, components: [] });
    }

    if (studentCmp) {
        const te = getCompanionTechniques(studentCmp);
        if (te.includes(what)) return interaction.update({ content: `❌ **${studentCmp.name}** already knows **${what}**!`, components: [] });
        te.push(what);
        studentCmp.techniques = te;
        studentCmp.fatigue = (studentCmp.fatigue || 0) + 20;
        const teachRestText = companionRestIfNeeded(studentCmp);
        teacher.companions[pending.slot - 1] = studentCmp;
        characterManager.updateCharacter(interaction.user.id, teacher.id, { companions: teacher.companions });
        characterManager.modifyFatigue(interaction.user.id, teacher.id, 20);
        pendingTeach.delete(interaction.user.id);
        return interaction.update({ content: `🧠 **${teacher.name}** taught **${studentCmp.name}** **${what}**! (both +20% fatigue)${teachRestText}`, components: [] });
    }
    const te2 = Array.isArray(studentChar.techniques) ? [...studentChar.techniques] : [];
    if (te2.includes(what)) return interaction.update({ content: `❌ **${studentChar.name}** already knows **${what}**!`, components: [] });
    te2.push(what);
    characterManager.updateCharacter(studentUserId, studentId, { techniques: te2 });
    characterManager.modifyFatigue(interaction.user.id, teacher.id, 20);
    characterManager.modifyFatigue(studentUserId, studentId, 20);
    pendingTeach.delete(interaction.user.id);
    return interaction.update({ content: `🧠 **${teacher.name}** taught **${studentChar.name}** **${what}**! (both +20% fatigue)`, components: [] });
}

// Store Dungeon Master user ID
let dungeonMasterId = null;

