const MERCHANT_PRICES = { ...DEFAULT_MERCHANT_PRICES, ...(merchantPrices || {}) };

// Daily sale discounts: each item has a random chance (30%) to be on sale (20-70% off).
const saleStock = new Map(); // `${location}-${space}-${item}` -> { date, sale, salePrice }
function getSaleInfo(location, space, itemName, basePrice) {
    const key = `${location}-${space}-${itemName}`;
    const today = new Date().toDateString();
    const existing = saleStock.get(key);
    if (existing && existing.date === today) return existing;
    let sale = null, salePrice = null;
    if (getRandomInt(100) <= 30) { // 30% chance to be on sale
        sale = 20 + getRandomInt(51) - 1; // 20-70% off
        salePrice = Math.max(1, Math.round(basePrice * (100 - sale) / 100));
    }
    const info = { date: today, sale, salePrice };
    saleStock.set(key, info);
    return info;
}

// Weapons & Armor stock (Trello "Merchant" card). Quality tiers: base price = weapon,
// heavy price = heavy armor; light/medium armors are derived between base and heavy.
const GEAR_QUALITIES = [
    { name: 'Masterwork', price: 3000000, heavyPrice: 1550000 },
    { name: 'Expert', price: 690000, heavyPrice: 920000 },
    { name: 'Tempered', price: 500000, heavyPrice: 840000 },
    { name: 'Fine', price: 350000, heavyPrice: 550000 },
    { name: 'Regular', price: 190000, heavyPrice: 380000 },
    { name: 'Bad', price: 65000, heavyPrice: 145000 },
    { name: 'Worthless', price: 1000, heavyPrice: 3000 }
];

const WEAPON_TYPES = ['Club', 'Spiked Club', 'Power Pole', 'Sword', 'Katana', 'Scythe', 'Nodachi', 'Halberd', 'Greatsword', 'Greathammer'];
const ARMOR_WEIGHTS = ['Light', 'Medium', 'Heavy'];

// ---------- Traveling Merchant (rare find while searching) ----------
// A rare merchant that spawns with a wider, high-value stock and sells 40-75% cheaper than city
// merchants. Only rarer goods (tech, weights, high-tier consumables, weapon stock) show up.
const TRAVELING_MERCHANT_POOL = [
    // Rare tech / engineering
    'Motherboard', 'Engine Conjunction', 'Gravitational Control Chip', 'Reactor Core', 'Philosophy Book',
    // Upgrades & training gear
    'Inventory Upgrade', 'Light weight', 'Med. weight', 'Heavy weight', 'Fishing Tackle', 'Fishing Rod',
    // High-tier consumables
    'Recovery Capsule', 'Ki Recovery Capsule', 'Mixed Capsule', 'Sage Water', 'Hetap™', 'Vita Drink',
    // Weapon stock (quality rolled on use/equip)
    'Sword', 'Katana', 'Nodachi', 'Greatsword', 'Halberd', 'Greathammer', 'Spear', 'Bo-Staff', 'Scythe', 'Club',
    // Crafting / components
    'Component', 'Copper Wire', 'Welding torch'
];

// Base price for a traveling-merchant good (weapon/armor goods fall back to a base price).
function getTravelingMerchantBasePrice(name) {
    const e = MERCHANT_PRICES[name];
    if (e) return e.price;
    if (WEAPON_STATS[name]) return 200000;
    return 10000;
}

// Rarity weight for the traveling merchant: higher-priced (rarer) goods appear more often.
function travelingMerchantRarityWeight(base) {
    if (base >= 10000000) return 8;   // epic tech
    if (base >= 1000000) return 6;    // philosophy book etc.
    if (base >= 300000) return 4;     // motherboards, heavy weights
    if (base >= 100000) return 3;     // med. weight, inventory upgrade
    if (base >= 50000) return 2;      // fishing tackle, welding torch
    return 1;
}

function generateTravelingMerchantStock(location) {
    const pool = [...new Set(TRAVELING_MERCHANT_POOL)].filter(name => {
        const e = MERCHANT_PRICES[name];
        if (e && e.earthOnly && location !== 'Earth') return false; // Earth-only food doesn't show off-world
        return true;
    });
    // Weight the stall toward rarer (higher-priced) goods.
    const weighted = pool.map(name => ({ name, base: getTravelingMerchantBasePrice(name) }));
    const count = 5 + getRandomInt(3) - 1; // 5-7 items (wider variety)
    const stock = [];
    const chosen = new Set();
    let guard = 0;
    while (stock.length < count && guard < 300 && chosen.size < weighted.length) {
        guard++;
        const candidates = weighted.filter(w => !chosen.has(w.name));
        if (candidates.length === 0) break;
        const totalWeight = candidates.reduce((s, w) => s + travelingMerchantRarityWeight(w.base), 0);
        let r = Math.random() * totalWeight;
        let pick = candidates[0];
        for (const w of candidates) {
            r -= travelingMerchantRarityWeight(w.base);
            if (r <= 0) { pick = w; break; }
        }
        chosen.add(pick.name);
        // 40-75% off city prices (the traveling merchant is a rare, generous find).
        const discount = 40 + getRandomInt(36) - 1; // 40-75%
        const price = Math.max(1, Math.round(pick.base * (100 - discount) / 100));
        // The priciest goods are truly scarce — only 1 in stock.
        const qty = pick.base >= 1000000 ? 1 : getRandomInt(2);
        stock.push({ name: pick.name, price, qty });
    }
    return stock;
}

// Offer a traveling merchant found while searching (stores its stock on the character).
function offerTravelingMerchant(interaction, character, prefixText) {
    const stock = generateTravelingMerchantStock(character.location || 'Earth');
    const tm = {
        stock,
        expiresAt: Date.now() + 24 * 60 * 60 * 1000,
        location: character.location || 'Earth',
        space: character.space || 1
    };
    character.travelingMerchant = tm;
    characterManager.updateCharacter(interaction.user.id, character.id, { travelingMerchant: tm });
    const row = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('tm_open')
                .setLabel('🏪 Browse the Traveling Merchant')
                .setStyle(ButtonStyle.Primary)
        );
    return interaction.reply({
        content: `${prefixText}🛒 A **Traveling Merchant** has set up a stall nearby! (rare find — stock is **40-75% off** city prices, and wares are rarer than a normal merchant's!)\n\nUse the button below or \`/traveling-merchant\` to browse their wares before they move on.`,
        components: [row]
    });
}

// Build the traveling merchant shop view (content + buy/leave buttons).
function buildTravelingMerchantView(userId, character) {
    const tm = character && character.travelingMerchant;
    if (!tm || !Array.isArray(tm.stock) || tm.stock.length === 0) {
        return { content: `🛒 You don't have a traveling merchant waiting for you. Keep searching to find one!`, components: [] };
    }
    if (Date.now() > (tm.expiresAt || 0)) {
        return { content: `🛒 The traveling merchant has moved on...`, components: [] };
    }
    const rows = [];
    let currentRow = null;
    const lines = [];
    tm.stock.forEach((item, idx) => {
        const soldOut = item.qty <= 0;
        lines.push(`• **${item.name}** — ${soldOut ? '❌ sold out' : `**${item.price.toLocaleString()} zeni** (${item.qty} in stock)`}`);
        if (soldOut) return;
        if (!currentRow || currentRow.components.length >= 5) {
            currentRow = new ActionRowBuilder();
            rows.push(currentRow);
        }
        currentRow.addComponents(
            new ButtonBuilder()
                .setCustomId(`tm_buy_${idx}`)
                .setLabel(`🛒 ${item.name.slice(0, 60)}`)
                .setStyle(ButtonStyle.Secondary)
        );
    });
    rows.push(new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('tm_sell_open').setLabel('💰 Sell Items').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('tm_leave').setLabel('👋 Leave').setStyle(ButtonStyle.Danger)
    ));
    return {
        content: `🛒 **Traveling Merchant** — stock is **40-75% off** city prices!\n\n${lines.join('\n')}\n\n💰 Your zeni: **${(character.zeni || 0).toLocaleString()}**`,
        components: rows
    };
}

// Enumerate the character's sellable inventory (name, owned qty, per-unit sell price).
function getSellableInventory(character) {
    const inventory = Array.isArray(character.inventory) ? character.inventory : [];
    const counts = new Map();
    inventory.forEach(item => {
        const p = parseItemName(item);
        const price = getSellPrice(p.name);
        if (price === null) return;
        const entry = counts.get(p.name) || { qty: 0, price };
        entry.qty += p.quantity;
        counts.set(p.name, entry);
    });
    return [...counts.entries()].map(([name, info]) => ({ name, ...info }))
        .sort((a, b) => a.name.localeCompare(b.name));
}

// Build the traveling merchant "sell" menu (list the player's sellable goods + sell buttons).
function buildTravelingMerchantSellView(userId, character) {
    const tm = character && character.travelingMerchant;
    if (!tm || !Array.isArray(tm.stock)) {
        return { content: `🛒 You don't have a traveling merchant waiting for you. Keep searching to find one!`, components: [] };
    }
    if (Date.now() > (tm.expiresAt || 0)) {
        return { content: `🛒 The traveling merchant has moved on...`, components: [] };
    }
    const allSellable = getSellableInventory(character);
    if (allSellable.length === 0) {
        return {
            content: `🛒 **Traveling Merchant** — you don't have anything the merchant is interested in buying.\n\n💰 Your zeni: **${(character.zeni || 0).toLocaleString()}**`,
            components: [new ActionRowBuilder().addComponents(
                new ButtonBuilder().setCustomId('tm_open').setLabel('⬅️ Back to Shop').setStyle(ButtonStyle.Secondary)
            )]
        };
    }
    // Cap the list so the menu stays within Discord's 5-button rows / 5-row message limit.
    const sellable = allSellable.slice(0, 20);
    const rows = [];
    let currentRow = null;
    const lines = [];
    sellable.forEach((item, idx) => {
        lines.push(`• **${item.name}** ×${item.qty} — sells for **${item.price.toLocaleString()} zeni** each`);
        if (!currentRow || currentRow.components.length >= 5) {
            currentRow = new ActionRowBuilder();
            rows.push(currentRow);
        }
        currentRow.addComponents(
            new ButtonBuilder().setCustomId(`tm_sell_${idx}`).setLabel(`💰 ${item.name.slice(0, 60)}`).setStyle(ButtonStyle.Secondary)
        );
    });
    if (allSellable.length > sellable.length) {
        lines.push(`…and ${allSellable.length - sellable.length} more (use \`/sell\` in a city for those).`);
    }
    rows.push(new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('tm_open').setLabel('⬅️ Back to Shop').setStyle(ButtonStyle.Secondary)
    ));
    return {
        content: `🛒 **Traveling Merchant** — what would you like to sell? (Pays **${Math.round(SELL_RATE * 100)}%** of an item's value)\n\n${lines.join('\n')}\n\n💰 Your zeni: **${(character.zeni || 0).toLocaleString()}**`,
        components: rows
    };
}

// Weapon ATTACK mod + inhibiting DEX mod, from the Trello "Weapons" card.
// attackMod adds to the attack (hit) roll; dexMod is the DEX penalty the weapon imposes while wielded.
const WEAPON_STATS = {
    'Club': { attackMod: '1d2', dexMod: '1d3', bypass: true },
    'Spiked Club': { attackMod: '1d3', dexMod: '1d3', bypass: true },
    'Power Pole': { attackMod: '1d4', dexMod: '1d3', bypass: true },
    'Bo-Staff': { attackMod: '1d4', dexMod: '1d3', bypass: true, damageMode: 'dex' },
    'Nun-Chuck': { attackMod: '1d2', dexMod: '1d3', bypass: true, damageMode: 'dex' },
    'Duel Sai': { attackMod: '2d2', dexMod: '1d4+1', damageMode: 'halfAttackHalfDex' },
    'Sword': { attackMod: '1d5', dexMod: '1d7+4' },
    'Katana': { attackMod: '1d2', dexMod: '1d7+5', damageMode: 'halfAttackHalfDex' },
    'Scythe': { attackMod: '1d7+1', dexMod: '1d8+4', noSwordsman: true },
    'Nodachi': { attackMod: '1d4+1', dexMod: '1d9+5', damageMode: 'halfAttackHalfDex', noSwordsman: true },
    'Spear': { attackMod: '1d6+2', dexMod: '1d8+3', noSwordsman: true },
    'Spear of Longinus': { attackMod: '1d17+2', dexMod: '1d9+2', damageMode: 'halfWilHalfStr', noSwordsman: true, conBonus: 5, wilBonus: 5 },
    'Halberd': { attackMod: '1d8+3', dexMod: '1d10+5', noSwordsman: true },
    'Greatsword': { attackMod: '1d9+3', dexMod: '1d10+5' },
    'Greathammer': { attackMod: '1d10+3', dexMod: '1d11+8', bypass: true, noSwordsman: true },
    'Bansho Fan': { attackMod: '1d3', dexMod: '1d2+1', bypass: true, damageMode: 'halfSpiHalfStr' },
    'Brave Sword': { attackMod: '1d15+4', dexMod: '1d8+3' },
    'Dimension Sword': { attackMod: '1d20+6', dexMod: '1d6+2', bypass: true }
};

// Bladed sword types (for Konatsian Sword Proficiency / Feinting Strike).
const SWORD_TYPES = new Set(['Sword', 'Katana', 'Nodachi', 'Greatsword', 'Brave Sword', 'Dimension Sword', 'Scythe']);

// Strip a quality prefix ("Masterwork Katana" -> "Katana"), then look up the weapon's type.
function parseWeaponType(weaponName) {
    if (!weaponName) return null;
    let rest = weaponName;
    for (const q of GEAR_QUALITIES) {
        const prefix = q.name + ' ';
        if (rest.startsWith(prefix)) { rest = rest.slice(prefix.length); break; }
    }
    return WEAPON_STATS[rest] ? rest : null;
}

// Roll a weapon stat expression like "1d5", "1d7+4", "2d2", or "d11+8".
function rollWeaponDie(expr) {
    if (!expr) return 0;
    const m = /^(\d*)d(\d+)(?:\s*\+\s*(\d+))?$/i.exec(expr.trim());
    if (!m) return 0;
    const count = m[1] ? parseInt(m[1], 10) : 1;
    const sides = parseInt(m[2], 10);
    const flat = m[3] ? parseInt(m[3], 10) : 0;
    let sum = 0;
    for (let i = 0; i < count; i++) sum += getRandomInt(sides);
    return sum + flat;
}

// Quality modifiers applied to weapons (Trello "Weapons"/"Smithing" cards): better quality
// adds ATTACK and reduces the weapon's inhibiting DEX penalty.
const WEAPON_QUALITY_MODS = {
    'Masterwork': { weaponStr: 4, weaponDex: 2 },
    'Expert': { weaponStr: 3, weaponDex: 1 },
    'Tempered': { weaponStr: 2, weaponDex: 1 },
    'Fine': { weaponStr: 2, weaponDex: 1 },
    'Regular': { weaponStr: 0, weaponDex: 0 },
    'Bad': { weaponStr: -1, weaponDex: 0 },
    'Worthless': { weaponStr: -2, weaponDex: 1 }
};

// Detect the quality prefix of a weapon/armor name ("Masterwork Katana" -> "Masterwork"), or null.
function getWeaponQuality(weaponName) {
    if (!weaponName) return null;
    for (const q of GEAR_QUALITIES) {
        if (String(weaponName).startsWith(q.name + ' ')) return q.name;
    }
    return null;
}

// Roll a weapon's ATK mod, DEX penalty, and damage mode for a given weapon name.
// Quality (Masterwork/Fine/etc.) modifies the rolled stats.
function getWeaponMods(weaponName) {
    const type = parseWeaponType(weaponName);
    if (!type) return null;
    const w = WEAPON_STATS[type];
    const q = WEAPON_QUALITY_MODS[getWeaponQuality(weaponName)] || { weaponStr: 0, weaponDex: 0 };
    return {
        attackMod: rollWeaponDie(w.attackMod) + q.weaponStr,
        dexPenalty: Math.max(0, rollWeaponDie(w.dexMod) - q.weaponDex),
        damageMode: w.damageMode || 'str',
        bypass: !!w.bypass,
        type,
        conBonus: w.conBonus || 0,
        wilBonus: w.wilBonus || 0
    };
}

// Store the rolled weapon modifiers on an enemy object (call after enemy.weapon is set).
function applyEnemyWeaponMods(enemy) {
    const mods = getWeaponMods(enemy.weapon);
    if (mods) {
        enemy.weaponType = mods.type;
        enemy.weaponAttackMod = mods.attackMod;
        enemy.weaponDexPenalty = applyWeaponProficiencyReduction(enemy.race, enemy.style, mods.type, mods.dexPenalty);
        enemy.weaponDamageMode = mods.damageMode;
        enemy.weaponBypass = mods.bypass;
        enemy.weaponConBonus = mods.conBonus || 0;
        enemy.weaponWilBonus = mods.wilBonus || 0;
    }
}

// Martial weapons for the Tortle "Ancient Martial Weapon Proficiency" passive.
const MARTIAL_WEAPON_TYPES = new Set(['Katana', 'Nodachi', 'Duel Sai', 'Nun-Chuck', 'Bo-Staff', 'Spear', 'Power Pole']);

// Apply racial/style weapon-proficiency reductions to a weapon's inhibiting DEX penalty.
// - Swordsman style: -1d4 with bladed swords (Trello "Swordsman" card).
// - Konatsian: -4 with bladed swords (Trello "Sword Proficiency").
// - Tortle: -1d3 with martial weapons (Trello "Ancient Martial Weapon Proficiency").
function applyWeaponProficiencyReduction(race, fightingStyle, weaponType, weaponDexPenalty) {
    if (!weaponType || weaponDexPenalty <= 0) return weaponDexPenalty;
    if (fightingStyle === 'Swordsman' && SWORD_TYPES.has(weaponType)) {
        return Math.max(0, weaponDexPenalty - getRandomInt(4));
    }
    if (race === 'Konatsian' && SWORD_TYPES.has(weaponType)) {
        return Math.max(0, weaponDexPenalty - 4);
    }
    if (race === 'Tortle' && MARTIAL_WEAPON_TYPES.has(weaponType)) {
        return Math.max(0, weaponDexPenalty - getRandomInt(3));
    }
    return weaponDexPenalty;
}

// Quality modifiers for enemy armor, keyed by quality name (better quality = more damage
// reduction, less DEX hindrance, more durability).
const ARMOR_QUALITY_MODS = {
    'Masterwork': { dr: 15, dex: 10, dur: 5 },
    'Expert': { dr: 10, dex: 8, dur: 3 },
    'Tempered': { dr: 7, dex: 5, dur: 0 },
    'Fine': { dr: 5, dex: 5, dur: 0 },
    'Regular': { dr: 0, dex: 0, dur: 0 },
    'Bad': { dr: -10, dex: 0, dur: -3 },
    'Worthless': { dr: -20, dex: 0, dur: -5 }
};

// Roll a gear quality, biasing toward better quality at higher difficulty rank. At rank 0 it's
// uniform; each rank adds "advantage" (best-of-N rolls), so high-rank enemies more often carry
// Masterwork/Expert gear.
function rollQualityForRank(rank) {
    const n = 1 + (rank || 0);
    let best = getRandomInt(GEAR_QUALITIES.length) - 1;
    for (let i = 1; i < n; i++) {
        const idx = getRandomInt(GEAR_QUALITIES.length) - 1;
        if (idx < best) best = idx;
    }
    return GEAR_QUALITIES[best];
}

// Roll a suit of enemy armor (or null). Higher difficulty rank = more common + better quality.
function rollEnemyArmor(rank) {
    const chance = Math.min(70, 10 + (rank || 0) * 15); // 10% casual → 70% boss
    if (getRandomInt(100) > chance) return null;
    const weight = ARMOR_WEIGHTS[getRandomInt(ARMOR_WEIGHTS.length) - 1];
    const quality = rollQualityForRank(rank);
    const q = ARMOR_QUALITY_MODS[quality.name] || { dr: 0, dex: 0, dur: 0 };
    let damageReduction, dexReduction, durability;
    if (weight === 'Light') { damageReduction = getRandomInt(20); dexReduction = getRandomInt(20) + 15; durability = getRandomInt(30); }
    else if (weight === 'Heavy') { damageReduction = getRandomInt(50); dexReduction = getRandomInt(40) + 30; durability = getRandomInt(60); }
    else { damageReduction = getRandomInt(35); dexReduction = getRandomInt(35) + 20; durability = getRandomInt(45); }
    damageReduction = Math.max(0, Math.min(90, damageReduction + q.dr));
    dexReduction = Math.max(0, Math.min(90, dexReduction - q.dex));
    durability = Math.max(0, durability + q.dur);
    return {
        name: `${quality.name} ${weight} Armor`,
        armorReduction: damageReduction,
        armorDexReduction: dexReduction,
        armorDurability: durability,
        weight
    };
}

// ---------- Smithing (Trello "Smithing" card) ----------
// Ore -> ingot by smelting the raw ore.
const ORE_INGOTS = {
    'Iron Ore': 'Iron Ingot',
    'Steel Ore': 'Steel Ingot',
    'Mithril': 'Mithril Ingot',
    'Soul Stone': 'Soulstone Ingot',
    'Ebonite': 'Ebonite Ingot',
    'Orichalcum': 'Orichalcum Ingot',
    'Adamantine': 'Adamantine Ingot',
    'Katchin': 'Katchin Ingot'
};

// Material bonuses applied to forged gear (keyed by material name, e.g. 'Steel' from 'Steel Ingot').
// `weaponStr`/`weaponDex` affect weapon attack; `weaponSpiDmgPct`/`weaponWilDmgPct` add that % of the
// stat's mod to physical weapon damage; `armorCon`/`armorDex` are % mods to armor DR/DEX-penalty;
// `armorWil`/`armorSpi` are flat stat bonuses granted by the armor; `durability` adjusts armor durability.
const ORE_BONUSES = {
    'Iron': { weaponStr: 0, weaponDex: 0, armorCon: 0, armorDex: 0, durability: 0 },
    'Steel': { weaponStr: 2, weaponDex: 0, armorCon: 20, armorDex: 0, durability: 2 },
    'Mithril': { weaponStr: 0, weaponDex: 1, armorCon: 0, armorDex: 20, durability: -5 },
    'Adamantine': { weaponStr: 3, weaponDex: 2, armorCon: 30, armorDex: 0, durability: 10 },
    'Katchin': { weaponStr: 4, weaponDex: 2, armorCon: 0, armorDex: 35, armorWil: 0, armorSpi: 0, durability: 4 },
    'Soulstone': { weaponStr: 0, weaponDex: 0, weaponSpiDmgPct: 15, armorCon: 0, armorDex: 0, armorWil: 20, armorSpi: 0, durability: -15 },
    'Orichalcum': { weaponStr: 2, weaponDex: -2, armorCon: 20, armorDex: -20, durability: 10 },
    'Ebonite': { weaponStr: 0, weaponDex: 1, weaponWilDmgPct: 20, armorCon: 0, armorDex: 0, armorWil: 0, armorSpi: 20, durability: -10 }
};

// Roll a forged gear's quality (d20 + INT) and return its modifiers.
// Smithing proficiency replaces INT for gear quality: the higher it is, the easier it is
// to forge high-quality gear. It caps at SMITHING_PROFICIENCY_MAX.
const SMITHING_PROFICIENCY_MAX = 100;

// A character's smithing proficiency (clamped, defaults to 0).
function getSmithingProficiency(character) {
    return Math.max(0, Math.min(SMITHING_PROFICIENCY_MAX, Number(character && character.smithingProficiency) || 0));
}

// Proficiency gained per smith action. This is a bell-curve / diminishing-returns curve:
// it's easy to improve at first but gets harder and harder as you approach the cap.
function smithingProficiencyGain(proficiency) {
    const t = Math.max(0, Math.min(1, proficiency / SMITHING_PROFICIENCY_MAX));
    return Math.max(1, Math.round(10 * (1 - t * t)));
}

function rollSmithQuality(proficiency) {
    const roll = getRandomInt(20) + Math.floor((proficiency || 0) / 4);
    if (roll >= 33) return { key: 'Masterwork', weaponStr: 4, weaponDex: 2, armorDR: 10, armorDurability: 5 };
    if (roll >= 29) return { key: 'Fine', weaponStr: 2, weaponDex: 1, armorDR: 8, armorDurability: 3 };
    if (roll >= 21) return { key: 'Good', weaponStr: 1, weaponDex: 0, armorDR: 5, armorDurability: 0 };
    if (roll >= 15) return { key: 'Ok', weaponStr: 0, weaponDex: 0, armorDR: 0, armorDurability: 0 };
    if (roll >= 9) return { key: 'Bad', weaponStr: -1, weaponDex: 0, armorDR: -10, armorDurability: -2 };
    return { key: 'Worthless', weaponStr: -2, weaponDex: 1, armorDR: -20, armorDurability: -3 };
}

// Forge a weapon from an ingot: applies the weapon-type base + material + quality modifiers.
function forgeWeapon(character, ingot, weaponTypeName) {
    const material = ingot.replace(/ Ingot$/, '');
    const oreB = ORE_BONUSES[material] || ORE_BONUSES['Iron'];
    const base = WEAPON_STATS[weaponTypeName];
    const q = rollSmithQuality(getSmithingProficiency(character));
    const attackMod = rollWeaponDie(base.attackMod) + oreB.weaponStr + q.weaponStr;
    const dexPenalty = Math.max(0, rollWeaponDie(base.dexMod) - (oreB.weaponDex + q.weaponDex));
    return {
        name: `${q.key} ${material} ${weaponTypeName}`,
        weaponType: weaponTypeName,
        weaponAttackMod: attackMod,
        weaponDexPenalty: dexPenalty,
        weaponDamageMode: base.damageMode || 'str',
        weaponBypass: !!base.bypass,
        weaponConBonus: base.conBonus || 0,
        weaponWilBonus: base.wilBonus || 0,
        weaponSpiDmgPct: oreB.weaponSpiDmgPct || 0,
        weaponWilDmgPct: oreB.weaponWilDmgPct || 0,
        quality: q.key,
        material
    };
}

// Forge a suit of armor from an ingot: applies the weight base + material + quality modifiers.
function forgeArmor(character, ingot, weight) {
    const material = ingot.replace(/ Ingot$/, '');
    const oreB = ORE_BONUSES[material] || ORE_BONUSES['Iron'];
    const q = rollSmithQuality(getSmithingProficiency(character));
    let damageReduction, dexReduction, durability;
    if (weight === 'Light') { damageReduction = getRandomInt(20); dexReduction = getRandomInt(20) + 15; durability = getRandomInt(30); }
    else if (weight === 'Heavy') { damageReduction = getRandomInt(50); dexReduction = getRandomInt(40) + 30; durability = getRandomInt(60); }
    else { damageReduction = getRandomInt(35); dexReduction = getRandomInt(35) + 20; durability = getRandomInt(45); }
    damageReduction = Math.max(0, Math.min(90, Math.round(damageReduction * (1 + oreB.armorCon / 100)) + q.armorDR));
    // Material "+% DEX" eases the armor's DEX penalty; negative values worsen it.
    dexReduction = Math.max(0, Math.min(90, Math.round(dexReduction * (1 - oreB.armorDex / 100))));
    durability = Math.max(0, durability + oreB.durability + q.armorDurability);
    return {
        name: `${q.key} ${material} ${weight} Armor`,
        armorReduction: damageReduction,
        armorDexReduction: dexReduction,
        armorDurability: durability,
        armorWilBonus: oreB.armorWil || 0,
        armorSpiBonus: oreB.armorSpi || 0,
        quality: q.key,
        material,
        weight
    };
}

// Trello "Weapons / Armor Sell" values, by quality (Masterwork* keeps the 3M value above).
// Sells were raised ~90% so crafted weapons & armor are worth more to sell.
const GEAR_SELL_VALUES = { Masterwork: 190000, Expert: 95000, Tempered: 47500, Fine: 19000, Regular: 9500, Bad: 475, Worthless: 28 };

function gearItemPrice(quality, weight) {
    if (!weight) return quality.price; // weapon
    if (weight === 'Heavy') return quality.heavyPrice;
    if (weight === 'Medium') return Math.round((quality.price + quality.heavyPrice) / 2);
    return quality.price; // Light
}

// Daily gear stock per city/slot: always stocks BOTH weapons and armor, each a concrete item.
const gearStock = new Map(); // `${location}-${space}` -> { date, items }
function getGearStock(location, space) {
    const key = `${location}-${space}`;
    const today = new Date().toDateString();
    const existing = gearStock.get(key);
    if (existing && existing.date === today) return existing;

    const items = [];
    const addGear = (name, category, basePrice) => {
        const sale = getSaleInfo(location, space, name, basePrice);
        items.push({ name, category, price: basePrice, sale: sale.sale, salePrice: sale.salePrice, remaining: getRandomInt(3) });
    };

    const weaponCount = getRandomInt(3) + 1; // 1-3 weapons
    for (let i = 0; i < weaponCount; i++) {
        const q = GEAR_QUALITIES[getRandomInt(GEAR_QUALITIES.length) - 1];
        const type = WEAPON_TYPES[getRandomInt(WEAPON_TYPES.length) - 1];
        addGear(`${q.name} ${type}`, 'weapon', q.price);
    }
    const armorCount = getRandomInt(3) + 1; // 1-3 armor pieces
    for (let i = 0; i < armorCount; i++) {
        const q = GEAR_QUALITIES[getRandomInt(GEAR_QUALITIES.length) - 1];
        const weight = ARMOR_WEIGHTS[getRandomInt(ARMOR_WEIGHTS.length) - 1];
        addGear(`${q.name} ${weight} Armor`, 'armor', gearItemPrice(q, weight));
    }

    const stock = { date: today, items };
    gearStock.set(key, stock);
    return stock;
}

function getGearStockItem(location, space, itemName) {
    const stock = getGearStock(location, space);
    return stock.items.find(i => i.name.toLowerCase() === itemName.toLowerCase()) || null;
}

// Trello consumable items (from the "Merchant and Items" cards).
// Effects: `hp`/`ki` are % of max unless `flat: true`; `fatigue` is a % delta (negative removes);
// `dice` rolls XdY % for the given stat; `full` restores HP, Ki, and removes all fatigue.
const CONSUMABLE_ITEMS = {
    'Senzu Bean': { full: true },
    'Bread': { ki: 5, flat: true },
    'Ramen': { hp: 8, ki: 10, flat: true },
    'Dumplings': { hp: 3, ki: 6, flat: true },
    'Vita Drink': { dice: { hp: '1d5', fatigue: '1d5', ki: '1d5' } },
    'Sage Water': { dice: { ki: '1d20', fatigue: '1d20' } },
    'Hetap™': { dice: { hp: '1d7', fatigue: '1d7', ki: '1d7' } },
    'Recovery Capsule': { hp: 50, fatigue: -20 },
    'Mixed Capsule': { hp: 25, ki: 25, fatigue: -10 },
    'Ki Recovery Capsule': { ki: 50 },
    "Healer's Kit": { hp: 40, fatigue: -15 }
};

// Food eaten via /eat (fish are eaten cooked; flat values per Trello)
const FOOD_ITEMS = {
    'Bread': CONSUMABLE_ITEMS['Bread'],
    'Ramen': CONSUMABLE_ITEMS['Ramen'],
    'Dumplings': CONSUMABLE_ITEMS['Dumplings'],
    'Hetap™': CONSUMABLE_ITEMS['Hetap™'],
    'Vita Drink': CONSUMABLE_ITEMS['Vita Drink'],
    'Sage Water': CONSUMABLE_ITEMS['Sage Water'],
    'Small Fish': { hp: 2, ki: 2, flat: true },
    'Medium Fish': { hp: 4, ki: 4, flat: true },
    'Large Fish': { hp: 6, ki: 6, fatigue: -2, flat: true },
    'Huge Fish': { hp: 9, ki: 9, fatigue: -4, flat: true },
    'Massive Fish': { hp: 15, ki: 15, fatigue: -8, flat: true },
    // Meat from /hunt animals. Raw meat must be cooked before it can be eaten (see /cook).
    'Rabbit Meat': { hp: 4, ki: 4, fatigue: -2, flat: true },
    'Deer Meat': { hp: 7, ki: 7, fatigue: -2, flat: true },
    'Wolf Meat': { hp: 8, ki: 8, fatigue: -3, flat: true },
    'Bear Meat': { hp: 12, ki: 12, fatigue: -5, flat: true },
    'Dinosaur Meat': { hp: 25, ki: 25, fatigue: -5, flat: true }
};

// Build a raw (uncooked) meat item from a hunted animal, so it must be cooked before eating.
function makeRawMeat(name) {
    const spec = FOOD_ITEMS[name] || {};
    return { name, type: 'consumable', cooked: false, hp: spec.hp || 0, ki: spec.ki || 0, fatigue: spec.fatigue || 0 };
}

// Roll an XdY percent string (e.g. '1d7' -> 1..7)
function rollPct(dice) {
    const m = String(dice).toLowerCase().match(/^(\d+)d(\d+)$/);
    if (!m) return 0;
    const count = parseInt(m[1], 10);
    const sides = parseInt(m[2], 10);
    let total = 0;
    for (let i = 0; i < count; i++) total += getRandomInt(sides);
    return total;
}

// Is this an uncooked/raw fish or meat? (must be cooked before use)
function isUncookedFood(item) {
    return !!(item && typeof item === 'object' && /(fish|meat)$/i.test(String(item.name || '')) && item.cooked !== true);
}

// Is this a fish item object?
function isFishObject(item) {
    return !!(item && typeof item === 'object' && /fish$/i.test(String(item.name || '')));
}

// A Fishing Tackle stores up to this many fish (each takes 0 inventory slots).
const FISHING_TACKLE_CAPACITY = 50;

// Does the character own a Fishing Tackle (fish storage container)?
function hasFishingTackle(character) {
    return countInventoryItem(character.inventory || [], 'Fishing Tackle') > 0;
}

// The character's fishing tackle storage array (initialized if missing).
function getFishTackle(character) {
    if (!Array.isArray(character.fishTackle)) character.fishTackle = [];
    return character.fishTackle;
}

// Fish species: weight range (kg), food effects, and sell value per kg.
// Higher-weight fish are rarer and sell for a lot more (Trello fishing).
const FISH_SPECIES = {
    'Small Fish':   { min: 1,      max: 8,       hp: 2,  ki: 2,  fatigue: 0,  rate: 250,  id: 'small' },
    'Medium Fish':  { min: 9,      max: 14.50,   hp: 4,  ki: 4,  fatigue: 0,  rate: 400,  id: 'medium' },
    'Large Fish':   { min: 14.51,  max: 34.38,   hp: 6,  ki: 6,  fatigue: -2, rate: 650,  id: 'large' },
    'Huge Fish':    { min: 34.38,  max: 57.80,   hp: 9,  ki: 9,  fatigue: -4, rate: 1000, id: 'huge' },
    'Massive Fish': { min: 57.81,  max: 857.38,  hp: 15, ki: 15, fatigue: -8, rate: 3000, id: 'massive', massive: true }
};

// Roll a fish's weight. Massive fish heavily bias toward the low end (really heavy ones are very rare).
function rollFishWeight(species) {
    const s = FISH_SPECIES[species];
    const span = s.max - s.min;
    const t = s.massive ? Math.pow(Math.random(), 3) : Math.random();
    return Math.round((s.min + t * span) * 100) / 100;
}

// ---------- Fish price curve (smooth weight-based) ----------
// Control points (weight kg -> zeni) chosen around the real FISH_SPECIES ranges:
//   Small 1–8, Medium 9–14.5, Large 14.51–34.38, Huge 34.38–57.8, Massive 57.81–857.38
// Medium/Large land ~8k–12k; Huge/Massive rise smoothly ~20k–33k with a diminishing tail.
const FISH_PRICE_CURVE = [
    { weight: 1, price: 400 },
    { weight: 9, price: 8000 },
    { weight: 14.5, price: 10500 },
    { weight: 26, price: 11500 },
    { weight: 34.4, price: 12000 },
    { weight: 40, price: 20000 },
    { weight: 47, price: 24500 },
    { weight: 57.8, price: 27000 },
    { weight: 120, price: 29000 },
    { weight: 400, price: 31000 },
    { weight: 857.4, price: 33000 }
];

// Monotonic smoothstep interpolation between control points (continuous, no category jumps).
function getFishPriceCurveValue(weight, points = FISH_PRICE_CURVE) {
    if (!points || points.length === 0) return 0;
    const w = Number(weight);
    if (w <= points[0].weight) return points[0].price;
    const last = points[points.length - 1];
    if (w >= last.weight) return last.price;
    for (let i = 0; i < points.length - 1; i++) {
        const a = points[i], b = points[i + 1];
        if (w >= a.weight && w <= b.weight) {
            const t = (w - a.weight) / (b.weight - a.weight);
            const s = t * t * (3 - 2 * t); // smoothstep
            return Math.round(a.price + (b.price - a.price) * s);
        }
    }
    return last.price;
}

// A fish's sell value grows with its weight via a smooth curve (no abrupt category jumps).
function getFishSellValue(fish) {
    const s = FISH_SPECIES[fish && fish.name] || FISH_SPECIES['Small Fish'];
    const weight = fish && typeof fish.weight === 'number' ? fish.weight : s.min;
    return Math.max(1, getFishPriceCurveValue(weight));
}

// A "Fish Again" button row so players can keep fishing without re-typing /fish (avoids channel spam).
function fishAgainRow() {
    return new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('fish_again')
                .setLabel('🎣 Fish Again')
                .setStyle(ButtonStyle.Primary)
        );
}

// Core fishing logic shared by the /fish command and the "Fish Again" button.
async function runFishing(interaction, isButton = false) {
    // Button clicks replace the existing message; slash commands create a new one.
    const send = (payload) => isButton ? interaction.update(payload) : interaction.reply(payload);

    const character = characterManager.getCharacter(interaction.user.id);

    if (!character) {
        return send({ content: 'You need a character to go fishing! Use `/character-create` to make one.' });
    }

    if (!isInCorrectChannel(interaction, character)) {
        return send({ content: wrongChannelReply(character) });
    }

    // You can only fish on a planet — not in space.
    if ((character.location || 'Earth') === 'Space') {
        return send({ content: '❌ You can\'t fish in **space**! Travel to a planet first.' });
    }

    // Check if character has a fishing rod
    const hasFishingRod = character.inventory && character.inventory.some(item => {
        const itemName = typeof item === 'string' ? item : item.name;
        return itemName.toLowerCase().includes('fishing rod');
    });

    if (!hasFishingRod) {
        return send({ content: '❌ You need a **Fishing Rod** to fish! Find one using `/search`.' });
    }

    const chance = getRandomInt(20);
    let fishItem = null;
    let text = "";

    if (chance === 1) {
        // Fishing Rod loses 1 durability on a critical fail (Trello: 3/3 durability, breaks at 0).
        const inv = Array.isArray(character.inventory) ? character.inventory : [];
        const rodIdx = inv.findIndex(item => {
            const name = typeof item === 'string' ? item : (item && item.name);
            return String(name || '').toLowerCase().includes('fishing rod');
        });
        // Jeremy Wade's Fishing Rod has Infinite Durability — never loses durability or breaks.
        const rodName = rodIdx !== -1 ? String(typeof inv[rodIdx] === 'string' ? inv[rodIdx] : (inv[rodIdx] && inv[rodIdx].name) || '') : '';
        if (rodName.toLowerCase().includes('jeremy wade')) {
            text = `🎣 ${interaction.user.displayName}'s **Jeremy Wade's Fishing Rod** (Infinite Durability) bends but never breaks!`;
        } else if (rodIdx !== -1) {
            // Legacy rods may be stored as plain strings (possibly a stacked "Nx Fishing Rod") —
            // expand them into individual durability objects so only one rod breaks, not the whole stack.
            if (typeof inv[rodIdx] === 'string') {
                const durable = DURABLE_ITEMS['Fishing Rod'] || { max: 3 };
                const count = parseItemName(inv[rodIdx]).quantity;
                const rods = [];
                for (let i = 0; i < count; i++) rods.push({ name: 'Fishing Rod', durability: durable.max, maxDurability: durable.max });
                inv.splice(rodIdx, 1, ...rods);
            }
            if (typeof inv[rodIdx] === 'object' && inv[rodIdx].durability !== undefined) {
                inv[rodIdx].durability -= 1;
                if (inv[rodIdx].durability <= 0) {
                    inv.splice(rodIdx, 1);
                    text = `💔 ${interaction.user.displayName}'s fishing rod broke! It hit **0 durability**.`;
                } else {
                    text = `🎣 ${interaction.user.displayName}'s fishing rod lost 1 durability (${inv[rodIdx].durability}/${inv[rodIdx].maxDurability}) because they suck at fishing!`;
                }
                characterManager.updateCharacter(interaction.user.id, character.id, { inventory: inv });
            } else {
                text = `🎣 ${interaction.user.displayName}'s fishing rod lost 1 durability because they suck at fishing!`;
            }
        } else {
            text = `🎣 ${interaction.user.displayName}'s fishing rod lost 1 durability because they suck at fishing!`;
        }
    } else {
        // Species rarity from a 1d20: Small(2-7 / 30%) < Medium(8-12 / 25%) < Large(13-16 / 20%)
        // < Huge(17-19 / 15%) < Massive(20 / 5% — the rarest).
        let species;
        if (chance <= 7) species = 'Small Fish';
        else if (chance <= 12) species = 'Medium Fish';
        else if (chance <= 16) species = 'Large Fish';
        else if (chance <= 19) species = 'Huge Fish';
        else species = 'Massive Fish';
        const s = FISH_SPECIES[species];
        const weight = rollFishWeight(species);
        fishItem = {
            name: species,
            type: 'consumable',
            cooked: false,
            hp: s.hp,
            ki: s.ki,
            fatigue: s.fatigue,
            weight
        };
        text = `🎣 ${interaction.user.displayName} caught a **${species}** (${weight} kg)! ${s.hp ? `When cooked it restores **+${s.hp} HP**, **+${s.ki} Ki**${s.fatigue ? `, and **${s.fatigue}% Fatigue**` : ''}.` : ''}`;
    }

    // Add fish to inventory (or the Fishing Tackle, which takes no inventory space).
    if (fishItem) {
        // Track the heaviest fish the character has ever caught (for the leaderboard).
        const thisWeight = fishItem.weight || 0;
        if (thisWeight > (character.heaviestFishWeightKg || 0)) {
            character.heaviestFishWeightKg = thisWeight;
            character.heaviestFishName = fishItem.name;
        }
        // Advance an NPC "catch N Massive Fish" quest.
        if ((fishItem.name || '') === 'Massive Fish') {
            text += processNpcCollectionQuest(interaction, character, 'fish', 1);
        }
        const tackle = getFishTackle(character);
        if (hasFishingTackle(character) && tackle.length < FISHING_TACKLE_CAPACITY) {
            tackle.push(fishItem);
            characterManager.updateCharacter(interaction.user.id, character.id, { fishTackle: tackle, heaviestFishWeightKg: character.heaviestFishWeightKg, heaviestFishName: character.heaviestFishName });
            text += `\n📦 Stored in your **Fishing Tackle** (${tackle.length}/${FISHING_TACKLE_CAPACITY}) — takes no inventory space!`;
        } else {
            const result = characterManager.addItem(interaction.user.id, character.id, fishItem);
            if (result && !result.success) {
                text = `❌ ${result.message}\n\nYou caught a fish but your inventory is full!`;
            }
            characterManager.updateCharacter(interaction.user.id, character.id, { heaviestFishWeightKg: character.heaviestFishWeightKg, heaviestFishName: character.heaviestFishName });
        }
    }

    return send({ content: text, components: [fishAgainRow()] });
}

// Resolve an inventory entry into a consumable effect spec, or null if it isn't consumable.
function getConsumableEffect(item) {
    const data = typeof item === 'string' ? { name: item, type: 'unknown' } : item;
    // Raw fish must be cooked before they can be used/eaten.
    if (isUncookedFood(item)) return null;
    const name = parseItemName(data.name || data).name; // strip a stacked "Nx " prefix
    if (CONSUMABLE_ITEMS[name]) return CONSUMABLE_ITEMS[name];
    if (FOOD_ITEMS[name]) return FOOD_ITEMS[name];
    if (data.type === 'consumable') {
        return { hp: data.hp || 0, ki: data.ki || 0, fatigue: data.fatigue || 0, flat: true };
    }
    return null;
}

// Compute the concrete HP/Ki/fatigue changes a consumable applies to a character.
function computeConsumableEffect(spec, character) {
    const maxHP = character.maxHP || 1;
    const maxKi = character.maxKi || 1;
    let hpHeal = 0, kiHeal = 0, fatigueDelta = 0, full = false;
    if (spec.full) full = true;
    if (spec.dice) {
        if (spec.dice.hp) hpHeal += Math.round(maxHP * rollPct(spec.dice.hp) / 100);
        if (spec.dice.ki) kiHeal += Math.round(maxKi * rollPct(spec.dice.ki) / 100);
        if (spec.dice.fatigue) fatigueDelta -= rollPct(spec.dice.fatigue);
    }
    if (spec.hp) hpHeal += spec.flat ? spec.hp : Math.round(maxHP * spec.hp / 100);
    if (spec.ki) kiHeal += spec.flat ? spec.ki : Math.round(maxKi * spec.ki / 100);
    if (spec.fatigue) fatigueDelta += spec.fatigue;
    return { hpHeal, kiHeal, fatigueDelta, full };
}

