// Merge config-driven crafting recipes (from config.json `craftingRecipes`) over the defaults,
// so recipes can be tuned/added per JSON without touching code.
if (craftingRecipes && typeof craftingRecipes === 'object') {
    Object.assign(CRAFTING_RECIPES, craftingRecipes);
}

// Daily per-city stock: every city rolls its OWN stock for each item from rarity ranges (10-500)
const shopStock = new Map(); // `${location}-${space}-${item}` -> { date, remaining, range }

function getCityName(location, space) {
    const cities = MERCHANT_CITIES[location];
    return cities ? (cities[space] || null) : null;
}

function getShopStock(location, space, itemName) {
    const entry = MERCHANT_PRICES[itemName];
    if (!entry) return null;
    const range = entry.stock && typeof entry.stock === 'object'
        ? entry.stock
        : (STOCK_TIERS[entry.stock] || STOCK_TIERS.common);
    const key = `${location}-${space}-${itemName}`;
    const today = new Date().toDateString();
    const existing = shopStock.get(key);
    if (!existing || existing.date !== today) {
        const stock = {
            date: today,
            remaining: range.min + getRandomInt(range.max - range.min + 1) - 1,
            range
        };
        shopStock.set(key, stock);
        return stock;
    }
    return existing;
}

// Value of an item in zeni (for /sell: pays SELL_RATE of this)
function getItemValue(name) {
    if (MERCHANT_PRICES[name]) return MERCHANT_PRICES[name].price;
    if (EXTRA_ITEM_VALUES[name] !== undefined) return EXTRA_ITEM_VALUES[name];
    if (/^masterwork/i.test(name)) return 5700000; // Masterwork crafted gear, raised ~90%
    // Stocked/crafted weapons & armor: sell by quality (Trello "Weapons / Armor Sell")
    const gearQuality = Object.keys(GEAR_SELL_VALUES).find(q => name.startsWith(q + ' '));
    if (gearQuality) return GEAR_SELL_VALUES[gearQuality];
    return null;
}

// Items that cannot be sold (Trello "Infinite Durability [ Unsellable ]" etc.).
const UNSELLABLE_ITEMS = new Set(["Jeremy Wade's Fishing Rod"]);

function getSellPrice(name) {
    if ([...UNSELLABLE_ITEMS].some(u => u.toLowerCase() === String(name || '').toLowerCase())) return null;
    const value = getItemValue(name);
    return value === null ? null : Math.max(1, Math.floor(value * SELL_RATE));
}

// Compute a companion's power level from its battle stats (for the companion leaderboard).
function getCompanionPowerLevel(companion, ownerChar) {
    const stats = companion.isChild
        ? getChildBattleStats(companion)
        : getCompanionBattleStats(companion, ownerChar);
    const maxHP = calculateHP(stats.con, companion.race || null);
    const maxKi = calculateKi(stats.spi, companion.race || null);
    return characterManager.calculatePowerLevel({
        str: stats.str, dex: stats.dex, con: stats.con, wil: stats.wil, spi: stats.spi,
        maxHP, maxKi
    });
}

