// Planets players can travel between
const LOCATIONS = ['Earth', 'Namek', 'Frieza Planet', 'King Kai\'s Planet', 'Otherworld', 'Yardrat', 'Space'];

// Number of spaces on each planet
const PLANET_SPACES = {
    'Earth': 100,
    'Namek': 200,
    "King Kai's Planet": 10,
    'Otherworld': 10000,
    'Hell': 100,
    'Frieza Planet': 300,
    'Space': 1000000
};

// Default planet based on race
function getDefaultLocation(race) {
    if (race === 'Namekian') return 'Namek';
    if (race === 'Frost Demon' || race === 'Alien') return 'Frieza Planet';
    return 'Earth';
}

// Discord channel names for each planet (players must be in their planet's channel to act)
const PLANET_CHANNELS = {
    'Earth': 'earth',
    'Namek': 'namek',
    'Yardrat': 'yardrat',
    'Frieza Planet': 'frieza planet',
    'Otherworld': 'otherworld',
    'Hell': 'hell',
    'Space': 'space'
};

// Normalize a channel name for planet-channel matching (strip spaces/hyphens/underscores).
function normalizeChannelName(s) {
    return String(s || '').trim().toLowerCase().replace(/[\s_.-]+/g, '');
}

// Does a channel name belong to a planet channel? Accepts the base name plus numbered/spaced
// copies like #earth, #earth-1, #earth_2, #frieza-planet, #frieza-planet-1, etc.
function channelMatchesPlanet(channelName, expected) {
    if (!expected) return true;
    const base = normalizeChannelName(expected);
    const name = normalizeChannelName(channelName);
    if (name === base) return true;
    if (!name.startsWith(base)) return false;
    // The suffix must not begin with a letter, so #earthling isn't treated as Earth.
    return /^[^a-z]/.test(name.slice(base.length));
}

// Returns true if the player is in the Discord channel matching their current planet.
// Planets without a dedicated channel (e.g. King Kai's Planet) are allowed anywhere.
function isInCorrectChannel(interaction, character) {
    const channelName = (interaction.channel && interaction.channel.name ? interaction.channel.name : '').trim().toLowerCase();
    const planet = character.location || 'Earth';
    const expected = PLANET_CHANNELS[planet];
    return channelMatchesPlanet(channelName, expected);
}

function wrongChannelReply(character) {
    const planet = character.location || 'Earth';
    const expected = PLANET_CHANNELS[planet];
    return `❌ You're on **${planet}**, so you need to be in a **#${expected}** channel (e.g. #${expected}, #${expected}-1) to do that!`;
}

// Space travel capabilities
function hasSpaceship(character) {
    if (character.spaceship === true) return true;
    if (Array.isArray(character.inventory)) {
        return character.inventory.some(item => {
            const name = typeof item === 'string' ? item : item.name;
            return /spaceship|space ship|space pod|attack ball/i.test(String(name));
        });
    }
    return false;
}

function canFly(character) {
    const raceInfo = races[character.race];
    if (raceInfo && raceInfo.passives && raceInfo.passives.some(p => p.id === 'extraterrestrial-equilibrium')) return true;
    if (character.flight === true) return true;
    if (Array.isArray(character.techniques)) {
        return character.techniques.some(t => {
            const name = String(typeof t === 'string' ? t : (t.name || t)).toLowerCase();
            return name === 'fly' || /flight/i.test(name);
        });
    }
    return false;
}

function canSurviveSpace(character) {
    const raceInfo = races[character.race];
    return !!(raceInfo && raceInfo.passives && raceInfo.passives.some(p => p.id === 'space-breathing'));
}

// Fly mastery effects (Trello "Fly" card, 5 mastery levels):
//   1: drain -2 | 2: drain -2, travel 4 less | 3: drain -2, +2 DEX defense
//   4: drain -2, +3 retreat rolls, travel 6 less | 5: drain -2, travel free
function getFlyMasteryEffects(character) {
    if (!character) return { drainReduction: 0, dexDefense: 0, travelDiscount: 0, travelFree: false, retreatBonus: 0 };
    const m = Math.min(5, (character.techniqueMastery || {})['Fly'] || 0);
    const hasFly = Array.isArray(character.techniques) && character.techniques.includes('Fly');
    return {
        drainReduction: m * 2,
        dexDefense: m >= 3 ? 2 : 0,
        travelDiscount: hasFly ? 2 + (m >= 2 ? 2 : 0) + (m >= 4 ? 2 : 0) : 0,
        travelFree: m >= 5,
        retreatBonus: m >= 4 ? 3 : 0
    };
}

