function getPlanetExit(planet) {
    return PLANET_EXIT_SPACES[planet] || 1;
}

function getSpecialSlotName(location, space) {
    const slots = SPECIAL_SLOTS[location];
    if (!slots) return null;
    return slots[space] || null;
}

function getTravelSpeed(character) {
    if (hasSpaceship(character)) {
        const level = Math.max(1, Math.min(MAX_SHIP_LEVEL, character.spaceshipLevel || 1));
        return SHIP_LEVEL_SPEEDS[level] || 100;
    }
    if (canFly(character)) return FLIGHT_SPEED;
    return WALK_SPEED;
}

function hasSpacePod(character) {
    if (character.spacePod === true) return true;
    if (Array.isArray(character.inventory)) {
        return character.inventory.some(item => {
            const name = typeof item === 'string' ? item : item.name;
            return /space pod|attack ball/i.test(String(name));
        });
    }
    return false;
}

function countInventoryItem(inventory, name) {
    return inventory.reduce((total, item) => {
        const p = parseItemName(item);
        return p.name.toLowerCase() === name.toLowerCase() ? total + p.quantity : total;
    }, 0);
}

// Does the character own at least one of the named item (inventory or home storage)?
function ownsItem(character, name) {
    if (countInventoryItem(character.inventory || [], name) > 0) return true;
    if (character.homeStorage && countInventoryItem(character.homeStorage, name) > 0) return true;
    return false;
}

// Magic Carpet: two travel-roll rerolls per day (reset at midnight).
function getCarpetRerolls(character) {
    if (!ownsItem(character, 'Magic Carpet')) return 0;
    const today = new Date().toDateString();
    if (character.carpetRerollDay !== today || character.carpetRerolls === undefined) {
        character.carpetRerollDay = today;
        character.carpetRerolls = 2;
    }
    return character.carpetRerolls || 0;
}

function removeInventoryItems(inventory, name, amount) {
    let removed = 0;
    for (let i = 0; i < inventory.length && removed < amount; i++) {
        const p = parseItemName(inventory[i]);
        if (p.name.toLowerCase() !== name.toLowerCase()) continue;
        if (typeof inventory[i] === 'object') {
            // Object items (e.g. fish) always count as a single unit
            inventory.splice(i, 1);
            removed++;
            i--;
            continue;
        }
        const take = Math.min(p.quantity, amount - removed);
        const newQty = p.quantity - take;
        if (newQty <= 0) {
            inventory.splice(i, 1);
            i--;
        } else {
            inventory[i] = formatStackedItem(p.name, newQty);
        }
        removed += take;
    }
    return removed;
}

// Remove ONE unit from a single inventory slot (decrements a stack, or removes the item entirely).
function consumeInventorySlot(inventory, slotIndex) {
    if (slotIndex < 0 || slotIndex >= inventory.length) return;
    const p = parseItemName(inventory[slotIndex]);
    if (typeof inventory[slotIndex] === 'object') {
        inventory.splice(slotIndex, 1);
        return;
    }
    if (p.quantity > 1) {
        inventory[slotIndex] = formatStackedItem(p.name, p.quantity - 1);
    } else {
        inventory.splice(slotIndex, 1);
    }
}

// Add `amount` of a named item, stacking onto existing matching string entries.
function pushStackedItem(inventory, name, amount) {
    const p = parseItemName(name);
    const baseName = p.name;
    // Durable items (like the Fishing Rod) must NOT stack: each one tracks its own durability,
    // so a stack of "Nx Fishing Rod" would otherwise collapse/burst all of them on a break.
    const durable = DURABLE_ITEMS[baseName];
    for (let k = 0; k < amount; k++) {
        if (durable) {
            inventory.push({ name: baseName, durability: durable.max, maxDurability: durable.max });
            continue;
        }
        const idx = inventory.findIndex(existing => {
            if (typeof existing !== 'string') return false;
            return parseItemName(existing).name.toLowerCase() === baseName.toLowerCase();
        });
        if (idx !== -1) {
            const q = parseItemName(inventory[idx]).quantity;
            inventory[idx] = formatStackedItem(baseName, q + 1);
        } else {
            inventory.push(baseName);
        }
    }
}

// Move up to `maxCount` of a named item from `source` to `dest`, preserving crafted
// object items (weapons/armor/fish) as objects while stacking plain string items.
function moveNamedItems(source, dest, name, maxCount) {
    let moved = 0;
    // Object items: move exactly one unit each, preserving the object.
    for (let i = 0; i < source.length && moved < maxCount; i++) {
        const it = source[i];
        if (parseItemName(it).name.toLowerCase() !== name.toLowerCase()) continue;
        if (typeof it === 'object') {
            dest.push(it);
            source.splice(i, 1);
            i--;
            moved++;
        }
    }
    // Stackable string items.
    if (moved < maxCount) {
        const take = Math.min(countInventoryItem(source, name), maxCount - moved);
        if (take > 0) {
            removeInventoryItems(source, name, take);
            pushStackedItem(dest, name, take);
            moved += take;
        }
    }
    return moved;
}

// Build the /character-inventory message text plus per-slot dispose buttons.
function buildInventoryMessage(character, page = 0) {
    const maxSlots = character.inventorySlots || 10;
    const inventory = Array.isArray(character.inventory) ? character.inventory : [];
    const currentSlots = inventory.length;

    // 20 items per page: 4 dispose rows (5 each) + 1 nav row = max 5 action rows.
    const PAGE_SIZE = 20;
    const maxPage = Math.max(0, Math.ceil(inventory.length / PAGE_SIZE) - 1);
    const currentPage = Math.min(Math.max(0, page), maxPage);
    const start = currentPage * PAGE_SIZE;
    const pageItems = inventory.slice(start, start + PAGE_SIZE);

    let content = `💰 **Zeni:** ${(character.zeni || 0).toLocaleString()}\n📦 **Resources:** ${(character.resources || 0).toLocaleString()}\n\n**${character.name}'s Inventory (${currentSlots}/${maxSlots}):**\n\n`;
    if (inventory.length === 0) {
        content += `Empty! Find items using \`/search\` or \`/fish\`.`;
    } else {
        pageItems.forEach((item, offset) => {
            const index = start + offset;
            let line;
            if (typeof item === 'string') {
                line = `${index + 1}. ${item}`;
            } else {
                const p = parseItemName(item);
                line = `${index + 1}. ${p.name}`;
                if (item.durability !== undefined && item.maxDurability !== undefined) {
                    line += ` ⚒️ D: ${item.durability}/${item.maxDurability}`;
                }
                if (/(fish|meat)$/i.test(String(item.name || ''))) {
                    if (typeof item.weight === 'number') line += ` (${item.weight} kg)`;
                    if (item.cooked !== true) line += String(item.name || '').toLowerCase().endsWith('meat') ? ' 🍖 (raw)' : ' 🐟 (raw)';
                }
            }
            content += `${line}\n`;
        });
        if (inventory.length > PAGE_SIZE) {
            content += `\n📄 Page **${currentPage + 1}/${maxPage + 1}**`;
        }
    }

    // Fishing Tackle contents (stored fish take up 0 inventory slots).
    if (hasFishingTackle(character)) {
        const tackle = getFishTackle(character);
        const fishCounts = {};
        tackle.forEach(fish => {
            const key = `${fish.name}${fish.cooked ? '' : ' (raw)'}`;
            fishCounts[key] = (fishCounts[key] || 0) + 1;
        });
        content += `\n🎣 **Fishing Tackle** (${tackle.length}/${FISHING_TACKLE_CAPACITY}):\n`;
        if (tackle.length === 0) {
            content += `Empty! Catch fish with \`/fish\` and they'll be stored here for free.\n`;
        } else {
            Object.entries(fishCounts).forEach(([key, count]) => {
                content += `• ${key} ×${count}\n`;
            });
        }
    }

    // Dispose buttons for this page's items (Discord: max 5 rows of 5 buttons).
    const components = [];
    for (let i = 0; i < pageItems.length; i += 5) {
        const row = new ActionRowBuilder();
        pageItems.slice(i, i + 5).forEach((item, offset) => {
            const idx = start + i + offset;
            const name = typeof item === 'string' ? item : (item.name || 'Item');
            row.addComponents(
                new ButtonBuilder()
                    .setCustomId(`inv_dispose_${idx}`)
                    .setLabel(`🗑️ ${String(name).slice(0, 40)}`)
                    .setStyle(ButtonStyle.Danger)
            );
        });
        components.push(row);
    }

    // Page navigation (only shown when there's more than one page).
    if (maxPage > 0) {
        const nav = [];
        if (currentPage > 0) {
            nav.push(new ButtonBuilder().setCustomId(`inv_prev_${currentPage}`).setLabel('◀ Prev').setStyle(ButtonStyle.Secondary));
        }
        if (currentPage < maxPage) {
            nav.push(new ButtonBuilder().setCustomId(`inv_next_${currentPage}`).setLabel('Next ▶').setStyle(ButtonStyle.Secondary));
        }
        if (nav.length > 0) components.push(new ActionRowBuilder().addComponents(nav));
    }

    return { content: clampMessage(content), components };
}

// Fuel cost for a trip of `distance` space slots at a given ship level
function getFuelCost(distance, level) {
    if (distance <= 0) return 0;
    const rate = SHIP_FUEL_PER_1000[level] || SHIP_FUEL_PER_1000[1];
    return Math.max(1, Math.ceil((distance / 1000) * rate));
}

// Space pods are one-way: consume the pod when the trip starts
function consumeSpacePod(userId, character) {
    if (character.spacePod === true) {
        character.spacePod = false;
        characterManager.updateCharacter(userId, character.id, { spacePod: false });
        return true;
    }
    const index = character.inventory.findIndex(item => /space pod|attack ball/i.test(String(typeof item === 'string' ? item : item.name)));
    if (index !== -1) {
        character.inventory.splice(index, 1);
        characterManager.updateCharacter(userId, character.id, { inventory: character.inventory });
        return true;
    }
    return false;
}

